import { Suspense } from "react";
import { Canvas } from "@/components/canvas";
import { MapProvider } from "@/components/map-context";
import { listMaps, loadMap, remoteOf } from "@/lib/maps";
import { STATIC_MAP } from "@/lib/source";

// The open level lives in the URL, and `useSearchParams` needs a Suspense
// boundary to prerender. `?map=` picks which repository's map is read.
export default async function Home({
  searchParams,
}: {
  searchParams: Promise<{ [key: string]: string | string[] | undefined }>;
}) {
  // A static export serves one map and must not read the request.
  const asked = STATIC_MAP ?? (await searchParams).map;
  const { name, file } = loadMap(typeof asked === "string" ? asked : undefined);
  file.RUN.url ??= remoteOf(file.RUN);
  // A published page has no checkout to read, and must not carry this machine's paths.
  if (STATIC_MAP) delete file.RUN.root;
  return (
    <MapProvider name={name} file={file} maps={STATIC_MAP ? [STATIC_MAP] : listMaps()}>
      <Suspense>
        {/* Keyed by map: a switch starts fresh, never mid-transition from the old tree. */}
        <Canvas key={name} />
      </Suspense>
    </MapProvider>
  );
}

ui/components/anatomy.tsx:
"use client";

import { cn } from "@/lib/utils";
import { StateChip } from "@/components/state";
import { rowId, type Anatomy } from "@/lib/data";
import { ShapeView } from "@/components/shapes";
import { ROW_LABEL_MAX_PCT, ROW_VALUE_MIN_PX, type Shape } from "@/lib/view";
import { useCallback, useEffect, useRef, useState } from "react";
import type { Slice, WriteResult } from "@/lib/repo";
import { ExplainedBlock, isExplained } from "@/components/blocks";
import { useMap } from "@/components/map-context";
import { readSource, SOURCE_URL } from "@/lib/source";

/**
 * Level 2 renders in the SHAPE of the thing it describes, and every row is a
 * wire endpoint.
 *
 * The rows are the point. A foreign key wire lands on the exact column it
 * references, not on the card containing it — card-to-card edges say "Billing
 * relates to Database", which is true and nearly contentless. Row-to-row edges
 * answer an actual question.
 *
 * Selection follows the same model: clicking a row lights its chain and greys
 * everything else, so the eye lands on "this value here → that value there".
 */

export interface RowCtx {
  /** Registers a row element as a wire endpoint. */
  anchor: (id: string) => (el: HTMLElement | null) => void;
  /** Rows in the currently traced chain. Empty set = nothing traced. */
  lit: Set<string>;
  /** True while any trace is active, so unlit rows can recede. */
  tracing: boolean;
  onTrace: (id: string) => void;
  /**
   * The row on the open path, if the level below came from a row. Lights the
   * row you drilled through, the same way a card stays selected.
   */
  open: string | null;
  /** Drill into the level this row owns. Same gesture as opening a card. */
  onOpenRow: (id: string) => void;
}

export function AnatomyView({
  owner,
  blocks,
  ctx,
  opened = false,
  shape,
}: {
  owner: string;
  blocks: Anatomy[];
  ctx: RowCtx;
  /**
   * The card's shape, drawn above its rows: something to recognise before
   * reading anything. Optional because it lives on the `Node` and only the
   * canvas has one — a card with nothing true to draw passes nothing, and
   * `ShapeView` itself returns null for a shape it cannot draw honestly.
   */
  shape?: Shape;
  /**
   * True only on the card the reader actually opened to. Everything else on
   * the level is a SIBLING, and a sibling answers a question nobody has asked
   * yet — so its long-form content stays folded until it is chosen.
   *
   * Optional, defaulting to sibling treatment: the caller that knows which
   * card was opened is `components/canvas.tsx`, and until it passes this every
   * card is folded, which is the safe direction to be wrong in.
   */
  opened?: boolean;
}) {
  return (
    <div className="flex flex-col gap-3">
      {shape ? <ShapeView shape={shape} /> : null}
      {blocks.map((block, i) => (
        <Block key={i} owner={owner} block={block} ctx={ctx} opened={opened} />
      ))}
    </div>
  );
}

/**
 * Points right, and turns green when this row's card is open.
 *
 * It does NOT rotate to point down any more. Down means "expands below me",
 * which is what this used to do and is exactly the thing that crushed 700px of
 * flow into a 340px column. The card opens to the RIGHT, so the mark keeps
 * pointing that way and only changes colour.
 */
function Caret({ open }: { open: boolean }) {
  return (
    <svg
      width="9"
      height="9"
      viewBox="0 0 12 12"
      fill="none"
      aria-hidden="true"
      className={cn(
        "shrink-0 transition-colors duration-200",
        open ? "text-deep-green" : "text-faint",
      )}
    >
      <path
        d="M4.5 2.5L8 6l-3.5 3.5"
        stroke="currentColor"
        strokeWidth="1.4"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  );
}

/**
 * The label is the question; the value is the answer. The answer never gets
 * less room than the question.
 *
 * Measured failure this exists to delete: a `map` row 212px wide where the
 * label `what the code does` took 112px — 53% — and the value got 32px,
 * rendering one word per line over twelve lines. The most important comparison
 * on the card was the least readable thing on screen.
 *
 * The cause was a `shrink-0` label beside a `min-w-0 flex-1` value: the only
 * element in the row allowed to give up space was the one carrying the content.
 * A previous fix moved the state chip INSIDE the value column (see the comment
 * that survives in the `map` block), which was real but addressed the wrong
 * element — the label was still unbounded.
 *
 * Two rules from `lib/view.ts`, enforced together:
 *
 *   label ≤ ROW_LABEL_MAX_PCT (40%)   value ≥ ROW_VALUE_MIN_PX (160px)
 *
 * Below a certain row width both cannot hold at once, so rather than squeeze
 * the value under its floor the pair STACKS — label above value, each with the
 * full width. That threshold is a property of the ROW, not of the viewport: a
 * card is a fixed-width column on a canvas that pans, so a viewport breakpoint
 * would tell us nothing about the space this row actually has. Hence a
 * container query.
 *
 * The threshold below is 267px, and it is `ROW_VALUE_MIN_PX / (1 -
 * ROW_LABEL_MAX_PCT/100)` — the narrowest row on which a 40% label still
 * leaves 160px. It is written as a literal in the class strings because
 * Tailwind scans source statically: an interpolated `@min-[${n}px]:` is a
 * class name no build step ever sees, so it would compile to nothing and the
 * row would silently stay stacked at every width. The assertion keeps the
 * literal honest if either constant is ever retuned.
 */
const STACK_BELOW_PX = Math.ceil(ROW_VALUE_MIN_PX / (1 - ROW_LABEL_MAX_PCT / 100));
if (STACK_BELOW_PX !== 267) {
  throw new Error(
    `view.ts row rules changed: the @min-[267px] literals in anatomy.tsx must become @min-[${STACK_BELOW_PX}px]`,
  );
}

/**
 * Every pair row is its own query container. The row, not the card, is what
 * the rules are about — a card can be wide while a row inside a rail or an
 * indent is not.
 */
const PAIR_SCOPE = "@container";

/**
 * Side by side once the row can honour both rules; stacked when it cannot.
 *
 * The percentage cap is a MAX, not a width, so a short label keeps its natural
 * size and does not pad out to 40% leaving the value starved for no reason.
 */
// Each of these is ONE unbroken literal on purpose. Tailwind's scanner reads
// source text, not evaluated JavaScript: splitting a class list across a `+`
// hides every class after the operator, which compiles to nothing and fails
// silently — measured here, where only the one class that stayed inline in JSX
// survived into the stylesheet.
const PAIR_ROW = "flex w-full min-w-0 flex-col items-stretch gap-0.5 @min-[267px]:flex-row @min-[267px]:items-start @min-[267px]:gap-2";

/** The question side. Capped, never allowed to eat the row. */
const PAIR_LABEL = "min-w-0 text-left @min-[267px]:max-w-[40%] @min-[267px]:shrink-0";

/** The answer side. Floored, and it is the only side allowed to grow. */
const PAIR_VALUE = "w-full min-w-0 text-left @min-[267px]:w-auto @min-[267px]:flex-1 @min-[267px]:min-w-[160px]";

/** Shared row chrome: lit fill, dimmed-when-others-are-lit, click to trace. */
function rowClass(id: string, ctx: RowCtx, extra?: string) {
  const isLit = ctx.lit.has(id);
  return cn(
    "w-full text-left transition-all duration-200",
    isLit && "bg-mint-success",
    ctx.tracing && !isLit && "opacity-55",
    !ctx.tracing && "hover:bg-surface-container-low",
    extra,
  );
}

function Block({
  owner,
  block,
  ctx,
  opened,
}: {
  owner: string;
  block: Anatomy;
  ctx: RowCtx;
  opened: boolean;
}) {
  if (block.kind === "schema") {
    return (
      <div className="overflow-hidden rounded-[10px] border border-border-gray bg-pure-white">
        <div className="flex items-center gap-2 border-b border-border-gray bg-surface px-3 py-1.5">
          <TableGlyph />
          <span className="font-mono text-[11px] font-semibold text-ink">
            {block.table}
          </span>
          <span className="ml-auto font-mono text-[10px] text-faint">
            {block.rows.length} columns
          </span>
        </div>
        <div>
          {block.rows.map((c) => {
            const id = rowId(owner, c.name);
            const isLit = ctx.lit.has(id);
            return (
              <button
                key={c.name}
                ref={ctx.anchor(id)}
                data-row
                onClick={() => ctx.onTrace(id)}
                className={rowClass(
                  id,
                  ctx,
                  cn(PAIR_SCOPE, "border-b border-border-gray px-3 py-1.5 last:border-b-0"),
                )}
              >
                {/* The column name, its type and its key are the question; the
                    note is the answer. The note was `truncate` against three
                    `shrink-0` siblings, so it was the one thing on the row
                    guaranteed to be cut — and it wraps now instead. */}
                <span className={PAIR_ROW}>
                  <span className={cn(PAIR_LABEL, "flex items-center gap-2")}>
                    <span
                      className={cn(
                        "min-w-0 font-mono text-[10.5px]",
                        isLit ? "font-semibold text-deep-green" : "text-on-surface",
                      )}
                    >
                      {c.name}
                      {c.nullable ? <span className="text-faint">?</span> : null}
                    </span>
                    <span className="shrink-0 font-mono text-[10.5px] text-muted-slate">
                      {c.type}
                    </span>
                    {c.key ? <KeyTag k={c.key} lit={isLit} /> : null}
                  </span>
                  <span className={cn(PAIR_VALUE, "flex items-start gap-2")}>
                    {c.note ? (
                      <span
                        className={cn(
                          "min-w-0 flex-1 text-[10px] leading-snug @min-[267px]:text-right",
                          c.state === "derived" ? "text-faint" : "text-amber-ink",
                        )}
                      >
                        {c.note}
                      </span>
                    ) : (
                      <span className="min-w-0 flex-1" />
                    )}
                    <StateChip state={c.state} />
                  </span>
                </span>
              </button>
            );
          })}
        </div>
        {block.rel?.length ? (
          <div className="border-t border-border-gray bg-surface-container-low px-3 py-2">
            {block.rel.map((r) => (
              <p
                key={r}
                className="text-[10px] leading-relaxed text-on-surface-variant"
              >
                {r}
              </p>
            ))}
          </div>
        ) : null}
      </div>
    );
  }

  if (block.kind === "routes") {
    return (
      <div className="overflow-hidden rounded-[10px] border border-border-gray bg-pure-white">
        {block.rows.map((r) => {
          const id = rowId(owner, `${r.method} ${r.path}`);
          const isLit = ctx.lit.has(id);
          return (
            <button
              key={r.method + r.path}
              ref={ctx.anchor(id)}
              data-row
              onClick={() => ctx.onTrace(id)}
              className={rowClass(
                id,
                ctx,
                cn(PAIR_SCOPE, "block border-b border-border-gray px-3 py-1.5 last:border-b-0"),
              )}
            >
              {/* The method is the label; the path is the answer, and it was
                  `truncate` — so the one string a reader needs in full was the
                  first thing cut. It wraps now, and the auth note drops to its
                  own line before the path has to give up any width. */}
              <span className={PAIR_ROW}>
                <span className={cn(PAIR_LABEL, "flex items-center gap-2")}>
                  <Method method={r.method} />
                  <span
                    className={cn(
                      "min-w-0 font-mono text-[10.5px] break-all",
                      isLit ? "font-semibold text-deep-green" : "text-on-surface",
                    )}
                  >
                    {r.path}
                  </span>
                </span>
                <span className={cn(PAIR_VALUE, "flex items-start gap-2")}>
                  <span className="min-w-0 flex-1 font-mono text-[9.5px] leading-snug text-faint @min-[267px]:text-right">
                    {r.auth}
                  </span>
                  <StateChip state={r.state} />
                </span>
              </span>
              {r.note ? (
                <span
                  className={cn(
                    "mt-0.5 block pl-[46px] text-[10px] leading-snug",
                    r.state === "derived" ? "text-faint" : "text-amber-ink",
                  )}
                >
                  {r.note}
                </span>
              ) : null}
            </button>
          );
        })}
      </div>
    );
  }

  if (block.kind === "source") {
    return <SourceView owner={owner} block={block} ctx={ctx} />;
  }

  if (isExplained(block)) return <ExplainedBlock block={block} />;

  if (block.kind === "chips") {
    return (
      <div className="rounded-[10px] border border-border-gray bg-pure-white px-3 py-2.5">
        {block.caption ? (
          <p className="mb-2 font-mono text-[9.5px] uppercase tracking-[0.08em] text-faint">
            {block.caption}
          </p>
        ) : null}
        <div className="flex flex-wrap gap-1.5">
          {block.rows.map((c) => {
            const id = rowId(owner, c.label);
            const isLit = ctx.lit.has(id);
            return (
              <button
                key={c.label}
                ref={ctx.anchor(id)}
                data-row
                onClick={() => ctx.onTrace(id)}
                title={c.note}
                className={cn(
                  "rounded-[6px] border px-2 py-1 font-mono text-[10px] transition-all duration-200",
                  ctx.tracing && !isLit && "opacity-55",
                  isLit
                    ? "border-deep-green bg-deep-green text-pure-white"
                    : c.state === "derived"
                      ? "border-mint-line bg-mint-success text-deep-green"
                      : "border-amber-line bg-amber-surface text-amber-ink",
                )}
              >
                {c.label}
              </button>
            );
          })}
        </div>
      </div>
    );
  }

  if (block.kind === "map") {
    return (
      <div className="overflow-hidden rounded-[10px] border border-border-gray bg-pure-white">
        {block.caption ? (
          <div className="border-b border-border-gray bg-surface px-3 py-1.5">
            <span className="font-mono text-[9.5px] uppercase tracking-[0.08em] text-faint">
              {block.caption}
            </span>
          </div>
        ) : null}
        {block.rows.map((m) => {
          const id = rowId(owner, m.from);
          const isLit = ctx.lit.has(id);
          const isOpen = ctx.open === id;
          return (
            <div key={m.from} className="border-b border-border-gray last:border-b-0">
              <button
                ref={ctx.anchor(id)}
                data-row
                // A row that has somewhere to go opens it; one that does not
                // keeps tracing. The same click does the thing the row can
                // actually do, so there is no dead affordance either way.
                // Stop the click here when the row owns a level.
                //
                // The card wrapping these rows is itself clickable, and a real
                // pointer click bubbles: row opens the level, card handler then
                // fires on the SAME click and collapses it again. Measured
                // order was ROW click → CARD click, which is why calling the
                // handler directly worked and every genuine click did nothing.
                onClick={(e) => {
                  if (!m.under) return ctx.onTrace(id);
                  e.stopPropagation();
                  ctx.onOpenRow(id);
                }}
                className={rowClass(id, ctx, cn(PAIR_SCOPE, "px-3 py-1.5"))}
              >
                <span className={PAIR_ROW}>
                  <span className={cn(PAIR_LABEL, "flex items-start gap-2")}>
                    <span
                      className={cn(
                        "min-w-0 rounded-[4px] px-1.5 py-0.5 font-mono text-[10px]",
                        isLit || isOpen
                          ? "bg-deep-green text-pure-white"
                          : "bg-surface-container text-on-surface",
                      )}
                    >
                      {m.from}
                    </span>
                    {/* The arrow carries the relationship, so the text doesn't
                        have to say "becomes". Stacked, it would point down a
                        column at nothing, so it is hidden there — the vertical
                        order already says which is which. */}
                    <span className="ml-auto hidden shrink-0 font-mono text-[11px] leading-[1.5] text-faint @min-[267px]:block">
                      →
                    </span>
                  </span>
                  {/* Chip sits INSIDE the flowing column, not beside it. As a
                      sibling of the text it was `shrink-0` against a `flex-1`
                      that could shrink to nothing, so a long `to` string was
                      squeezed into a five-line ribbon while the chip kept its
                      full width. Inline, the chip wraps with the words. */}
                  <span className={cn(PAIR_VALUE, "flex items-start gap-2")}>
                    <span
                      className={cn(
                        "min-w-0 flex-1 font-mono text-[9.5px] leading-snug",
                        m.state === "derived" ? "text-muted-slate" : "text-amber-ink",
                      )}
                    >
                      {m.to}
                      {m.state !== "derived" ? (
                        <StateChip state={m.state} className="ml-1.5 align-[1px]" />
                      ) : null}
                    </span>
                    {m.under ? (
                      <span className="mt-[3px]">
                        <Caret open={isOpen} />
                      </span>
                    ) : null}
                  </span>
                </span>
              </button>
            </div>
          );
        })}
      </div>
    );
  }

  if (block.kind === "parts") {
    // The ratio IS the finding. Segments are sized by real weight, so a 149KB
    // block next to a 1KB one looks like what it is — no amount of prose makes
    // that land the way a length does.
    const total = block.rows.reduce((sum, p) => sum + p.weight, 0) || 1;
    return (
      <div className="overflow-hidden rounded-[10px] border border-border-gray bg-pure-white">
        <div className="flex items-center gap-2 border-b border-border-gray bg-surface px-3 py-1.5">
          <span className="font-mono text-[11px] font-semibold text-ink">
            {block.total}
          </span>
          <span className="ml-auto font-mono text-[10px] text-faint">
            {block.rows.length} parts
          </span>
        </div>
        <div className="px-3 pb-2.5 pt-2.5">
          <div className="flex h-[22px] w-full overflow-hidden rounded-[5px]">
            {block.rows.map((p, at) => {
              const id = rowId(owner, p.label);
              const isLit = ctx.lit.has(id);
              return (
                <button
                  key={p.label}
                  ref={ctx.anchor(id)}
                  data-row
                  onClick={() => ctx.onTrace(id)}
                  title={`${p.label} — ${p.display}`}
                  // Floored at 6%: a slice worth naming has to be visible, and
                  // a 1%-of-the-whole block rendered ~2px wide — present in the
                  // DOM, absent to the eye. The exact figure is in the legend;
                  // the bar's job is the contrast, not the arithmetic.
                  style={{ width: `${Math.max((p.weight / total) * 100, 6)}%` }}
                  className={cn(
                    "h-full border-r border-pure-white transition-all duration-200 last:border-r-0",
                    ctx.tracing && !isLit && "opacity-45",
                    isLit
                      ? "bg-deep-green"
                      : p.tone === "vary"
                        ? "bg-amber-line"
                        : // Alternating weights within the same family. Every
                          // "hold" slice sharing one mint made a 198px and a
                          // 33px segment read as a single bar with a hairline
                          // seam — measured, not guessed. The ratio only lands
                          // if adjacent slices are separable.
                          at % 2 === 0
                          ? "bg-deep-green/55"
                          : "bg-mint-line",
                  )}
                />
              );
            })}
          </div>
          {/* Legend, not a table: label and size on one line each. */}
          <ul className="mt-2 flex flex-col gap-1">
            {block.rows.map((p, at) => {
              const id = rowId(owner, p.label);
              const isLit = ctx.lit.has(id);
              return (
                <li key={p.label} className="flex items-center gap-2">
                  <span
                    // Same tone rule as the bar segment above, index included.
                    // A swatch is only a key if it is the colour it explains.
                    className={cn(
                      "size-[7px] shrink-0 rounded-[2px]",
                      isLit
                        ? "bg-deep-green"
                        : p.tone === "vary"
                          ? "bg-amber-line"
                          : at % 2 === 0
                            ? "bg-deep-green/55"
                            : "bg-mint-line",
                    )}
                  />
                  <span
                    className={cn(
                      // `min-w-0` so a long label wraps instead of shoving the
                      // figure past the right edge. The figure stays `shrink-0`
                      // because it is short and is the thing being compared.
                      "min-w-0 font-mono text-[10px]",
                      isLit ? "font-semibold text-deep-green" : "text-on-surface",
                    )}
                  >
                    {p.label}
                  </span>
                  <span className="ml-auto shrink-0 font-mono text-[10px] text-muted-slate">
                    {p.display}
                  </span>
                  <StateChip state={p.state} />
                </li>
              );
            })}
          </ul>
        </div>
      </div>
    );
  }

  if (block.kind === "bars") {
    // Comparison, not enumeration. Bars share one scale so the 250x gap
    // between an anonymous and a premium quota is visible rather than stated.
    const max = Math.max(...block.rows.map((b) => b.value), 1);
    return (
      <div className="overflow-hidden rounded-[10px] border border-border-gray bg-pure-white">
        <div className="flex items-center gap-2 border-b border-border-gray bg-surface px-3 py-1.5">
          <span className="font-mono text-[10px] uppercase tracking-[0.08em] text-faint">
            {block.unit}
          </span>
        </div>
        <div className="flex flex-col gap-1.5 px-3 py-2.5">
          {block.rows.map((b) => {
            const id = rowId(owner, b.label);
            const isLit = ctx.lit.has(id);
            return (
              <button
                key={b.label}
                ref={ctx.anchor(id)}
                data-row
                onClick={() => ctx.onTrace(id)}
                className={rowClass(id, ctx, cn(PAIR_SCOPE, "rounded-[5px]"))}
              >
                {/* The label was `w-[92px]` and the figure `w-[108px]`: 200px
                    of fixed furniture either side of the bar, so on a narrow
                    card the TRACK — the only part that carries the comparison
                    — was what collapsed. Both are capped shares now, and the
                    pair stacks before the bar can be squeezed out. */}
                <span className={PAIR_ROW}>
                  <span
                    className={cn(
                      PAIR_LABEL,
                      "truncate font-mono text-[10px]",
                      isLit ? "font-semibold text-deep-green" : "text-on-surface",
                    )}
                  >
                    {b.label}
                  </span>
                  <span className={cn(PAIR_VALUE, "flex items-center gap-2")}>
                    {/* The track is the scale. Without it a short bar reads as
                        a small number rather than a small share. */}
                    <span className="h-[9px] min-w-0 flex-1 rounded-[3px] bg-surface-container">
                      <span
                        style={{ width: `${Math.max((b.value / max) * 100, 2)}%` }}
                        className={cn(
                          "block h-full rounded-[3px] transition-all duration-200",
                          isLit
                            ? "bg-deep-green"
                            : b.state === "derived"
                              ? "bg-mint-line"
                              : "bg-amber-line",
                        )}
                      />
                    </span>
                    <span className="shrink-0 text-right font-mono text-[9.5px] text-muted-slate">
                      {b.display}
                    </span>
                    <StateChip state={b.state} />
                  </span>
                </span>
              </button>
            );
          })}
        </div>
      </div>
    );
  }

  if (block.kind === "flow") {
    return (
      <ol className="flex flex-col">
        {block.rows.map((s, i) => {
          const id = rowId(owner, s.n);
          const isLit = ctx.lit.has(id);
          return (
            <li key={s.n} className="flex gap-2.5">
              {/* The rail: a numbered dot with a line to the next step, so the
                  sequence reads as one path rather than four cards. */}
              <div className="flex flex-col items-center">
                <span
                  className={cn(
                    "flex size-[18px] shrink-0 items-center justify-center rounded-full border font-mono text-[9px] font-semibold transition-colors",
                    isLit
                      ? "border-deep-green bg-deep-green text-pure-white"
                      : s.state === "derived"
                        ? "border-mint-line bg-mint-success text-deep-green"
                        : "border-amber-line bg-amber-surface text-amber-ink",
                  )}
                >
                  {s.n}
                </span>
                {i < block.rows.length - 1 ? (
                  <span className="w-px flex-1 bg-border-gray" />
                ) : null}
              </div>
              <button
                ref={ctx.anchor(id)}
                data-row
                // See the map row above: the click must not reach the card.
                onClick={(e) => {
                  if (!s.under) return ctx.onTrace(id);
                  e.stopPropagation();
                  ctx.onOpenRow(id);
                }}
                className={rowClass(
                  id,
                  ctx,
                  cn(
                    "min-w-0 flex-1 rounded-[6px] px-1.5 py-0.5",
                    i < block.rows.length - 1 && "mb-2.5",
                  ),
                )}
              >
                <span className="flex items-center gap-1.5">
                  <span
                    className={cn(
                      "text-[11px] font-semibold leading-tight",
                      isLit || ctx.open === id ? "text-deep-green" : "text-ink",
                    )}
                  >
                    {s.title}
                  </span>
                  <StateChip state={s.state} />
                  {s.under ? (
                    <span className="ml-auto">
                      <Caret open={ctx.open === id} />
                    </span>
                  ) : null}
                </span>
                {/* A step that has somewhere to go shows its TITLE and nothing
                    else. Its `detail` is the level behind the click, and
                    printing it here painted the next level onto this one — 226
                    words on this card alone, measured, of which four paragraphs
                    were the four children it already had.

                    A step with no `under` keeps its line, because for that row
                    there is no deeper level to defer to and the sentence is the
                    whole fact. See LEVEL_WORD_BUDGET in lib/view.ts. */}
                {s.under ? null : (
                  <span className="mt-0.5 block text-[10px] leading-relaxed text-on-surface-variant">
                    {s.detail}
                  </span>
                )}
              </button>
            </li>
          );
        })}
      </ol>
    );
  }

  return <Facts owner={owner} block={block} ctx={ctx} opened={opened} />;
}

/**
 * Facts fold past FACTS_VISIBLE on a card nobody opened.
 *
 * The rest are not dropped — they are one click away, on the same card, and
 * the count says exactly how many are waiting. A sibling card's job is to say
 * WHAT it holds so the reader can choose it; enumerating every pair is the
 * document behaviour this level is supposed to stop being.
 */
const FACTS_VISIBLE = 3;

function Facts({
  owner,
  block,
  ctx,
  opened,
}: {
  owner: string;
  block: Extract<Anatomy, { kind: "facts" }>;
  ctx: RowCtx;
  opened: boolean;
}) {
  const [expanded, setExpanded] = useState(false);
  // The opened card shows everything; a sibling folds unless the reader asked.
  const folded = !opened && !expanded && block.rows.length > FACTS_VISIBLE;
  const rows = folded ? block.rows.slice(0, FACTS_VISIBLE) : block.rows;
  const hidden = block.rows.length - rows.length;

  return (
    <div className="overflow-hidden rounded-[10px] border border-border-gray bg-pure-white">
      {rows.map((p) => {
        const id = rowId(owner, p.label);
        const isLit = ctx.lit.has(id);
        return (
          <button
            key={p.label}
            ref={ctx.anchor(id)}
            data-row
            onClick={() => ctx.onTrace(id)}
            className={rowClass(
              id,
              ctx,
              cn(PAIR_SCOPE, "border-b border-border-gray px-3 py-1.5 last:border-b-0"),
            )}
          >
            <span className={PAIR_ROW}>
              <span
                className={cn(
                  PAIR_LABEL,
                  "font-mono text-[10.5px]",
                  isLit ? "font-semibold text-deep-green" : "text-on-surface",
                )}
              >
                {p.label}
              </span>
              {/* Left-aligned: right-aligning a long value in a narrow column
                  produces a ragged staircase of 3-4 wrapped lines. */}
              <span className={cn(PAIR_VALUE, "flex items-start gap-2")}>
                <span
                  className={cn(
                    "min-w-0 flex-1 text-[10px] leading-snug",
                    p.state === "derived" ? "text-muted-slate" : "text-amber-ink",
                  )}
                >
                  {p.value}
                </span>
                <StateChip state={p.state} />
              </span>
            </span>
          </button>
        );
      })}
      {/* Nothing is thrown away: the count is the affordance, and the rows it
          names are one click down on this same card. */}
      {hidden > 0 ? (
        <button
          onClick={(e) => {
            // The card behind this is itself clickable, and a real click
            // bubbles — without this the card would collapse the level on the
            // same gesture that expanded the facts. Same reason as the map and
            // flow rows above.
            e.stopPropagation();
            setExpanded(true);
          }}
          className="flex w-full items-center gap-1.5 border-t border-border-gray bg-surface-container-low px-3 py-1.5 text-left transition-colors hover:bg-surface-container"
        >
          <span className="font-mono text-[9.5px] text-muted-slate">
            {hidden} more {hidden === 1 ? "fact" : "facts"}
          </span>
          <span className="ml-auto">
            <Caret open={false} />
          </span>
        </button>
      ) : null}
    </div>
  );
}

/**
 * The bottom of the map, read from the real repository.
 *
 * Three things are kept strictly apart, and the separation is the point:
 *
 *   the CODE       verbatim from a real file at a real line, read from disk
 *   the WHY        synthesized commentary, in its own tinted band
 *   the FINDING    when disk no longer says what the map quoted
 *
 * The fixture's text is still what renders first, so the card is readable
 * before any request finishes and readable at all if the repo is not there.
 * Once the read lands, disk wins — with a mark saying it drifted, if it did.
 * Silently swapping fresh code under a stale explanation is the exact failure
 * this project exists to study, so it is the one thing that cannot happen here.
 */
export function SourceView({
  owner,
  block,
  ctx,
}: {
  owner: string;
  block: Extract<Anatomy, { kind: "source" }>;
  ctx: RowCtx;
}) {
  const id = rowId(owner, "source");
  const isLit = ctx.lit.has(id);

  const quoted = block.code.replace(/\n$/, "");
  const end = block.start + quoted.split("\n").length - 1;

  const [slice, setSlice] = useState<Slice | null>(null);
  const [failed, setFailed] = useState<string | null>(null);
  const [editing, setEditing] = useState(false);
  const [draft, setDraft] = useState(quoted);
  const [saved, setSaved] = useState<WriteResult | null>(null);
  const { name: map } = useMap();

  /**
   * One read of the repository, resolved to what the UI should show.
   *
   * Pure apart from the fetch: it sets no state, which is what lets the effect
   * below subscribe to it rather than call setState in its own body.
   */
  const read = useCallback(
    async (signal?: AbortSignal) => {
      try {
        const r = await readSource({ map, file: block.file, start: block.start, end, fixture: quoted }, signal);
        return "slice" in r ? { slice: r.slice, failed: null } : { slice: null, failed: r.refused };
      } catch {
        return { slice: null, failed: "unreachable" };
      }
    },
    [map, block.file, block.start, end, quoted],
  );

  // Aborted on unmount and whenever the block changes, so a slow response for
  // one source block can never land as the state of a different one.
  useEffect(() => {
    const ac = new AbortController();
    read(ac.signal).then((r) => {
      if (ac.signal.aborted) return;
      setSlice(r.slice);
      setFailed(r.failed);
    });
    return () => ac.abort();
  }, [read]);

  // Disk is the truth once we have it; the fixture is the fallback.
  const shown = slice?.code ?? quoted;
  const lines = shown.split("\n");
  const drifted = slice != null && !slice.matchesFixture;

  // Nothing is ever written without an explicit click, so this is only ever
  // reached from the save button's own handler. Never a blur, never a timer,
  // never navigation.
  async function save() {
    const res = await fetch("/api/source", {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({
        map,
        file: block.file,
        start: block.start,
        end,
        code: draft,
        // What we read is what we claim is there. A write built on anything
        // else is the stale-read clobber the contract exists to refuse.
        expected: shown,
      }),
    });
    const body = (await res.json()) as WriteResult;
    setSaved(body);
    if (body.ok) {
      setEditing(false);
      // Re-read rather than trusting the draft: what is now on disk is the
      // only thing this card is allowed to show as the file's contents.
      const r = await read();
      setSlice(r.slice);
      setFailed(r.failed);
    }
  }

  return (
    <div
      className={cn(
        "overflow-hidden rounded-[10px] border bg-pure-white",
        drifted ? "border-amber-line" : isLit ? "border-deep-green" : "border-border-gray",
      )}
    >
      <div
        className={cn(
          "flex items-center gap-2 border-b border-border-gray px-3 py-1.5",
          drifted ? "bg-amber-surface" : "bg-surface",
        )}
      >
        <button
          ref={ctx.anchor(id)}
          data-row
          onClick={() => ctx.onTrace(id)}
          className={rowClass(id, ctx, "flex min-w-0 flex-1 items-center gap-2 rounded-[5px]")}
        >
          <FileGlyph />
          {/* file:line as one addressable string, not a path with a number
              stranded on the far side of the row. */}
          <span
            className={cn(
              "min-w-0 truncate text-left font-mono text-[11px]",
              isLit ? "font-semibold text-deep-green" : "text-on-surface",
            )}
          >
            {block.file}
            <span className="text-faint">:{block.start}</span>
          </span>
        </button>
        {/* "733 of 779 lines" — where this sits in the file, which a quote
            with no denominator cannot say. */}
        {slice ? (
          <span className="tnum shrink-0 font-mono text-[9.5px] text-faint">
            {block.start.toLocaleString()} of {slice.total.toLocaleString()} lines
          </span>
        ) : null}
        <CopyPath text={`${block.file}:${block.start}`} />
        {/* A static export has no repository to write to: it links to the code host instead. */}
        {SOURCE_URL ? (
          <a
            href={`${SOURCE_URL}/${block.file}#L${block.start}-L${end}`}
            target="_blank"
            rel="noreferrer"
            onClick={(e) => e.stopPropagation()}
            className="shrink-0 rounded-[4px] border border-border-strong px-1.5 py-0.5 font-mono text-[9px] text-muted-slate transition-colors hover:text-on-surface"
          >
            github ↗
          </a>
        ) : (
          /* Read-only is the default. Editing is a control you go and press. */
          <button
            onClick={(e) => {
              e.stopPropagation();
              setDraft(shown);
              setSaved(null);
              setEditing((v) => !v);
            }}
            className={cn(
              "shrink-0 rounded-[4px] border px-1.5 py-0.5 font-mono text-[9px] transition-colors",
              editing
                ? "border-deep-green bg-deep-green text-pure-white"
                : "border-border-strong text-muted-slate hover:text-on-surface",
            )}
          >
            {editing ? "cancel" : "edit"}
          </button>
        )}
      </div>

      {/* The finding, stated before the code it is about. */}
      {drifted ? (
        <p className="border-b border-amber-line bg-amber-surface px-3 py-1.5 text-[10px] leading-relaxed text-amber-ink">
          <span className="font-semibold">Drifted.</span> The file no longer says
          what the map quoted here. The code below is what is on disk now; the
          explanation under it was written about the older text.
        </p>
      ) : null}
      {failed ? (
        <p className="border-b border-border-gray bg-surface-container-low px-3 py-1.5 text-[10px] leading-relaxed text-muted-slate">
          Could not read the repository ({failed}). Showing the quote the map
          was authored with, which nothing has verified against disk.
        </p>
      ) : null}

      {editing ? (
        <div className="px-3 py-2">
          <textarea
            value={draft}
            onChange={(e) => setDraft(e.target.value)}
            spellCheck={false}
            rows={Math.min(lines.length + 2, 24)}
            className="w-full resize-y rounded-[6px] border border-border-strong bg-surface-container-low p-2 font-mono text-[11.5px] leading-[1.55] text-on-surface outline-none focus:border-deep-green"
          />
          {/* The diff is shown BEFORE the write, and the write needs this
              click. There is no other path to disk. */}
          <div className="mt-2 flex items-center gap-2">
            <button
              onClick={(e) => {
                e.stopPropagation();
                void save();
              }}
              disabled={draft === shown}
              className="rounded-[5px] bg-deep-green px-2 py-1 font-mono text-[10px] text-pure-white disabled:opacity-40"
            >
              save to disk
            </button>
            <span className="font-mono text-[9.5px] text-faint">
              {draft === shown
                ? "no change"
                : `rewrites ${block.file}:${block.start}-${end}`}
            </span>
          </div>
          {draft !== shown ? <DraftDiff before={shown} after={draft} /> : null}
          {saved && !saved.ok ? (
            <p className="mt-2 text-[10px] leading-relaxed text-clay-ink">
              Refused: {saved.refused}
              {saved.refused === "stale"
                ? " — the file changed since this was read. Cancel and reopen to get the current text."
                : null}
            </p>
          ) : null}
        </div>
      ) : (
        /* Real line numbers, counting from the file's own offset. A gutter
           that restarts at 1 is a quiet lie about where this code lives. */
        <div className="overflow-x-auto">
          <pre className="min-w-full py-1.5 font-mono text-[11.5px] leading-[1.55]">
            {lines.map((line, i) => (
              <div key={i} className="flex">
                <span className="tnum sticky left-0 shrink-0 select-none border-r border-border-gray bg-pure-white pl-3 pr-2 text-right text-faint">
                  {block.start + i}
                </span>
                <code className="whitespace-pre pl-2.5 pr-3 text-on-surface">
                  {line || " "}
                </code>
              </div>
            ))}
          </pre>
        </div>
      )}

      {/* Commentary, in its own band, below the code, labelled. It is
          synthesized and must never be able to read as something the file
          says. */}
      {block.why ? (
        <div className="flex gap-2 border-t border-border-gray bg-surface-container-low px-3 py-2">
          <span className="mt-[3px] shrink-0 font-mono text-[9px] uppercase tracking-[0.09em] text-faint">
            why
          </span>
          <p className="text-[10px] leading-relaxed text-on-surface-variant">
            {block.why}
          </p>
        </div>
      ) : null}
    </div>
  );
}

/** Line-wise diff of the pending edit, shown before anything is written. */
function DraftDiff({ before, after }: { before: string; after: string }) {
  const b = before.split("\n");
  const a = after.split("\n");
  return (
    <pre className="mt-2 overflow-x-auto rounded-[6px] border border-border-gray bg-pure-white py-1.5 font-mono text-[10.5px] leading-[1.5]">
      {b.map((l, i) => (
        <div key={`b${i}`} className="bg-clay-surface px-3 text-clay-ink">
          <span className="select-none">- </span>
          {l || " "}
        </div>
      ))}
      {a.map((l, i) => (
        <div key={`a${i}`} className="bg-mint-success px-3 text-deep-green">
          <span className="select-none">+ </span>
          {l || " "}
        </div>
      ))}
    </pre>
  );
}

/** Copies `file:line`, the string you paste into an editor or a message. */
function CopyPath({ text }: { text: string }) {
  const [done, setDone] = useState(false);
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);
  useEffect(() => () => void (timer.current && clearTimeout(timer.current)), []);
  return (
    <button
      onClick={(e) => {
        e.stopPropagation();
        void navigator.clipboard.writeText(text);
        setDone(true);
        timer.current = setTimeout(() => setDone(false), 1200);
      }}
      title={`Copy ${text}`}
      className="shrink-0 rounded-[4px] border border-border-strong px-1.5 py-0.5 font-mono text-[9px] text-muted-slate transition-colors hover:text-on-surface"
    >
      {done ? "copied" : "copy path"}
    </button>
  );
}

function KeyTag({ k, lit }: { k: "PK" | "FK" | "UQ"; lit?: boolean }) {
  return (
    <span
      className={cn(
        "shrink-0 rounded-[4px] px-1 py-px font-mono text-[8.5px] font-semibold leading-none",
        lit
          ? "bg-pure-white text-deep-green ring-1 ring-deep-green/45"
          : k === "PK"
            ? "bg-mint-success text-deep-green"
            : "bg-surface-container text-muted-slate",
      )}
    >
      {k}
    </span>
  );
}

const METHOD_TONE: Record<string, string> = {
  GET: "bg-surface-container text-muted-slate",
  POST: "bg-mint-success text-deep-green",
  PATCH: "bg-amber-surface text-amber-ink",
  DELETE: "bg-clay-surface text-clay-ink",
};

function Method({ method }: { method: string }) {
  return (
    <span
      className={cn(
        "w-[42px] shrink-0 rounded-[4px] px-1 py-px text-center font-mono text-[8.5px] font-semibold leading-[1.4]",
        METHOD_TONE[method],
      )}
    >
      {method}
    </span>
  );
}

function FileGlyph() {
  return (
    <svg width="11" height="11" viewBox="0 0 12 12" fill="none" aria-hidden="true">
      <path
        d="M3 1.5h3.5L9 4v6.5H3z"
        stroke="currentColor"
        strokeWidth="1"
        strokeLinejoin="round"
        className="text-muted-slate"
      />
      <path d="M6.4 1.6V4.2H9" stroke="currentColor" strokeWidth="1" strokeLinejoin="round" className="text-muted-slate" />
    </svg>
  );
}

function TableGlyph() {
  return (
    <svg width="11" height="11" viewBox="0 0 12 12" fill="none" aria-hidden="true">
      <rect x="1" y="1.5" width="10" height="9" rx="1.5" stroke="currentColor" strokeWidth="1" className="text-muted-slate" />
      <path d="M1 4.5h10M4.5 4.5v6" stroke="currentColor" strokeWidth="1" className="text-muted-slate" />
    </svg>
  );
}

ui/components/blocks.tsx:
"use client";

import { useState } from "react";
import { cn } from "@/lib/utils";
import { Eyebrow, Prose } from "@/components/state";
import { SourceView, type RowCtx } from "@/components/anatomy";
import type { Anatomy, CodeRef, Issue } from "@/lib/data";
import type { Slice as RepoSlice } from "@/lib/repo";
import { useMap } from "@/components/map-context";
import { readSource } from "@/lib/source";
import { BOX_H, CUE_ROOM, layoutDiagram } from "@/lib/diagram";

/**
 * The blocks a reader learns from without opening code (round 3, D34): the
 * picture, the real values, who talks to whom, what is on screen, what a stored
 * value looks like. Typeset at reading size for the open level — unlike the
 * older anatomy blocks, which were built for a 340px card and are zoomed up.
 */

export type Explained = Extract<
  Anatomy,
  { kind: "diagram" | "table" | "sequence" | "screen" | "example" }
>;

export function isExplained(b: Anatomy): b is Explained {
  return ["diagram", "table", "sequence", "screen", "example"].includes(b.kind);
}

export function ExplainedBlock({
  block,
  onOpen,
  hrefFor,
}: {
  block: Explained;
  /** Opens the part a diagram box names (D40). Absent where a block is drawn
      inside a card, which has no room to be navigated from. */
  onOpen?: (id: string) => void;
  /** That part's own URL, so a box is a real link: focusable, and openable
      in a new tab like any other. */
  hrefFor?: (id: string) => string;
}) {
  switch (block.kind) {
    case "diagram":
      return <Diagram block={block} onOpen={onOpen} hrefFor={hrefFor} />;
    case "table":
      return <Table block={block} />;
    case "sequence":
      return <Sequence block={block} />;
    case "screen":
      return <Screen block={block} />;
    case "example":
      return <Example block={block} />;
  }
}

function Caption({ children }: { children?: string }) {
  return children ? (
    <p className="mb-2.5 text-[13px] font-medium text-on-surface-variant">{children}</p>
  ) : null;
}

/* ── diagram ─────────────────────────────────────────────────── */

const TONE = {
  plain: { stroke: "var(--color-border-strong)", fill: "var(--color-pure-white)", ink: "var(--color-ink)", line: "var(--color-wire)" },
  good: { stroke: "var(--color-deep-green)", fill: "var(--color-mint-success)", ink: "var(--color-ink)", line: "var(--color-deep-green)" },
  warn: { stroke: "var(--color-amber-ink)", fill: "var(--color-amber-surface)", ink: "var(--color-amber-ink)", line: "var(--color-amber-ink)" },
} as const;

/**
 * Boxes on a grid, arrows routed between them. Drawn at real pixels and never
 * scaled down: a figure whose labels shrink below reading size is decoration
 * (the measured failure in `Figure`), so a wide one scrolls instead.
 */
function Diagram({
  block,
  onOpen,
  hrefFor,
}: {
  block: Extract<Anatomy, { kind: "diagram" }>;
  onOpen?: (id: string) => void;
  hrefFor?: (id: string) => string;
}) {
  const { W, H, boxes, arrows } = layoutDiagram(block);
  // Only a picture that actually leads somewhere dims its scenery: on a
  // diagram where nothing opens, every box is equally "inert" and dimming
  // them all would just make the picture grey.
  const navigable = Boolean(onOpen) && block.boxes.some((b) => b.opens);

  return (
    <figure className="min-w-0">
      {/* No frame: the picture is the level, not an illustration pasted onto
          it (D41). A border here drew a box around the one thing that should
          read as the page itself. */}
      <div className="overflow-x-auto">
        {/* Scales down to fit the page — but never below 70%, where the
            labels stop being readable; past that the frame scrolls. */}
        <svg
          viewBox={`0 0 ${W} ${H}`}
          role="img"
          aria-label={block.caption}
          className={navigable ? "dg-nav block h-auto" : "block h-auto"}
          style={{ width: "100%", maxWidth: W, minWidth: W * 0.7 }}
        >
          <defs>
            {(["plain", "good", "warn"] as const).map((t) => (
              <marker
                key={t}
                id={`dg-${t}`}
                viewBox="0 0 8 8"
                refX="7"
                refY="4"
                markerWidth="7"
                markerHeight="7"
                orient="auto-start-reverse"
              >
                <path d="M1 1.2L7 4 1 6.8z" fill={TONE[t].line} />
              </marker>
            ))}
          </defs>
          {arrows.map(({ d, tone, label }, i) => (
            <g key={i}>
              <path
                d={d}
                fill="none"
                stroke={TONE[tone].line}
                strokeWidth="1.5"
                strokeDasharray={tone === "warn" ? "5 4" : undefined}
                markerEnd={`url(#dg-${tone})`}
              />
              {label ? (
                <text
                  x={label.x}
                  y={label.y}
                  textAnchor={label.anchor}
                  fontSize="12"
                  fill="var(--color-muted-slate)"
                  stroke="var(--color-warm-cream)"
                  strokeWidth="4"
                  strokeLinejoin="round"
                  paintOrder="stroke"
                >
                  {label.text}
                </text>
              ) : null}
            </g>
          ))}
          {boxes.map(({ x, y, w, b }) => {
            const t = TONE[b.tone ?? "plain"];
            // Live only where the author named the part this box belongs to.
            const go = b.opens && onOpen ? () => onOpen(b.opens!) : undefined;
            return (
              <Box
                key={b.id}
                live={Boolean(go)}
                href={b.opens ? hrefFor?.(b.opens) : undefined}
                onActivate={go}
                label={b.label}
              >
                <rect
                  x={x}
                  y={y}
                  width={w}
                  height={BOX_H}
                  rx="10"
                  fill={t.fill}
                  stroke={t.stroke}
                  strokeWidth="1.5"
                  strokeDasharray={b.tone === "warn" ? "5 4" : undefined}
                />
                {/* The label centres in the space left of the badge, so a
                    long one never runs under it. */}
                <text
                  x={x + (w - (b.opens ? CUE_ROOM : 0)) / 2}
                  y={b.sub ? y + 25 : y + BOX_H / 2 + 5}
                  textAnchor="middle"
                  fontSize="14.5"
                  fontWeight="600"
                  fill={t.ink}
                >
                  {b.label}
                </text>
                {b.sub ? (
                  <text x={x + w / 2} y={y + 43} textAnchor="middle" fontSize="12" fill="var(--color-faint)">
                    {b.sub}
                  </text>
                ) : null}
                {/* The cue that this box goes somewhere. A filled disc in the
                    corner rather than a bare character: at rest a lone "›"
                    read as decoration, so the click was only discoverable by
                    hovering (D43). */}
                {go ? (
                  <g className="dg-cue" aria-hidden>
                    {/* Green, not the box's own stroke: the accent colour is
                        what reads as "this does something" everywhere else
                        on the page, and it stays legible on a warn-tinted
                        box where the stroke is amber. */}
                    <circle cx={x + w - 15} cy={y + 15} r="8.5" fill="var(--color-deep-green)" />
                    <text
                      x={x + w - 15}
                      y={y + 19}
                      textAnchor="middle"
                      fontSize="11"
                      fontWeight="700"
                      fill="var(--color-pure-white)"
                    >
                      ›
                    </text>
                  </g>
                ) : null}
              </Box>
            );
          })}
        </svg>
      </div>
      <figcaption className="mt-2 text-[13px] text-muted-slate">{block.caption}</figcaption>
    </figure>
  );
}

/**
 * One diagram box. A box that opens a part is an <a> so that focus, Enter and
 * a screen reader all work: Chrome refuses focus to an SVG <g>, tabIndex or
 * not, which would have left the picture mouse-only. An inert box is a plain
 * <g> and announces nothing extra.
 */
function Box({
  live,
  href,
  onActivate,
  label,
  children,
}: {
  live: boolean;
  /** A real destination, so the link focuses and Enter fires natively. */
  href?: string;
  onActivate?: () => void;
  label: string;
  children: React.ReactNode;
}) {
  if (!live) return <g>{children}</g>;
  return (
    <a
      className="dg-live"
      href={href}
      aria-label={`${label} — open this part`}
      onClick={(e) => {
        // Left-click navigates in place; cmd/ctrl-click and the context menu
        // keep the browser's own behaviour, because the href is real.
        if (e.metaKey || e.ctrlKey || e.shiftKey || e.button !== 0) return;
        e.preventDefault();
        onActivate?.();
      }}
      onKeyDown={(e) => {
        if (e.key === " ") {
          e.preventDefault();
          onActivate?.();
        }
      }}
    >
      {children}
    </a>
  );
}

/* ── table ───────────────────────────────────────────────────── */

const TABLE_ROWS_FOLDED = 12;

function Table({ block }: { block: Extract<Anatomy, { kind: "table" }> }) {
  const [all, setAll] = useState(false);
  const rows = all ? block.rows : block.rows.slice(0, TABLE_ROWS_FOLDED);
  return (
    <div className="min-w-0">
      <Caption>{block.caption}</Caption>
      <div className="overflow-x-auto rounded-[12px] border border-border-gray bg-pure-white">
        <table className="w-full border-collapse text-left text-[13.5px]">
          <thead>
            <tr className="border-b border-border-gray bg-surface">
              {block.columns.map((c) => (
                <th key={c} className="px-4 py-2 font-mono text-[10.5px] font-medium uppercase tracking-[0.07em] text-faint">
                  {c}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {rows.map((r, i) => (
              <tr key={i} className="border-b border-border-gray last:border-0">
                {r.map((cell, j) => (
                  <td
                    key={j}
                    className={cn(
                      "px-4 py-2 align-top leading-snug",
                      j === 0 ? "font-medium text-ink" : "text-on-surface-variant",
                    )}
                  >
                    {cell}
                  </td>
                ))}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      {block.rows.length > TABLE_ROWS_FOLDED ? (
        <button
          onClick={() => setAll((v) => !v)}
          className="mt-2 text-[12.5px] font-medium text-deep-green hover:underline"
        >
          {all ? "Show fewer" : `Show all ${block.rows.length}`}
        </button>
      ) : null}
    </div>
  );
}

/* ── sequence ────────────────────────────────────────────────── */

/**
 * Who talks to whom, top to bottom. One column per actor with a faint line
 * down from it; each message is an arrow between two of those lines, numbered,
 * with its words on top. A message to itself is a note on that actor's line.
 */
function Sequence({ block }: { block: Extract<Anatomy, { kind: "sequence" }> }) {
  const n = block.actors.length;
  const centre = (a: string) => ((block.actors.indexOf(a) + 0.5) / n) * 100;
  return (
    <div className="min-w-0">
      <Caption>{block.caption}</Caption>
      <div className="overflow-x-auto rounded-[14px] border border-border-gray bg-pure-white/80 px-4 pb-4 pt-3">
        <div className="relative" style={{ minWidth: n * 150 }}>
          {/* lifelines */}
          {block.actors.map((a) => (
            <span
              key={a}
              aria-hidden
              className="absolute bottom-0 top-9 border-l border-dashed border-border-strong"
              style={{ left: `${centre(a)}%` }}
            />
          ))}
          <div className="relative flex">
            {block.actors.map((a) => (
              <div key={a} className="flex flex-1 justify-center">
                <span className="rounded-[8px] border border-border-strong bg-surface px-3 py-1.5 text-[13px] font-semibold text-ink">
                  {a}
                </span>
              </div>
            ))}
          </div>
          <ol className="relative mt-3">
            {block.rows.map((m, i) => {
              const a = centre(m.from);
              const b = centre(m.to);
              const self = m.from === m.to;
              const left = Math.min(a, b);
              const width = Math.abs(b - a);
              const warn = m.state !== "derived";
              return (
                <li key={i} className="relative h-[76px]">
                  <span className="absolute bottom-[14px] left-0 font-mono text-[10.5px] text-faint">{i + 1}</span>
                  {self ? (
                    <div
                      className="absolute top-[8px] -translate-x-1/2 rounded-[8px] border border-border-gray bg-surface-container-low px-2.5 py-1.5 text-center text-[12.5px] text-on-surface"
                      style={{ left: `${a}%`, maxWidth: `${100 / n}%` }}
                    >
                      {m.label}
                      {m.note ? <span className="block text-[11.5px] text-faint">{m.note}</span> : null}
                    </div>
                  ) : (
                    <div className="absolute bottom-[18px]" style={{ left: `${left}%`, width: `${width}%` }}>
                      <p className="line-clamp-2 px-3 text-center text-[12.5px] leading-tight text-on-surface" title={m.label}>
                        {m.label}
                      </p>
                      <div className={cn("relative mt-1.5 h-0 border-t-[1.5px]", warn ? "border-dashed border-amber-ink" : "border-deep-green/70")}>
                        <span
                          aria-hidden
                          className={cn(
                            "absolute -top-[6px] size-0 border-y-[5px] border-y-transparent",
                            a < b ? "right-0 border-l-[8px]" : "left-0 border-r-[8px]",
                            warn ? "border-l-amber-ink border-r-amber-ink" : "border-l-deep-green/70 border-r-deep-green/70",
                          )}
                        />
                      </div>
                      {m.note ? (
                        <p className="truncate px-3 pt-1 text-center text-[11.5px] text-faint" title={m.note}>
                          {m.note}
                        </p>
                      ) : null}
                    </div>
                  )}
                </li>
              );
            })}
          </ol>
        </div>
      </div>
    </div>
  );
}

/* ── screen ──────────────────────────────────────────────────── */

/**
 * What the user sees, top to bottom, in a phone-shaped frame, with what each
 * numbered thing does written beside it rather than on top of it.
 */
function Screen({ block }: { block: Extract<Anatomy, { kind: "screen" }> }) {
  const noted = block.items.map((it, i) => ({ ...it, i })).filter((it) => it.note);
  const num = new Map(noted.map((it, k) => [it.i, k + 1]));
  return (
    <div className="min-w-0">
      <Caption>{block.caption}</Caption>
      <div className="flex flex-wrap items-start gap-6">
        {block.shot ? (
          // The real screen, captured from the app's own web build with
          // sample data (D37). Numbered callouts sit beside it, not on it:
          // the capture has no coordinates for where each item landed.
          <figure className="w-[300px] shrink-0">
            {/* A bezel, and a blank strip above and below the capture: the web
                build has no status bar, so without them the rounded corners
                cut into the app's own title and tab bar. */}
            <div className="rounded-[44px] bg-ink p-[9px] shadow-panel">
              <div className="overflow-hidden rounded-[36px] bg-pure-white">
                <div className="flex h-8 items-center justify-center">
                  <div className="h-[18px] w-[84px] rounded-full bg-ink" />
                </div>
                {/* eslint-disable-next-line @next/next/no-img-element -- a static capture at its own size; next/image adds nothing here */}
                <img src={block.shot} alt={block.title} className="block h-auto w-full" />
                <div className="flex h-6 items-center justify-center">
                  <div className="h-[4px] w-24 rounded-full bg-ink/80" />
                </div>
              </div>
            </div>
            <figcaption className="mt-2 text-center font-mono text-[10.5px] text-faint">
              the real screen · sample data
            </figcaption>
          </figure>
        ) : (
          <div className="w-[280px] shrink-0 rounded-[30px] border-[1.5px] border-border-strong bg-pure-white p-3 shadow-panel">
            <div className="mx-auto mb-3 h-[5px] w-16 rounded-full bg-surface-container" />
            <p className="mb-3 px-2 text-center text-[13px] font-semibold text-ink">{block.title}</p>
            <div className="flex flex-col gap-2 px-2 pb-3">
              {block.items.map((it, i) => (
                <ScreenThing key={i} type={it.type} label={it.label} n={num.get(i)} />
              ))}
            </div>
          </div>
        )}
        {noted.length ? (
          // Reading size, not caption size (D44). This list sits beside a
          // ~700px phone with room to spare, so it was set small and tight
          // against a column of empty space. It is the explanation of the
          // screen — the main text of the block — and is typeset as such.
          <ol className="flex min-w-[280px] max-w-[760px] flex-1 flex-col gap-4 pt-10">
            {noted.map((it, k) => (
              <li key={it.i} className="flex gap-3 text-[15.5px] leading-relaxed">
                <Badge n={k + 1} />
                <span>
                  <span className="font-semibold text-ink">{it.label}</span>
                  <span className="text-on-surface-variant">
                    {" — "}
                    <Prose text={it.note ?? ""} />
                  </span>
                </span>
              </li>
            ))}
          </ol>
        ) : null}
      </div>
    </div>
  );
}

function Badge({ n }: { n: number }) {
  return (
    <span className="mt-[3px] flex size-[21px] shrink-0 items-center justify-center rounded-full bg-deep-green font-mono text-[11px] font-semibold text-pure-white">
      {n}
    </span>
  );
}

function ScreenThing({ type, label, n }: { type: string; label: string; n?: number }) {
  const badge = n ? (
    <span className="absolute -right-1.5 -top-1.5">
      <Badge n={n} />
    </span>
  ) : null;
  const base = "relative text-[12.5px]";
  switch (type) {
    case "heading":
      return <p className={cn(base, "text-[15px] font-semibold text-ink")}>{label}{badge}</p>;
    case "text":
      return <p className={cn(base, "text-muted-slate")}>{label}{badge}</p>;
    case "field":
      return (
        <div className={cn(base, "rounded-[8px] border border-border-strong px-2.5 py-2 text-faint")}>
          {label}
          {badge}
        </div>
      );
    case "choice":
      return (
        <div className={cn(base, "rounded-full border border-mint-line bg-mint-success px-3 py-1.5 text-deep-green")}>
          {label}
          {badge}
        </div>
      );
    case "button":
      return (
        <div className={cn(base, "rounded-full bg-deep-green px-3 py-2 text-center font-medium text-pure-white")}>
          {label}
          {badge}
        </div>
      );
    case "image":
      return (
        <div className={cn(base, "flex h-20 items-center justify-center rounded-[8px] bg-surface-container text-faint")}>
          {label}
          {badge}
        </div>
      );
    default:
      return (
        <div className={cn(base, "flex flex-col gap-1 rounded-[8px] border border-border-gray p-2 text-on-surface-variant")}>
          {label}
          <span className="h-2 w-4/5 rounded bg-surface-container" />
          <span className="h-2 w-3/5 rounded bg-surface-container" />
          {badge}
        </div>
      );
  }
}

/* ── example ─────────────────────────────────────────────────── */

function Example({ block }: { block: Extract<Anatomy, { kind: "example" }> }) {
  return (
    <div className="min-w-0">
      <div className="mb-2.5 flex items-center gap-2">
        <span className="rounded-full border border-border-strong px-2 py-[2px] font-mono text-[10px] uppercase tracking-[0.07em] text-faint">
          example
        </span>
        <span className="text-[13px] font-medium text-on-surface-variant">{block.caption}</span>
      </div>
      <pre className="overflow-x-auto rounded-[12px] border border-border-gray bg-surface px-4 py-3 font-mono text-[12.5px] leading-relaxed text-on-surface">
        {block.value}
      </pre>
      {block.notes?.length ? (
        <dl className="mt-2.5 flex flex-col gap-1.5">
          {block.notes.map((p) => (
            <div key={p.label} className="flex gap-3 text-[13px] leading-snug">
              <dt className="w-[160px] shrink-0 font-mono text-[12px] text-ink">{p.label}</dt>
              <dd className="text-on-surface-variant">
                <Prose text={p.value} />
              </dd>
            </div>
          ))}
        </dl>
      ) : null}
    </div>
  );
}

/* ── watch out ───────────────────────────────────────────────── */

export function WatchOut({ issues }: { issues: Issue[] }) {
  return (
    <section>
      <Eyebrow className="text-clay-ink">Watch out</Eyebrow>
      <ul className="mt-3 flex flex-col gap-2.5">
        {issues.map((it) => (
          <li key={it.title} className="rounded-[12px] border border-clay-line bg-clay-surface/60 px-4 py-3">
            <p className="text-[14px] font-semibold text-clay-ink">{it.title}</p>
            <p className="mt-1 text-[13.5px] leading-relaxed text-on-surface">
              <Prose text={it.detail} />
            </p>
            {it.where ? <p className="mt-1.5 font-mono text-[11px] text-muted-slate">{it.where}</p> : null}
          </li>
        ))}
      </ul>
    </section>
  );
}

/* ── the code, last ──────────────────────────────────────────── */

/**
 * The code behind this level, folded. Each place opens on its own, read live
 * from disk and editable through the same view the old leaf level used — so
 * the code is never more than two clicks away and never in the way.
 */
export function CodeDrawer({
  owner,
  refs,
  ctx,
  open,
  onToggle,
}: {
  owner: string;
  refs: CodeRef[];
  ctx: RowCtx;
  open: boolean;
  onToggle: () => void;
}) {
  return (
    <section id="code" className="scroll-mt-16">
      <button
        onClick={onToggle}
        aria-expanded={open}
        className="flex items-center gap-2 rounded-full border border-border-gray bg-pure-white px-3.5 py-1.5 text-[13px] text-on-surface-variant transition-colors hover:border-border-strong hover:text-ink"
      >
        <span className="font-mono text-[12px]">{"</>"}</span>
        {open ? "Hide the code" : `The code behind this · ${refs.length} ${refs.length === 1 ? "place" : "places"}`}
      </button>
      {open ? (
        <ul className="mt-4 flex flex-col gap-2">
          {refs.map((r) => (
            <CodePlace key={`${r.file}:${r.start}`} owner={owner} code={r} ctx={ctx} />
          ))}
        </ul>
      ) : null}
    </section>
  );
}

function CodePlace({ owner, code, ctx }: { owner: string; code: CodeRef; ctx: RowCtx }) {
  const [slice, setSlice] = useState<RepoSlice | null | "failed">(null);
  const [shown, setShown] = useState(false);
  const { name: map } = useMap();

  const toggle = async () => {
    setShown((v) => !v);
    if (slice) return;
    try {
      const r = await readSource({ map, file: code.file, start: code.start, end: code.end });
      setSlice("slice" in r ? r.slice : "failed");
    } catch {
      setSlice("failed");
    }
  };

  return (
    <li className="rounded-[12px] border border-border-gray bg-pure-white">
      <button onClick={toggle} aria-expanded={shown} className="flex w-full items-baseline gap-3 px-4 py-2.5 text-left">
        <span className="text-[13.5px] text-ink">{code.label}</span>
        <span className="ml-auto shrink-0 font-mono text-[11px] text-faint">
          {code.file}:{code.start}–{code.end}
        </span>
        <span aria-hidden className="text-[11px] text-faint">{shown ? "▾" : "▸"}</span>
      </button>
      {shown ? (
        <div className="border-t border-border-gray p-3">
          {slice === "failed" ? (
            <p className="text-[12.5px] text-clay-ink">Could not read this file from the repository.</p>
          ) : slice ? (
            <SourceView
              owner={`${owner}@${code.file}:${code.start}`}
              block={{ kind: "source", file: code.file, start: slice.start, code: slice.code }}
              ctx={ctx}
            />
          ) : (
            <p className="text-[12.5px] text-faint">Reading…</p>
          )}
        </div>
      ) : null}
    </li>
  );
}

ui/components/canvas.tsx:
"use client";

import { useCallback, useEffect, useLayoutEffect, useMemo, useRef, useState } from "react";
import { AnimatePresence, motion } from "motion/react";
import { useSearchParams } from "next/navigation";
import { cn } from "@/lib/utils";
import { AnatomyView, type RowCtx } from "@/components/anatomy";
import { CodeDrawer, ExplainedBlock, WatchOut, isExplained } from "@/components/blocks";
import { InlineMarks, ShapeView } from "@/components/shapes";
import { Eyebrow, Prose, StateChip } from "@/components/state";
import { WireLayer, wireKind, useWireAnchors, type Wire } from "@/components/wires";
import { Crumbs } from "@/components/chrome";
import { useMap } from "@/components/map-context";
import type { Edge, Node } from "@/lib/data";
import { BLURB_LINES, type Shape } from "@/lib/view";

/**
 * The whole screen: ONE level at a time.
 *
 * The board used to be a pan/zoom canvas where every drill unfolded another
 * row of cards beside the last. Each level added width, siblings were squeezed
 * to fit a 360px wrapper (Formulas rendered one word per line), and the top
 * level was a hand-placed serpentine whose second row read right-to-left. See
 * D28.
 *
 * Now the node you opened is the header, its children are the body, and the
 * way back is the trail on the left. Every level — the repo included — is the
 * same template, so depth costs nothing visually: level six looks like level
 * one, and the bottom of every branch is the code itself.
 */


/** Levels below this node: 0 for a leaf. */
function height(node: Node): number {
  return node.children?.length ? 1 + Math.max(...node.children.map(height)) : 0;
}

/**
 * File paths only at the bottom of a branch — the level you are standing on
 * when there is nowhere further to go (D42). A path on a card answers a
 * question nobody has asked yet: you can open the part and be told then. The
 * code drawer still names every file on every level, and the open level's own
 * header still shows its footprint.
 */
function nearBottom(node: Node) {
  return height(node) === 0;
}

function authored(node: Node) {
  return (node.children ?? []).filter((c) => !c.fromRow);
}

/** Opening a card shows something: its children, or its own rows in full. */
function openable(node: Node) {
  return authored(node).length > 0 || Boolean(node.anatomy?.length);
}

/**
 * The arrows between a node's children — only where the node declares a
 * sequence (D19, D21). A set gets nothing and says so via `setNote`.
 */
function siblingEdges(node: Node, kids: Node[]): Edge[] {
  if (node.group?.ordering !== "sequence" || kids.length < 2) return [];
  if (node.edges?.length) return node.edges;
  return kids.slice(1).map((c, i) => ({
    from: kids[i].id,
    to: c.id,
    state: kids[i].state === "derived" && c.state === "derived" ? "derived" : "partial",
    order: i + 1,
  }));
}

/**
 * The line an unordered level says about itself. No `group` at all says
 * nothing: an unbacked claim about ordering is the same mistake as an unbacked
 * arrow, pointing the other way.
 */
function setNote(node: Node): string | null {
  if (!node.group || node.group.ordering === "sequence") return null;
  return node.group.note ?? "No order between these — they are a set, not a flow.";
}

export function Canvas() {
  const { LINKS, RUN, levelAt, nodeAt, stepOf, name, maps } = useMap();
  const scrollRef = useRef<HTMLDivElement>(null);
  const contentRef = useRef<HTMLDivElement>(null);
  const { nodes, anchor, version } = useWireAnchors();

  /**
   * The open path, root-first, read from the URL (`?at=engine&at=eng-math`).
   * `[]` is the repo; depth is its length.
   *
   * The URL rather than state because every level is then a history entry:
   * the browser's back button and the trackpad's two-finger swipe step back
   * the way they do everywhere else, and a level can be linked or reloaded.
   * Clicking empty space used to go back, and an accidental click on the
   * background threw away where you were.
   */
  const params = useSearchParams();
  const path = useMemo(() => {
    const asked = params.getAll("at");
    return asked.length && nodeAt(asked) ? asked : [];
  }, [params, nodeAt]);
  const key = path.join("/");
  const focus = path.length ? nodeAt(path) : null;

  // Which way the level slides: deeper or back. Derived when the depth
  // changes, during render, so the exiting level already knows its direction.
  const [moved, setMoved] = useState({ depth: path.length, dir: 1 });
  if (moved.depth !== path.length) {
    setMoved({ depth: path.length, dir: path.length > moved.depth ? 1 : -1 });
  }
  const dir = moved.dir;

  // A trace belongs to the level it was started on, and ends when you leave.
  const [trace, setTrace] = useState<{ at: string; id: string } | null>(null);
  const traced = trace?.at === key ? trace.id : null;
  const setTraced = useCallback(
    (id: string | null) => setTrace(id ? { at: key, id } : null),
    [key],
  );

  // Native pushState is integrated with the App Router: `useSearchParams`
  // follows it, and so does back/forward.
  const go = useCallback((next: string[]) => {
    const q = new URLSearchParams();
    const map = new URLSearchParams(window.location.search).get("map");
    if (map) q.set("map", map);
    for (const id of next) q.append("at", id);
    window.history.pushState(null, "", q.size ? `?${q}` : window.location.pathname);
  }, []);

  // A new level starts at its top, not wherever the last one was scrolled to.
  useLayoutEffect(() => {
    scrollRef.current?.scrollTo({ top: 0 });
  }, [key]);

  /* ── tracing a row-level chain ────────────────────────────── */

  // Depth-capped walk of LINKS outward from the clicked row, so a click on a
  // foreign key lights what it references AND what reads that, not one hop.
  const lit = useMemo(() => {
    if (!traced) return new Set<string>();
    const seen = new Set<string>([traced]);
    let frontier = [traced];
    for (let hop = 0; hop < 6 && frontier.length; hop++) {
      const next: string[] = [];
      for (const id of frontier) {
        for (const l of LINKS) {
          if (l.from === id && !seen.has(l.to)) { seen.add(l.to); next.push(l.to); }
          if (l.to === id && !seen.has(l.from)) { seen.add(l.from); next.push(l.from); }
        }
      }
      frontier = next;
    }
    return seen;
  }, [traced, LINKS]);

  // Only row-to-row wires remain: sibling order is drawn by `Sequence` itself,
  // where a wrapping layout can't send a wire across a card. Foreign keys show
  // when both ends are on screen; a trace replaces them while it is active.
  const wires = useMemo<Wire[]>(() => {
    const kind = (l: (typeof LINKS)[number]) => wireKind(l.state, l.alarm);
    if (traced) {
      return LINKS.filter((l) => lit.has(l.from) && lit.has(l.to)).map((l) => ({
        from: l.from,
        to: l.to,
        kind: kind(l),
        depth: l.from === traced || l.to === traced ? 0 : 1,
        relation: l.label === "FK",
      }));
    }
    if (!focus) return [];
    const shown = new Set([focus.id, ...levelAt(path).map((n) => n.id)]);
    const owner = (rowKey: string) => rowKey.slice(0, rowKey.lastIndexOf(":"));
    return LINKS.filter(
      (l) => l.label === "FK" && shown.has(owner(l.from)) && shown.has(owner(l.to)),
    ).map((l) => ({ from: l.from, to: l.to, kind: kind(l), depth: 0, relation: true }));
  }, [traced, lit, focus, path, LINKS, levelAt]);

  /* ── rows that open their own level ───────────────────────── */

  const onOpenRow = useCallback(
    (id: string) => {
      // The row id names its owner (`eng-path:2` owns `eng-path:2:not expired`,
      // hence lastIndexOf). The owner is either the open node or a card on the
      // level below it, so cut the path back to it or step into it — never
      // just append.
      const owner = id.slice(0, id.lastIndexOf(":"));
      const ownerAt = path.indexOf(owner);
      const at = ownerAt === -1 ? [...path, owner] : path.slice(0, ownerAt + 1);
      if (nodeAt([...at, id])) go([...at, id]);
    },
    [path, go, nodeAt],
  );

  const ctx = useMemo<RowCtx>(
    () => ({
      anchor,
      lit,
      tracing: Boolean(traced),
      onTrace: (rid) => setTraced(traced === rid ? null : rid),
      open: path[path.length - 1] ?? null,
      onOpenRow,
    }),
    [anchor, lit, traced, setTraced, path, onOpenRow],
  );

  /* ── keyboard ─────────────────────────────────────────────── */

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.target instanceof HTMLElement && e.target.closest("textarea, input")) return;
      if (e.key === "Escape") {
        // Unwind one layer at a time: the trace first, then one level.
        if (traced) setTraced(null);
        else if (path.length) go(path.slice(0, -1));
      } else if (e.key === "0") {
        go([]);
      }
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [traced, setTraced, path, go]);

  const crumbs = path
    .map((_, i) => nodeAt(path.slice(0, i + 1)))
    .filter((n): n is Node => n !== null)
    .map((n) => ({ id: n.id, title: n.title, step: stepOf(n.id)?.n }));

  const open = (next: string[]) => go(next);

  return (
    <div className="flex h-dvh w-screen overflow-hidden bg-warm-cream">
      <main ref={scrollRef} className="dotfield relative min-w-0 flex-1 overflow-y-auto">
        <Crumbs repo={RUN.repo} map={name} maps={maps} crumbs={crumbs} onJump={(d) => go(path.slice(0, d))} />
        <div ref={contentRef} className="relative mx-auto max-w-[1220px] px-10 pb-28 pt-5">
          <WireLayer
            canvasRef={contentRef}
            nodes={nodes}
            wires={wires}
            version={version}
            reflowKey={key}
          />
          <AnimatePresence mode="wait" initial={false} custom={dir}>
            <motion.div
              key={key}
              custom={dir}
              variants={{
                in: { opacity: 1, y: 0 },
                out: (d: number) => ({ opacity: 0, y: 10 * d }),
                gone: (d: number) => ({ opacity: 0, y: -6 * d }),
              }}
              initial="out"
              animate="in"
              exit="gone"
              transition={{ duration: 0.18, ease: [0.22, 1, 0.36, 1] }}
            >
              {focus ? (
                <Level node={focus} path={path} ctx={ctx} onOpen={open} />
              ) : (
                <Overview onOpen={open} />
              )}
            </motion.div>
          </AnimatePresence>
        </div>
      </main>
    </div>
  );
}


/* ── levels ──────────────────────────────────────────────────── */

/**
 * The repo itself, drawn as a level like any other: the shared path as a
 * numbered line, then — where it splits — one numbered line per lane side by
 * side, and the roots E0 never touches grouped under their own heading.
 */
function Overview({ onOpen }: { onOpen: (p: string[]) => void }) {
  const { RUN, E0, L0, SPINE, LANES, HANDOFFS, ON_PATH, roots } = useMap();
  const chain = roots(SPINE);
  const outside = L0.filter((n) => !ON_PATH.has(n.id));
  const fork = LANES.length ? L0.find((n) => n.id === LANES[0].from) : undefined;

  return (
    <>
      <Header
        eyebrow="Repository"
        title={RUN.repo}
        sub={RUN.about}
        meta={`${RUN.files} files · commit ${RUN.commit}`}
        link={RUN.url ? { href: `${RUN.url}/tree/${RUN.commit}`, label: `${RUN.url.replace(/^https:\/\//, "")} ↗` } : undefined}
      />
      <Caption
        count={chain.length}
        what="steps"
        how={LANES.length ? "in order, for everyone" : "in order"}
      />
      <Steps nodes={chain} edges={E0} at={[]} onOpen={onOpen} />

      {fork ? (
        <section className="mt-10">
          <Caption count={LANES.length} what="paths" how={`after ${fork.title}`} />
          <Note>{fork.title} sends each account down one of these. They meet where noted.</Note>
          <div className="grid max-w-[1180px] grid-cols-1 gap-x-10 gap-y-8 lg:grid-cols-2">
            {LANES.map((l) => (
              <div key={l.name} className="min-w-0">
                <h3 className="mb-3 border-b border-border-strong pb-2 text-[15px] font-semibold text-ink">
                  {l.name}
                </h3>
                <Steps
                  nodes={roots(l.ids)}
                  edges={E0}
                  start={SPINE.length + 1}
                  handoffs={HANDOFFS}
                  at={[]}
                  onOpen={onOpen}
                />
              </div>
            ))}
          </div>
        </section>
      ) : null}

      {outside.length ? (
        <section className="mt-12">
          <Caption count={outside.length} what="more" how="outside the path" />
          <Note>No step leads to these.</Note>
          <Grid nodes={outside} at={[]} onOpen={onOpen} />
        </section>
      ) : null}
    </>
  );
}

/**
 * One open node, explained. Top to bottom: what it is (header), the picture of
 * how it fits together, its own data — tables, screens, who talks to whom —
 * then its parts to go deeper, what to watch out for, and last, folded, the
 * code (D34).
 *
 * A level still shows ONE step of depth: a part below is named, never opened
 * in place (D31). What changed is that the open level itself now carries
 * enough to be understood without reading the code.
 */
function Level({
  node,
  path,
  ctx,
  onOpen,
}: {
  node: Node;
  path: string[];
  ctx: RowCtx;
  onOpen: (p: string[]) => void;
}) {
  const { RUN, nodeAt, stepOf } = useMap();
  const kids = authored(node);
  const parent = path.length > 1 ? nodeAt(path.slice(0, -1)) : null;
  const step = path.length === 1 ? stepOf(node.id) : undefined;
  const note = setNote(node);
  const sequence = node.group?.ordering === "sequence";
  const figure = node.shape?.kind === "figure" ? node.shape : undefined;
  const blocks = node.anatomy ?? [];
  // Which parts a box on this level's diagram already opens — those drive the
  // list below down to a quiet index (D40).
  const onDiagram = new Set(
    blocks
      .flatMap((b) => (b.kind === "diagram" ? b.boxes : []))
      .map((box) => box.opens)
      .filter((id): id is string => Boolean(id) && kids.some((k) => k.id === id)),
  );
  // A row-built level has no refs of its own; the code of the nearest level
  // above it is still the code behind it.
  const code =
    node.code ??
    path
      .map((_, i) => nodeAt(path.slice(0, path.length - 1 - i))?.code)
      .find((c) => c?.length) ??
    [];
  const [codeOpen, setCodeOpen] = useState(false);

  return (
    <>
      <Header
        back={{
          label: parent?.title ?? RUN.repo,
          onClick: () => onOpen(path.slice(0, -1)),
        }}
        eyebrow={
          parent
            ? `Inside ${parent.title}`
            : step
              ? `${step.lane ? `${step.lane} · ` : ""}Step ${step.n} of ${step.of}`
              : "Outside the path"
        }
        title={node.title}
        state={node.state}
        alarm={node.alarm}
        // A row-built node's fallback sub is "Inside <parent>", which the
        // eyebrow already says.
        sub={node.sub === `Inside ${parent?.title}` ? undefined : node.sub}
        detail={node.detail}
        unsure={node.state === "derived" ? undefined : node.unsure}
        meta={
          !nearBottom(node)
            ? undefined
            : node.footprint
              ? `${node.footprint.dirs.join("  ")}  ·  ${node.footprint.files} files`
              : node.evidence
        }
        shape={figure ? undefined : node.shape}
        onCode={
          code.length
            ? () => {
                setCodeOpen(true);
                requestAnimationFrame(() =>
                  document.getElementById("code")?.scrollIntoView({ behavior: "smooth" }),
                );
              }
            : undefined
        }
      />

      <div className="flex flex-col gap-12">
        {/* The picture is the main thing on the level, not a thumbnail in
            the header's corner. */}
        {figure ? (
          <div className="max-w-[540px]">
            <ShapeView shape={figure} />
          </div>
        ) : null}

        {blocks.map((b, i) =>
          isExplained(b) ? (
            <div key={i} className={b.kind === "diagram" ? "" : "max-w-[1000px]"}>
              <ExplainedBlock
                block={b}
                onOpen={(id) =>
                  kids.some((k) => k.id === id) ? onOpen([...path, id]) : undefined
                }
                hrefFor={(id) =>
                  `?${[...path, id].map((p) => `at=${encodeURIComponent(p)}`).join("&")}`
                }
              />
            </div>
          ) : (
            // The older blocks are typeset for a 340px card (11px rows); zoom
            // lifts them to reading size without forking their type scale.
            <div key={i} className="max-w-[900px] [zoom:1.18]">
              <AnatomyView owner={node.id} blocks={[b]} ctx={ctx} opened />
            </div>
          ),
        )}

        {kids.length ? (
          <section>
            <Caption
              count={kids.length}
              what={kids.length === 1 ? "part" : "parts"}
              how={
                onDiagram.size
                  ? onDiagram.size === kids.length
                    ? "all of them on the picture above"
                    : `${onDiagram.size} of them on the picture above`
                  : sequence
                    ? "in order — open one to go deeper"
                    : "open one to go deeper"
              }
            />
            {note ? <Note>{note}</Note> : null}
            {sequence ? (
              <Steps nodes={kids} edges={siblingEdges(node, kids)} at={path} onOpen={onOpen} />
            ) : onDiagram.size ? (
              // The picture is the way down, so the list stops competing with
              // it: names and problems, no cards, no blurbs, no paths (D40).
              <List nodes={kids} at={path} onOpen={onOpen} />
            ) : (
              <Grid nodes={kids} at={path} onOpen={onOpen} />
            )}
          </section>
        ) : null}

        {node.issues?.length ? (
          <div className="max-w-[820px]">
            <WatchOut issues={node.issues} />
          </div>
        ) : null}

        {code.length ? (
          <div className="max-w-[1000px]">
            <CodeDrawer
              owner={node.id}
              refs={code}
              ctx={ctx}
              open={codeOpen}
              onToggle={() => setCodeOpen((v) => !v)}
            />
          </div>
        ) : null}
      </div>
    </>
  );
}

/* ── layout ──────────────────────────────────────────────────── */

/**
 * Real order, drawn as one numbered line down the left — the same rail the
 * steps inside a flow use. It never wraps, so there is no row-end arrow
 * pointing at nothing. Where the data names the hand-off ("uploads to") it is
 * written on the line; where the hand-off is only partly established the line
 * is dashed.
 */
function Steps({
  nodes,
  edges,
  start = 1,
  handoffs = [],
  at,
  onOpen,
}: {
  nodes: Node[];
  edges: Edge[];
  /** The first dot's number — a lane continues the shared path's count. */
  start?: number;
  /** Hand-offs into another lane, written under the step they leave. */
  handoffs?: Edge[];
  at: string[];
  onOpen: (p: string[]) => void;
}) {
  const { L0, stepOf } = useMap();
  return (
    <ol className="flex max-w-[880px] flex-col">
      {nodes.map((n, i) => {
        const last = i === nodes.length - 1;
        const edge = last
          ? undefined
          : edges.find((e) => e.from === n.id && e.to === nodes[i + 1].id);
        const partial = edge && edge.state !== "derived";
        return (
          <li key={n.id} className="flex gap-4">
            <div className="flex w-[22px] shrink-0 flex-col items-center pt-[15px]">
              <StepDot n={start + i} state={n.state} />
              {last ? null : (
                <span
                  className={cn(
                    "mt-1.5 w-0 flex-1 border-l",
                    partial ? "border-dashed border-amber-line" : "border-border-strong",
                  )}
                />
              )}
            </div>
            <div className={cn("min-w-0 flex-1", last ? "" : "pb-3")}>
              <Row node={n} at={at} onOpen={onOpen} />
              {edge?.label ? (
                <p
                  className={cn(
                    "mt-2.5 pl-1 text-[11.5px] italic",
                    partial ? "text-amber-ink" : "text-faint",
                  )}
                >
                  {edge.label} {nodes[i + 1].title}
                </p>
              ) : null}
              {handoffs
                .filter((h) => h.from === n.id)
                .map((h) => (
                  <p key={h.to} className="mt-1.5 pl-1 text-[11.5px] italic text-faint">
                    ↗ {h.label}{" "}
                    <span className="font-medium not-italic text-muted-slate">
                      {L0.find((r) => r.id === h.to)?.title}
                    </span>
                    {stepOf(h.to)?.lane ? ` · ${stepOf(h.to)?.lane}` : ""}
                  </p>
                ))}
            </div>
          </li>
        );
      })}
    </ol>
  );
}

/** A set has no order, so it gets no numbers and no line — a grid. */
function Grid({
  nodes,
  at,
  onOpen,
}: {
  nodes: Node[];
  at: string[];
  onOpen: (p: string[]) => void;
}) {
  return (
    <div className="grid max-w-[1100px] grid-cols-[repeat(auto-fill,minmax(340px,1fr))] gap-3">
      {nodes.map((n) => (
        <Row key={n.id} node={n} at={at} onOpen={onOpen} />
      ))}
    </div>
  );
}

/**
 * The parts as an index, for when the diagram above is already the way down
 * (D40). One line each: the name, and a problem count if there is one. No
 * blurb, no block counts, no file path — the picture carries the shape of the
 * level, and this is here so a part is still reachable by keyboard, by screen
 * reader, and when a part has no box of its own.
 */
function List({
  nodes,
  at,
  onOpen,
}: {
  nodes: Node[];
  at: string[];
  onOpen: (p: string[]) => void;
}) {
  return (
    <ul className="max-w-[560px]">
      {nodes.map((n) => {
        const go = openable(n) ? () => onOpen([...at, n.id]) : undefined;
        return (
          <li key={n.id}>
            <button
              data-node-id={n.id}
              onClick={go}
              disabled={!go}
              className={cn(
                "group flex w-full items-center gap-2.5 rounded-[8px] border-b border-border-gray/70 px-1.5 py-2.5 text-left transition-colors",
                go && "hover:bg-surface-container-low",
                "focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-deep-green",
              )}
            >
              <span className="truncate text-[14px] font-medium tracking-[-0.01em] text-ink">
                {n.title}
              </span>
              {n.issues?.length ? (
                <span className="shrink-0 font-mono text-[10.5px] text-clay-ink">
                  ⚠ {n.issues.length}
                </span>
              ) : null}
              <span className="flex-1" />
              {go ? (
                <span
                  aria-hidden
                  className="shrink-0 text-[14px] text-faint transition-colors group-hover:text-deep-green"
                >
                  ›
                </span>
              ) : null}
            </button>
          </li>
        );
      })}
    </ul>
  );
}

function Caption({ count, what, how }: { count: number; what: string; how: string }) {
  return (
    <div className="mb-3 flex items-baseline gap-2">
      <Eyebrow className="text-muted-slate">
        {count} {what}
      </Eyebrow>
      <span className="font-mono text-[10.5px] text-faint">· {how}</span>
    </div>
  );
}

function Note({ children }: { children: React.ReactNode }) {
  return <p className="-mt-1 mb-4 text-[12px] italic text-faint">{children}</p>;
}

/* ── the node you are in ─────────────────────────────────────── */

function Header({
  back,
  eyebrow,
  title,
  state,
  alarm,
  sub,
  detail,
  unsure,
  meta,
  link,
  shape,
  onCode,
}: {
  /** The level above, named — so "back" says where it goes. */
  back?: { label: string; onClick: () => void };
  eyebrow: string;
  title: string;
  state?: Node["state"];
  alarm?: boolean;
  sub?: string;
  detail?: string;
  /** Why this level is not certain, shown with the mark it explains. */
  unsure?: string;
  meta?: string;
  /** Where the code lives, outside this page. */
  link?: { href: string; label: string };
  shape?: Shape;
  onCode?: () => void;
}) {
  return (
    <header className="mb-8 border-b border-border-gray pb-7">
      <div className="min-w-0 max-w-[660px]">
        {back ? (
          <button
            onClick={back.onClick}
            className="-ml-2 mb-4 flex items-center gap-1.5 rounded-full px-2 py-1 text-[12.5px] text-muted-slate transition-colors hover:bg-surface-container-low hover:text-ink focus-visible:outline-2 focus-visible:outline-deep-green"
          >
            <span aria-hidden>←</span>
            {back.label}
          </button>
        ) : null}
        <Eyebrow>{eyebrow}</Eyebrow>
        <div className="mt-2.5 flex flex-wrap items-center gap-x-3 gap-y-2">
          <h1 className="text-[28px] font-semibold leading-tight tracking-[-0.02em] text-ink">
            {title}
          </h1>
          {state ? <StateChip state={state} alarm={alarm} /> : null}
          {shape?.kind === "marks" ? <InlineMarks ids={shape.ids} note={shape.note} /> : null}
          {shape?.kind === "count" ? (
            <span className="rounded-full border border-border-gray bg-pure-white px-2.5 py-1 text-[12px] text-on-surface-variant">
              <span className="tnum font-semibold text-ink">{shape.value}</span> {shape.unit}
            </span>
          ) : null}
        </div>
        {sub ? (
          <p className="mt-1.5 text-[15px] leading-snug text-on-surface-variant">{sub}</p>
        ) : null}
        {detail
          ? detail.split(/\n\s*\n/).map((para, i) => (
              <p key={i} className="mt-4 text-[14.5px] leading-relaxed text-on-surface">
                <Prose text={para} />
              </p>
            ))
          : null}
        {unsure ? (
          <p className="mt-4 rounded-[10px] border border-dashed border-amber-line bg-amber-surface/60 px-3 py-2 text-[13px] leading-snug text-amber-ink">
            <span className="font-semibold">Not certain: </span>
            <Prose text={unsure} />
          </p>
        ) : null}
        {meta || link || onCode ? (
          <div className="mt-4 flex flex-wrap items-baseline gap-x-4 gap-y-1">
            {meta ? (
              <p className="whitespace-pre-wrap font-mono text-[11px] text-faint">{meta}</p>
            ) : null}
            {link ? (
              <a href={link.href} target="_blank" rel="noreferrer" className="font-mono text-[11px] text-deep-green hover:underline">
                {link.label}
              </a>
            ) : null}
            {onCode ? (
              <button
                onClick={onCode}
                className="font-mono text-[11px] text-deep-green hover:underline"
              >
                {"</>"} view code
              </button>
            ) : null}
          </div>
        ) : null}
      </div>
    </header>
  );
}

/* ── a part: named, not opened ───────────────────────────────── */

const BLOCK_NOUN: Record<string, string> = {
  flow: "steps",
  facts: "facts",
  map: "entries",
  schema: "columns",
  routes: "routes",
  chips: "kinds",
  bars: "measures",
  parts: "parts",
  table: "rows",
  sequence: "steps",
};

/**
 * What is behind the click, in a few words: the author's own `summary` when
 * there is one, else the names of the parts, else a count of what kind of
 * thing is inside — and whether real code is at the bottom of it.
 */
function inside(node: Node): string {
  if (node.summary) return node.summary;
  const kids = authored(node);
  if (kids.length) return kids.map((k) => k.title).join(" · ");
  // Code is not listed: it is behind every level now, not a destination.
  return (node.anatomy ?? [])
    .map((b) =>
      b.kind === "diagram" ? "diagram"
      : b.kind === "screen" ? `the ${b.title} screen`
      : b.kind === "example" ? "an example"
      : b.kind === "source" ? null
      : `${b.rows.length} ${BLOCK_NOUN[b.kind]}`,
    )
    .filter(Boolean)
    .join(" · ");
}

/**
 * One part of the level: what it is, in a line, and what you will find if you
 * open it. Never its contents — those are the next step down.
 */
function Row({ node, at, onOpen }: { node: Node; at: string[]; onOpen: (p: string[]) => void }) {
  const go = openable(node) ? () => onOpen([...at, node.id]) : undefined;
  // No path on a card at all (D42): a card says what the part IS, and the
  // level it opens says where that lives.
  const peek = inside(node);
  const count = node.shape?.kind === "count" ? `${node.shape.value} ${node.shape.unit}` : null;

  return (
    <button
      data-node-id={node.id}
      onClick={go}
      disabled={!go}
      className={cn(
        "group flex w-full items-start gap-3 rounded-[12px] border bg-pure-white px-4 py-3 text-left transition-[border-color,box-shadow] duration-150",
        node.ghost ? "border-dashed border-border-strong bg-surface-container-low/60" : "border-border-gray",
        go && "hover:border-border-strong hover:shadow-panel",
        "focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-deep-green",
      )}
    >
      <span className="min-w-0 flex-1">
        <span className="flex items-center gap-2">
          <span className="truncate text-[15px] font-semibold tracking-[-0.01em] text-ink">
            {node.title}
          </span>
          <StateChip state={node.state} alarm={node.alarm} />
          {node.issues?.length ? (
            <span className="shrink-0 rounded-full border border-clay-line bg-clay-surface px-2 py-[3px] font-mono text-[10px] leading-none text-clay-ink">
              ⚠ {node.issues.length} {node.issues.length === 1 ? "problem" : "problems"}
            </span>
          ) : null}
        </span>
        <span
          className="mt-0.5 block text-[13px] leading-snug text-on-surface-variant [display:-webkit-box] [overflow:hidden] [-webkit-box-orient:vertical]"
          style={{ WebkitLineClamp: BLURB_LINES }}
        >
          {node.sub}
        </span>
        {count || peek ? (
          <span className="mt-1.5 block truncate text-[11.5px] text-muted-slate">
            {[count, peek].filter(Boolean).join(" · ")}
          </span>
        ) : null}
      </span>
      {go ? (
        <span
          aria-hidden
          className="pt-0.5 text-[15px] text-faint transition-colors group-hover:text-deep-green"
        >
          ›
        </span>
      ) : null}
    </button>
  );
}

function StepDot({ n, state }: { n: number; state: Node["state"] }) {
  return (
    <span
      className={cn(
        "flex size-[22px] shrink-0 items-center justify-center rounded-full border font-mono text-[10.5px] font-semibold",
        state === "derived"
          ? "border-mint-line bg-mint-success text-deep-green"
          : "border-amber-line bg-amber-surface text-amber-ink",
      )}
    >
      {n}
    </span>
  );
}

