"use client";

import { Fragment } from "react";
import { useRouter } from "next/navigation";
import { cn } from "@/lib/utils";

/**
 * Where you are, and the way back — one line across the top of the page.
 *
 * This is the sentence you say out loud when someone asks what you are looking
 * at — "explorify, Sign Up, Student Sign-Up". It used to be a 232px rail down
 * the left, which spent a whole column on two or three names and boxed the
 * page in. Now it sits on the page's own background, sticks while you scroll,
 * and WRAPS rather than eliding when the path gets deep, so no stop is ever
 * hidden — the reason the rail existed.
 */
export function Crumbs({
  repo,
  crumbs,
  onJump,
  map,
  maps,
}: {
  repo: string;
  /** The open map and every map on disk; a switcher shows when there are two. */
  map: string;
  maps: string[];
  /** One entry per level below the repo, outermost first. */
  crumbs: { id: string; title: string; step?: number }[];
  /** Jump to depth `n` — 0 is the repo. */
  onJump: (depth: number) => void;
}) {
  const router = useRouter();
  const stops = [{ id: "", title: repo, step: undefined as number | undefined }, ...crumbs];
  return (
    <nav
      aria-label="Location"
      className="sticky top-0 z-20 bg-warm-cream/85 backdrop-blur-sm"
    >
      <div className="mx-auto flex max-w-[1220px] items-start gap-6 px-10 py-3">
        {maps.length > 1 ? (
          <label className="flex shrink-0 items-center gap-2">
            <span className="font-mono text-[10.5px] uppercase tracking-[0.08em] text-faint">map</span>
            <select
              value={map}
              // The router, not pushState: the map is read on the server.
              onChange={(e) => router.push(`?map=${encodeURIComponent(e.target.value)}`)}
              className="rounded-[7px] border border-border-strong bg-pure-white px-2 py-1 text-[12.5px] text-ink focus-visible:outline-2 focus-visible:outline-deep-green"
            >
              {maps.map((m) => (
                <option key={m} value={m}>
                  {m}
                </option>
              ))}
            </select>
          </label>
        ) : null}
        <ol className="flex min-w-0 flex-1 flex-wrap items-center gap-x-1 gap-y-1">
          {stops.map((c, i) => {
            const here = i === stops.length - 1;
            return (
              <Fragment key={c.id || "repo"}>
                {i > 0 ? (
                  <li aria-hidden className="text-[13px] text-faint">
                    ›
                  </li>
                ) : null}
                <li>
                  <button
                    onClick={() => onJump(i)}
                    disabled={here}
                    aria-current={here ? "page" : undefined}
                    className={cn(
                      "rounded-[7px] px-1.5 py-0.5 text-[13px] transition-colors focus-visible:outline-2 focus-visible:outline-deep-green",
                      i === 0 && "font-mono text-[12.5px]",
                      here ? "font-semibold text-ink" : "text-muted-slate hover:bg-surface-container-low hover:text-ink",
                    )}
                  >
                    {c.step ? <span className="mr-1 font-mono text-[11px] text-faint">{c.step}</span> : null}
                    {c.title}
                  </button>
                </li>
              </Fragment>
            );
          })}
        </ol>
        <div className="flex shrink-0 items-center gap-3 pt-0.5 font-mono text-[10.5px] text-faint">
          <Hint k="esc">back</Hint>
          <Hint k="0">top</Hint>
        </div>
      </div>
    </nav>
  );
}

function Hint({ k, children }: { k: string; children: React.ReactNode }) {
  return (
    <span className="flex items-center gap-1">
      <kbd className="rounded border border-border-gray bg-surface px-1.5 py-0.5 text-[10px] text-muted-slate">
        {k}
      </kbd>
      {children}
    </span>
  );
}

ui/components/map-context.tsx:
"use client";

import { createContext, useContext, useMemo } from "react";
import { buildMap, type BuiltMap, type MapFile } from "@/lib/map";

const MapContext = createContext<(BuiltMap & { maps: string[] }) | null>(null);

/** The map on screen. Read on the server, built once here. */
export function MapProvider({
  name,
  file,
  maps,
  children,
}: {
  name: string;
  file: MapFile;
  maps: string[];
  children: React.ReactNode;
}) {
  const value = useMemo(() => ({ ...buildMap(file, name), maps }), [file, name, maps]);
  return <MapContext.Provider value={value}>{children}</MapContext.Provider>;
}

export function useMap() {
  const m = useContext(MapContext);
  if (!m) throw new Error("useMap outside MapProvider");
  return m;
}

ui/components/wires.tsx:
"use client";

import {
  useCallback,
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
  type RefObject,
} from "react";
import type { State } from "@/lib/data";

/**
 * SVG connector lines between two DOM nodes, measured from the live layout.
 *
 * Endpoints come from getBoundingClientRect rather than from assumed
 * coordinates, because the nodes move: panning the canvas, expanding a
 * subsystem, and opening the detail pane all shift them.
 */

/**
 * A wire carries the same three states as everything else on screen, so a line
 * you can trust and a line the analysis guessed at never look alike.
 */
export type WireKind = "derived" | "partial" | "alarm" | "inferred";

export function wireKind(state: State, alarm?: boolean): WireKind {
  if (alarm) return "alarm";
  return state;
}

export interface Wire {
  from: string;
  to: string;
  kind: WireKind;
  /** 0 = touches the focused node directly; deeper = further out. */
  depth: number;
  /**
   * Foreign key. Drawn as an ER relationship instead of a flow arrow:
   * orthogonal elbows routed through the gutter between cards, with crow's
   * foot terminals — a bar for "exactly one" at the referenced key, three
   * splayed lines for "many" at the referencing column.
   */
  relation?: boolean;
}

interface Path {
  d: string;
  kind: WireKind;
  depth: number;
  x1: number;
  y1: number;
  /** ER terminals, when this path is a foreign key. */
  er?: {
    /** "many" end — sits on the referencing column. */
    many: { x: number; y: number; dir: 1 | -1 };
    /** "one" end — sits on the referenced key. */
    one: { x: number; y: number; dir: 1 | -1 };
  };
}

/**
 * Stroke per state. Dashing is the load-bearing signal: a solid line was
 * resolved by the compiler, a dashed one was not, so an unproven edge can
 * never be mistaken for a proven one at a glance.
 */
const STROKE: Record<WireKind, string> = {
  derived: "var(--color-deep-green)",
  partial: "var(--color-amber-ink)",
  alarm: "var(--color-clay-ink)",
  inferred: "var(--color-muted-slate)",
};

const DASHED: Record<WireKind, string | undefined> = {
  derived: undefined,
  partial: "5 4",
  alarm: "5 4",
  inferred: "2 4",
};

/**
 * Lane assignment for wires that share a corridor.
 *
 * Deriving a lane from a wire's own geometry — its span, its endpoints — is
 * what produced the bundles: two unrelated relationships whose spans happen to
 * agree land on the same track and draw straight over each other. The only
 * thing that actually separates them is knowing WHICH wires share a corridor,
 * so lanes are assigned by grouping first and indexing within the group.
 *
 * Keyed on the rounded corridor position, so the grouping is stable across
 * re-measures rather than depending on wire order.
 */
function assignLanes(keys: string[]): number[] {
  const seen = new Map<string, number>();
  const index: number[] = [];
  for (const k of keys) {
    const n = seen.get(k) ?? 0;
    index.push(n);
    seen.set(k, n + 1);
  }
  const total = new Map(seen);
  // Centre each group on the corridor: with n wires, offsets run symmetrically
  // about 0 so the bundle straddles the midline instead of drifting off it.
  return index.map((i, at) => {
    const n = total.get(keys[at]) ?? 1;
    return i - (n - 1) / 2;
  });
}

export function useWireAnchors() {
  const nodes = useRef(new Map<string, HTMLElement>());
  const [version, setVersion] = useState(0);

  // The ref callback for a given id has to be referentially stable. React
  // detaches and re-attaches a ref whenever the callback's identity changes,
  // so building `(el) => …` inline in render would unregister and re-register
  // every anchor on every render — and with a re-measure hung off that, loop.
  const callbacks = useRef(new Map<string, (el: HTMLElement | null) => void>());
  const pending = useRef(0);

  const bump = useCallback(() => {
    // Mounts arrive one node at a time; coalesce a whole level into one pass.
    if (pending.current) return;
    pending.current = requestAnimationFrame(() => {
      pending.current = 0;
      setVersion((v) => v + 1);
    });
  }, []);

  const anchor = useCallback(
    (id: string) => {
      const existing = callbacks.current.get(id);
      if (existing) return existing;
      const fn = (el: HTMLElement | null) => {
        if (el) nodes.current.set(id, el);
        else nodes.current.delete(id);
        bump();
      };
      callbacks.current.set(id, fn);
      return fn;
    },
    [bump],
  );

  return { nodes, anchor, version };
}

export function WireLayer({
  canvasRef,
  nodes,
  wires,
  version,
  scale = 1,
  reflowKey,
}: {
  canvasRef: RefObject<HTMLDivElement | null>;
  nodes: RefObject<Map<string, HTMLElement>>;
  wires: Wire[];
  version: number;
  /**
   * Scale of the transformed world this layer is mounted inside.
   * getBoundingClientRect reports post-transform screen pixels, so every
   * measured delta is divided by this to get back to world coordinates —
   * otherwise the wires would be scaled twice and drift off the nodes.
   */
  scale?: number;
  /** Any value that changes when the layout shifts — forces a re-measure. */
  reflowKey?: string | null;
}) {
  const [paths, setPaths] = useState<Path[]>([]);
  const [size, setSize] = useState({ w: 0, h: 0 });

  const measure = useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const base = canvas.getBoundingClientRect();
    const k = scale || 1;
    setSize({ w: base.width / k, h: base.height / k });

    // Pass 1: resolve the corridor every relation wire will run through, so
    // lanes can be handed out by group rather than guessed from each wire's own
    // geometry. Two wires that merely happen to share a span are a different
    // thing from two wires that actually share a gutter, and only the second
    // needs separating.
    const cardOf = (el: HTMLElement) =>
      (el.closest("[data-node]") as HTMLElement | null) ?? el;
    // Fan-in lanes for PLAIN card wires. Five edges arriving at one card all
    // aimed at its centre, which stacked them into a single thick smear at the
    // landing point. Grouping by target lets each arrival get its own offset
    // along the target's edge, so five separate facts read as five wires.
    const fanKey: string[] = wires.map((wire) =>
      wire.relation ? "" : `to:${wire.to}`,
    );
    const fanLane = assignLanes(fanKey);
    const fanSize = new Map<string, number>();
    for (const k of fanKey) if (k) fanSize.set(k, (fanSize.get(k) ?? 0) + 1);

    const corridorKey: string[] = wires.map((wire) => {
      if (!wire.relation) return "";
      const a = nodes.current?.get(wire.from);
      const b = nodes.current?.get(wire.to);
      if (!a || !b) return "";
      const rca = cardOf(a).getBoundingClientRect();
      const rcb = cardOf(b).getBoundingClientRect();
      if (Math.abs(rca.left - rcb.left) < 1) return `self:${Math.round(rca.left)}`;
      const rightward = rcb.left >= rca.right || rcb.left > rca.left;
      const sx = rightward ? rca.right : rca.left;
      const ex = rightward ? rcb.left : rcb.right;
      const gutter = Math.abs(ex - sx);
      // Same key for both directions across one gutter: wires sharing a
      // corridor must share a group whichever way they point.
      const span = [Math.round(sx), Math.round(ex)].sort((p, q) => p - q);
      return gutter > 28 && gutter < 320
        ? `gut:${span[0]}:${span[1]}`
        : `under:${Math.round(Math.max(rca.bottom, rcb.bottom))}`;
    });
    const lanes = assignLanes(corridorKey);

    // Every card on screen, in world space. A wire has to route around the
    // boxes it does not connect, not just the two it does — that is the whole
    // difference between a diagram and a bowl of spaghetti.
    // Keyed by the card ELEMENT, because a wire has to be able to recognise
    // its own endpoints here. The boxes are fresh objects built per pass, so
    // an identity test against the wire's A/B boxes can never match — it
    // silently made every wire dodge its own source and target, and since the
    // last matching blocker wins, the target routinely undid the avoidance
    // that a genuine obstacle had just applied.
    const obstacles = [...(nodes.current?.values() ?? [])].map((el) => {
      const rc = (el.closest("[data-node]") as HTMLElement | null) ?? el;
      const box = rc.getBoundingClientRect();
      return {
        el: rc,
        left: (box.left - base.left) / k,
        right: (box.right - base.left) / k,
        top: (box.top - base.top) / k,
        bottom: (box.bottom - base.top) / k,
      };
    });

    const next: Path[] = [];
    for (const [wireAt, wire] of wires.entries()) {
      const a = nodes.current?.get(wire.from);
      const b = nodes.current?.get(wire.to);
      if (!a || !b) continue;
      // The cards this wire actually connects. `a` and `b` may be row anchors
      // rather than cards, and `obstacles` is keyed by card, so both sides have
      // to be resolved the same way for the exclusion to match.
      const cardA = cardOf(a);
      const cardB = cardOf(b);
      const lane = lanes[wireAt];
      const ra = a.getBoundingClientRect();
      const rb = b.getBoundingClientRect();

      // World-space edges of each node. No culling here: the layer lives inside
      // the panned/zoomed world, so "outside the canvas" no longer means
      // offscreen — the viewport clips what the eye can't reach.
      const A = {
        left: (ra.left - base.left) / k,
        right: (ra.right - base.left) / k,
        top: (ra.top - base.top) / k,
        bottom: (ra.bottom - base.top) / k,
      };
      const B = {
        left: (rb.left - base.left) / k,
        right: (rb.right - base.left) / k,
        top: (rb.top - base.top) / k,
        bottom: (rb.bottom - base.top) / k,
      };

      const ax = (A.left + A.right) / 2;
      const ay = (A.top + A.bottom) / 2;
      const bx = (B.left + B.right) / 2;
      const by = (B.top + B.bottom) / 2;

      // Foreign keys draw as ER relationships: orthogonal elbows through the
      // gutter, never diagonals across a card. Three segments — out sideways
      // from the column, vertically along the gutter, in sideways to the key.
      if (wire.relation) {
        // Route around the CARDS, not the rows. A midpoint between two column
        // rows usually lands inside one of the cards, which is how the lines
        // ended up cutting straight through the tables.
        const rca = cardOf(a).getBoundingClientRect();
        const rcb = cardOf(b).getBoundingClientRect();
        const CA = {
          left: (rca.left - base.left) / k,
          right: (rca.right - base.left) / k,
          bottom: (rca.bottom - base.top) / k,
        };
        const CB = {
          left: (rcb.left - base.left) / k,
          right: (rcb.right - base.left) / k,
          bottom: (rcb.bottom - base.top) / k,
        };

        const sameCard = Math.abs(CA.left - CB.left) < 1;
        // Direction follows where the target CARD sits, and only falls back to
        // the rows when the cards genuinely overlap in x. Reading it off the row
        // centres made a wire whose target row happened to sit right of its
        // source exit rightward and then double back to land on a card to its
        // left — two lines travelling right to arrive left.
        const rightward = sameCard
          ? false
          : CB.left >= CA.right
            ? true
            : CA.left >= CB.right
              ? false
              : bx >= ax;

        // Exit the card's own edge, not the row's, so the stub always clears
        // the box it came from.
        const sx = sameCard
          ? CA.left
          : rightward
            ? CA.right
            : CA.left;
        const ex = sameCard ? CB.left : rightward ? CB.left : CB.right;
        const dirOut: 1 | -1 = sameCard ? -1 : rightward ? 1 : -1;

        const r = 7; // elbow radius, so corners read as drawn not aliased
        const gutter = sameCard ? 0 : Math.abs(ex - sx);

        let dd: string;

        if (!sameCard) {
          // Neighbouring cards: run the gutter between them, which is now wide
          // enough to hold a wire. Only reach for the under-card lane when
          // something actually sits in the way.
          const adjacent = gutter > 28 && gutter < 320;
          if (adjacent) {
            // Each wire crossing this gutter gets its own vertical track,
            // centred on the corridor. Pitch is capped so a busy gutter stays
            // inside itself rather than spilling over a card edge.
            const pitch = Math.min(26, Math.max(0, gutter / 2 - 18));
            const mid = (sx + ex) / 2 + lane * pitch;
            const vSign = by > ay ? 1 : -1;
            const canRound = Math.abs(by - ay) > r * 2 + 2;
            dd = canRound
              ? `M ${sx} ${ay} H ${mid - dirOut * r}` +
                ` Q ${mid} ${ay} ${mid} ${ay + vSign * r}` +
                ` V ${by - vSign * r}` +
                ` Q ${mid} ${by} ${mid + dirOut * r} ${by}` +
                ` H ${ex}`
              : `M ${sx} ${ay} H ${mid} V ${by} H ${ex}`;
            next.push({
              d: dd,
              kind: wire.kind,
              depth: wire.depth,
              x1: sx,
              y1: ay,
              er: {
                many: { x: sx, y: ay, dir: dirOut },
                one: { x: ex, y: by, dir: (rightward ? -1 : 1) as 1 | -1 },
              },
            });
            continue;
          }
          // Far apart, with cards in between. Detour beneath everything.
          //
          // Both stubs turn INWARD, toward the lane's interior. Deriving them
          // from dirOut inverted the pair on right-to-left links, so the two
          // verticals crossed and the path doubled back on itself.
          // Hug the taller card. The old offset pushed long-hauls far below
          // everything, which drew one relationship as a giant rectangle
          // sweeping under the whole diagram; only stack when several share it.
          const laneY = Math.max(CA.bottom, CB.bottom) + 22 + lane * 16;
          const inward = ex >= sx ? 1 : -1;
          const outX = sx + inward * 16;
          const inX = ex - inward * 16;
          dd =
            `M ${sx} ${ay} H ${outX - inward * r}` +
            ` Q ${outX} ${ay} ${outX} ${ay + r}` +
            ` V ${laneY - r}` +
            ` Q ${outX} ${laneY} ${outX + inward * r} ${laneY}` +
            ` H ${inX - inward * r}` +
            ` Q ${inX} ${laneY} ${inX} ${laneY - r}` +
            ` V ${by + r}` +
            ` Q ${inX} ${by} ${inX - inward * r} ${by}` +
            ` H ${ex}`;
        } else {
          // Two tables in one card: bow out into the left margin rather than
          // crossing the rows between them. Otherwise run the real gutter.
          const mid = sameCard ? CA.left - 22 : (sx + ex) / 2;
          const sweepDown = by > ay;
          const vSign = sweepDown ? 1 : -1;
          const canRound = Math.abs(by - ay) > r * 2 + 2;
          dd = canRound
            ? `M ${sx} ${ay} H ${mid - dirOut * r}` +
              ` Q ${mid} ${ay} ${mid} ${ay + vSign * r}` +
              ` V ${by - vSign * r}` +
              ` Q ${mid} ${by} ${mid + dirOut * r} ${by}` +
              ` H ${ex}`
            : `M ${sx} ${ay} H ${mid} V ${by} H ${ex}`;
        }
        next.push({
          d: dd,
          kind: wire.kind,
          depth: wire.depth,
          x1: sx,
          y1: ay,
          er: {
            many: { x: sx, y: ay, dir: dirOut },
            one: { x: ex, y: by, dir: (rightward ? -1 : 1) as 1 | -1 },
          },
        });
        continue;
      }

      // Leave and enter through whichever pair of edges the nodes actually
      // face, so a wire never crosses the box it starts from.
      const horizontal = Math.abs(bx - ax) >= Math.abs(by - ay);

      let x1: number, y1: number, x2: number, y2: number, d: string;

      // Spread arrivals along the target's edge. With n wires landing on one
      // card, offsets run symmetrically about its centre so the bundle
      // straddles the midline instead of piling onto a single point. Capped so
      // a busy target keeps its arrivals inside its own edge.
      const fk = fanKey[wireAt];
      const n = fk ? (fanSize.get(fk) ?? 1) : 1;
      const spread = n > 1 ? Math.min(30, (horizontal ? B.bottom - B.top : B.right - B.left) / (n + 1)) : 0;
      const fan = fk ? fanLane[wireAt] * spread : 0;

      // THE BUS.
      //
      // Five things write to the store. Routed individually they arrived on
      // three different edges of one card — two on the left, two dropping onto
      // the top 40px apart, two stacked on the right 20px apart — plus a long
      // haul crossing the canvas to get there. No per-edge routing fixes that;
      // six arrowheads on one box is six relationships competing for the same
      // landing strip.
      //
      // Infrastructure diagrams solve this with a bus: every writer drops onto
      // one shared lane above the target and the lane enters it once. Five
      // edges then read as one convergence, which is what it actually is.
      if (fk && n >= 3) {
        const laneY = B.top - 26;
        const enterX = (B.left + B.right) / 2;
        // Leave the source from whichever vertical edge faces the target, drop
        // to the lane, run along it, and descend once into the target.
        // A writer sitting ABOVE the lane drops out of its bottom edge. One
        // level with the target — admin shares the store's row — has no room
        // to drop, so it leaves from its own top edge and runs up, which drew
        // a stub poking out of the card. Those join the lane from the side
        // instead, at their nearest vertical edge.
        const above = A.bottom <= laneY;
        const startY = above ? A.bottom : A.top;
        const dropX = above ? ax : A.left <= B.right ? A.left : A.right;
        const busR = 7;
        const alongRight = enterX >= dropX ? 1 : -1;
        const canRound = Math.abs(enterX - dropX) > busR * 2 + 2 && Math.abs(laneY - startY) > busR * 2 + 2;
        const dd = canRound
          ? `M ${dropX} ${startY}` +
            ` V ${laneY - busR}` +
            ` Q ${dropX} ${laneY} ${dropX + alongRight * busR} ${laneY}` +
            ` H ${enterX - alongRight * busR}` +
            ` Q ${enterX} ${laneY} ${enterX} ${laneY + busR}` +
            ` V ${B.top - 3}`
          : `M ${dropX} ${startY} V ${laneY} H ${enterX} V ${B.top - 3}`;
        next.push({ d: dd, kind: wire.kind, depth: wire.depth, x1: dropX, y1: startY });
        continue;
      }

      // Orthogonal, not bezier.
      //
      // These are the plain card wires — every edge on the overview. They used
      // to draw as a cubic with a pull of up to 0.45x the distance, which is
      // what sent long links bowing straight through whatever card sat between
      // their endpoints. A curve cannot be told to avoid anything; it goes
      // where its control points send it.
      //
      // Architectural diagrams don't do that. C4, ER, and every Sugiyama-
      // layered renderer route edges as horizontal and vertical runs through
      // the space BETWEEN nodes, because an orthogonal path can be moved off
      // an obstacle one segment at a time while still arriving perpendicular
      // to the box it points at. Same three segments as the FK wires above, so
      // both wire systems read as one language.
      const r = 7;
      const clear = 18; // how far a detour stands off a card it routes around

      if (horizontal) {
        const rightward = bx > ax;
        x1 = rightward ? A.right : A.left;
        y1 = ay;
        x2 = rightward ? B.left : B.right;
        y2 = by + fan;
        const dir = rightward ? 1 : -1;
        const tip = x2 - dir * 3;

        // The corridor this wire turns in. Start at the midpoint of the gap,
        // then walk it clear of anything standing in the way: a vertical run
        // at `mid` must not cut through a card, or the line crosses content
        // exactly the way the old curve did.
        let mid = (x1 + x2) / 2;
        const top = Math.min(y1, y2);
        const bot = Math.max(y1, y2);
        // Settle rather than sweep once: pushing clear of one card can land
        // the corridor inside the next, and a single pass leaves it there.
        for (let pass = 0; pass < 3; pass++) {
          let moved = false;
          for (const box of obstacles) {
            if (box.el === cardA || box.el === cardB) continue;
            if (box.bottom < top - 1 || box.top > bot + 1) continue;
            if (mid > box.left - clear && mid < box.right + clear) {
              // Push the turn to whichever side of the blocker is nearer, but
              // never past the endpoint it has to reach.
              const left = box.left - clear;
              const right = box.right + clear;
              const pick = Math.abs(mid - left) <= Math.abs(mid - right) ? left : right;
              const to = dir > 0 ? Math.min(Math.max(pick, x1 + r), tip - r) : Math.max(Math.min(pick, x1 - r), tip + r);
              if (Math.abs(to - mid) > 0.5) moved = true;
              mid = to;
            }
          }
          if (!moved) break;
        }

        const vSign = y2 > y1 ? 1 : -1;
        const canRound = Math.abs(y2 - y1) > r * 2 + 2 && Math.abs(mid - x1) > r && Math.abs(tip - mid) > r;
        d = canRound
          ? `M ${x1} ${y1} H ${mid - dir * r}` +
            ` Q ${mid} ${y1} ${mid} ${y1 + vSign * r}` +
            ` V ${y2 - vSign * r}` +
            ` Q ${mid} ${y2} ${mid + dir * r} ${y2}` +
            ` H ${tip}`
          : Math.abs(y2 - y1) < 1
            ? `M ${x1} ${y1} H ${tip}`
            : `M ${x1} ${y1} H ${mid} V ${y2} H ${tip}`;
      } else {
        const downward = by > ay;
        x1 = ax;
        y1 = downward ? A.bottom : A.top;
        x2 = bx + fan;
        y2 = downward ? B.top : B.bottom;
        const dir = downward ? 1 : -1;
        const tip = y2 - dir * 3;

        let mid = (y1 + y2) / 2;
        const left = Math.min(x1, x2);
        const right = Math.max(x1, x2);
        for (let pass = 0; pass < 3; pass++) {
          let moved = false;
          for (const box of obstacles) {
            if (box.el === cardA || box.el === cardB) continue;
            if (box.right < left - 1 || box.left > right + 1) continue;
            if (mid > box.top - clear && mid < box.bottom + clear) {
              const above = box.top - clear;
              const below = box.bottom + clear;
              const pick = Math.abs(mid - above) <= Math.abs(mid - below) ? above : below;
              const to = dir > 0 ? Math.min(Math.max(pick, y1 + r), tip - r) : Math.max(Math.min(pick, y1 - r), tip + r);
              if (Math.abs(to - mid) > 0.5) moved = true;
              mid = to;
            }
          }
          if (!moved) break;
        }

        const hSign = x2 > x1 ? 1 : -1;
        const canRound = Math.abs(x2 - x1) > r * 2 + 2 && Math.abs(mid - y1) > r && Math.abs(tip - mid) > r;
        d = canRound
          ? `M ${x1} ${y1} V ${mid - dir * r}` +
            ` Q ${x1} ${mid} ${x1 + hSign * r} ${mid}` +
            ` H ${x2 - hSign * r}` +
            ` Q ${x2} ${mid} ${x2} ${mid + dir * r}` +
            ` V ${tip}`
          : Math.abs(x2 - x1) < 1
            ? `M ${x1} ${y1} V ${tip}`
            : `M ${x1} ${y1} V ${mid} H ${x2} V ${tip}`;
      }

      next.push({ d, kind: wire.kind, depth: wire.depth, x1, y1 });
    }
    setPaths(next);
  }, [canvasRef, nodes, wires, scale]);

  // Synchronous and pre-paint, so wires never render a frame behind the nodes.
  useLayoutEffect(() => {
    measure();
  }, [measure, version, reflowKey]);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    let frame = 0;
    const schedule = () => {
      if (frame) return;
      frame = requestAnimationFrame(() => {
        frame = 0;
        measure();
      });
    };

    // Capture phase: scroll does not bubble, so a scrollable canvas pane would
    // otherwise go unheard.
    window.addEventListener("scroll", schedule, true);
    window.addEventListener("resize", schedule);
    const ro = new ResizeObserver(schedule);
    ro.observe(canvas);
    return () => {
      if (frame) cancelAnimationFrame(frame);
      window.removeEventListener("scroll", schedule, true);
      window.removeEventListener("resize", schedule);
      ro.disconnect();
    };
  }, [canvasRef, measure]);

  if (paths.length === 0) return null;

  return (
    <svg
      className="pointer-events-none absolute inset-0 z-10 hidden md:block"
      width={size.w}
      height={size.h}
      aria-hidden="true"
    >
      <defs>
        {(Object.keys(STROKE) as WireKind[]).map((kind) => (
          <marker
            key={kind}
            id={`arrow-${kind}`}
            viewBox="0 0 10 10"
            refX="8.5"
            refY="5"
            // Stroked chevron, not a filled wedge — a solid triangle reads as
            // an arrow bolted onto the wire. But at markerWidth 4 against a
            // 1.5px stroke it was invisible at overview zoom, which left every
            // edge undirected: you could see two cards were related and not
            // which way it ran. Direction is half the information in a flow
            // diagram, so it has to survive a glance.
            markerWidth="7"
            markerHeight="7"
            orient="auto-start-reverse"
          >
            <path
              d="M 2.5 2 L 8 5 L 2.5 8"
              fill="none"
              stroke={STROKE[kind]}
              strokeWidth="1.6"
              strokeLinecap="round"
              strokeLinejoin="round"
            />
          </marker>
        ))}
      </defs>
      {paths.map((p, i) => {
        // Fade with distance from the focused node, so its direct edges stay
        // the loudest thing on the canvas.
        const opacity = Math.max(0.2, 0.92 - p.depth * 0.24);
        if (p.er) {
          // ER relationship: crow's foot at the referencing column, single bar
          // at the referenced key. Cardinality IS the information here, so the
          // terminals carry it rather than a generic arrowhead.
          const { many, one } = p.er;
          const s = STROKE[p.kind];
          const w = p.depth === 0 ? 1.3 : 1.1;
          return (
            <g key={i} opacity={opacity} stroke={s} strokeWidth={w} fill="none" strokeLinecap="round">
              <path d={p.d} strokeDasharray={DASHED[p.kind]} />
              {/* many: three splayed lines opening away from the column */}
              <path
                d={`M ${many.x + many.dir * 9} ${many.y - 4.5} L ${many.x} ${many.y}` +
                   ` M ${many.x + many.dir * 9} ${many.y} L ${many.x} ${many.y}` +
                   ` M ${many.x + many.dir * 9} ${many.y + 4.5} L ${many.x} ${many.y}`}
              />
              {/* one: a single bar across the line */}
              <path d={`M ${one.x + one.dir * 7} ${one.y - 4.5} L ${one.x + one.dir * 7} ${one.y + 4.5}`} />
            </g>
          );
        }
        return (
          <g key={i} opacity={opacity}>
            <path
              d={p.d}
              fill="none"
              stroke={STROKE[p.kind]}
              strokeWidth={p.depth === 0 ? 1.5 : 1.15}
              strokeLinecap="round"
              strokeDasharray={DASHED[p.kind]}
              markerEnd={`url(#arrow-${p.kind})`}
            />
            {/* Origin dot — the wire's other terminal. Small enough to read as
                a node on the thread rather than a bullet. */}
            <circle cx={p.x1} cy={p.y1} r={2} fill={STROKE[p.kind]} />
          </g>
        );
      })}
    </svg>
  );
}

export function WireLegend() {
  return (
    <div className="hidden flex-wrap items-center gap-x-5 gap-y-2 md:flex">
      <LegendKey kind="derived" label="Resolved by the compiler" />
      <LegendKey kind="partial" label="Found, known incomplete" />
      <LegendKey kind="alarm" label="Unproven — worth a look" />
      <LegendKey kind="inferred" label="Guessed from layout" />
    </div>
  );
}

function LegendKey({ kind, label }: { kind: WireKind; label: string }) {
  return (
    <span className="flex items-center gap-1.5 text-[12px] text-muted-slate">
      <svg width="24" height="8" aria-hidden="true">
        <path
          d="M 1 4 L 23 4"
          stroke={STROKE[kind]}
          strokeWidth="2"
          strokeLinecap="round"
          strokeDasharray={DASHED[kind]}
        />
      </svg>
      {label}
    </span>
  );
}

ui/lib/data.ts:
/**
 * Fixture for the prototype. No repository is analysed — this is the shape a
 * real `understand-slop map` run would emit for a mid-size SaaS codebase.
 *
 * The map is organised by CONCEPT, not by file. Someone new to a codebase asks
 * "how does billing work" and "what's in the database", not "what's in
 * identity.ts". Files appear only at the bottom, as the evidence for a claim.
 *
 * Every fact carries a state. `derived` is resolved by the TypeScript compiler
 * or read straight out of a migration; `partial` was found but the analysis
 * knows it is incomplete (and says why); `inferred` is a guess from naming or
 * layout and is never presented as fact.
 */

import type { Shape } from "@/lib/view";

export type State = "derived" | "partial" | "inferred";

/* ── anatomy: level 2 renders in the SHAPE of the thing ───────
   A database capability shows columns. An API capability shows routes. A
   pipeline shows ordered steps. One prose paragraph for all three would throw
   away the structure that makes each legible. */

export interface Column {
  name: string;
  type: string;
  key?: "PK" | "FK" | "UQ";
  nullable?: boolean;
  state: State;
  note?: string;
}

export interface Route {
  method: "GET" | "POST" | "PATCH" | "DELETE";
  path: string;
  auth: string;
  state: State;
  note?: string;
}

export interface Step {
  n: number;
  title: string;
  detail: string;
  state: State;
  /** What happens inside this step. Same contract as `Mapping.under`. */
  under?: Anatomy[];
}

export interface Pair {
  label: string;
  value: string;
  state: State;
}

/**
 * The bottom of the map. Real source, quoted verbatim from a real file at a
 * real line — never paraphrased, never reconstructed from memory. `why` is the
 * one place a synthesized explanation is allowed, and it is separated from the
 * code so nobody mistakes the commentary for the thing itself.
 */
export interface Source {
  kind: "source";
  /** Repo-relative path. */
  file: string;
  /** Line number of `code`'s first line, so the gutter tells the truth. */
  start: number;
  /** Verbatim. Leading indentation preserved. */
  code: string;
  /** Why it is this way. Synthesized — rendered as commentary, not as fact. */
  why?: string;
}

/**
 * A quantity worth comparing. `value` is what draws the bar; `display` is what
 * a human reads, because "40 per day, 10 per hour" is the fact and 40 is only
 * the part of it that has a length.
 */
export interface Bar {
  label: string;
  value: number;
  display: string;
  state: State;
  note?: string;
}

/**
 * One slice of a whole. Used where the RATIO is the finding — three prompt
 * blocks whose sizes are the entire reason the split exists read as a bar in
 * one glance and as an essay in three rows.
 */
export interface Part {
  label: string;
  weight: number;
  display: string;
  /** Tints the slice: the thing being contrasted, not decoration. */
  tone?: "hold" | "vary";
  state: State;
}

/** One accepted kind of thing. The label IS the content; no sentence needed. */
export interface Chip {
  label: string;
  note?: string;
  state: State;
}

/** A rewrite rule: what goes in, what comes out. */
export interface Mapping {
  from: string;
  to: string;
  state: State;
  /**
   * What actually happens between `from` and `to`. An arrow is a summary of a
   * path, and for some rows the path is the question — "image → base64 image
   * block" is four stages in three files drawn as one hop.
   *
   * Deliberately `Anatomy[]` and not `Node[]`. A node owns a grid position, a
   * camera frame and a wire anchor; a row that opened one would push the
   * deepest level past the viewport, which is the failure D8 records after
   * twelve attempts. This expands in place instead — the camera never moves,
   * so no framing maths is involved at all.
   *
   * A row with no `under` is a row whose arrow really is the whole fact. Most
   * rows are that, and adding this everywhere would restate the summary one
   * click down, which is the clutter this tool exists to avoid.
   */
  under?: Anatomy[];
}

/** One message in a `sequence`: who asks whom for what, in order. */
export interface Message {
  /** Must be one of the block's `actors`. */
  from: string;
  to: string;
  /** Plain words: "sends the email and a made-up password". */
  label: string;
  note?: string;
  state: State;
}

/**
 * One thing on a screen, top to bottom, read out of the JSX. Not a mock-up: a
 * list of what is there, so a reader knows what the user sees and taps.
 */
export interface ScreenItem {
  type: "heading" | "text" | "field" | "choice" | "button" | "list" | "image";
  label: string;
  /** What happens or what it holds: "must be 8+ characters", "opens RSVP". */
  note?: string;
}

/**
 * A place in the repository behind a node. Read live from disk when the reader
 * opens the code — never pasted — so it is available on EVERY level without
 * the fixture carrying a copy that can drift.
 */
export interface CodeRef {
  file: string;
  /** 1-indexed, inclusive. */
  start: number;
  end: number;
  /** Plain words: what these lines do. */
  label: string;
}

/** Something a developer should know before they touch this. */
export interface Issue {
  /** Plain words, a few: "Anyone can delete any account". */
  title: string;
  /** What goes wrong, for whom, and when. One to three sentences. */
  detail: string;
  /** file:line where it happens. */
  where?: string;
}

/**
 * A box in a `diagram`, placed on a grid: `col` left to right, `row` top to
 * bottom, both from 0. The renderer does the geometry, so a figure is authored
 * as WHAT connects to what, never as coordinates.
 */
export interface DiagramBox {
  id: string;
  /** 1-4 words. */
  label: string;
  /** A few words under the label: "row with this id". */
  sub?: string;
  col: number;
  row: number;
  /** `good` = where things end up fine; `warn` = a problem or dead end. */
  tone?: "plain" | "good" | "warn";
  /**
   * The id of the child node this box is part of (D40). The box then opens
   * that part, so the picture is the way down and the list below it is a
   * fallback, not the only route.
   *
   * Boxes outnumber parts — a level draws ~8 boxes and owns ~4 parts — and the
   * two name different things: a box is a thing at runtime (`individual
   * table`), a part is a chapter about it (`Checking Who You Are`). So the
   * link is authored, never matched on the label, and a box with no `opens`
   * stays inert scenery rather than promising a click it cannot honour.
   */
  opens?: string;
}

export interface DiagramArrow {
  from: string;
  to: string;
  /** A few words on the line: "not found", "publishes". */
  label?: string;
  tone?: "plain" | "good" | "warn";
  /**
   * `file:line` where this path happens in the code. Not drawn — the generator
   * must cite one and the checker confirms the line exists, so "every arrow is
   * a real path" (D19) is checked rather than trusted.
   */
  at?: string;
}

export type Anatomy =
  // How the pieces connect — the main picture of a level. Every arrow is a
  // real path in the code (D19); a dead end is drawn `warn`, not left out.
  | { kind: "diagram"; caption: string; boxes: DiagramBox[]; arrows: DiagramArrow[] }
  // The real values, as a table: the categories themselves, the 61 campuses,
  // the fields a form sends. One column is a list.
  | { kind: "table"; caption?: string; columns: string[]; rows: string[][]; state: State }
  // Who talks to whom, in order — phone, Supabase, email, a table.
  | { kind: "sequence"; caption?: string; actors: string[]; rows: Message[] }
  // What the user sees on one screen. `shot` is a real capture of the app
  // (scripts/capture/phone.mjs, sample data), served from ui/public — e.g.
  // "/shots/explorify/ce-home.png". With a shot, `items` that carry a `note`
  // become the callouts beside it; without one, `items` are drawn (D37).
  | { kind: "screen"; title: string; caption?: string; shot?: string; items: ScreenItem[] }
  // What a stored value looks like. Synthesized and labelled as an example.
  | { kind: "example"; caption: string; value: string; notes?: Pair[] }
  | { kind: "schema"; table: string; rows: Column[]; rel?: string[] }
  | { kind: "routes"; rows: Route[] }
  | { kind: "flow"; rows: Step[] }
  | { kind: "facts"; rows: Pair[] }
  // Measured against each other. A number nobody can compare is just text.
  | { kind: "bars"; unit: string; rows: Bar[] }
  // Measured against the whole.
  | { kind: "parts"; total: string; rows: Part[] }
  // A closed set. Five one-line sentences describing five accepted formats is
  // an essay about a list; the list itself is the fact.
  | { kind: "chips"; caption?: string; rows: Chip[] }
  // in → out. A mapping drawn as a mapping.
  | { kind: "map"; caption?: string; rows: Mapping[] }
  | Source;

export interface Node {
  id: string;
  /**
   * The thing's own name, 1-3 words, Title Case. A LABEL, not a sentence.
   *
   * The board shipped with prose here — "Agreeing to be read", "Where it all
   * lands" — and a reader cannot tell from those what part of the product they
   * name, so the first level read as ten riddles. The sentence belongs in
   * `sub`. See `lib/view.ts`.
   */
  title: string;
  /** One line, plain English. What this IS — never a file path. */
  sub: string;
  /**
   * Where this card's code actually lives: the direct answer to "what belongs
   * to what". Features cut across directories (`identity` spans
   * `app/(protected)`, `lib/rules` and `app/api`), so the footprint is stated
   * rather than left to be inferred from the title.
   */
  footprint?: { dirs: string[]; files: number };
  /**
   * Set on cards holding more rows than `CARD_ROWS_SOFT`: the shape of what is
   * inside, so the reader knows what they are scrolling before they scroll it.
   * e.g. "13 formulas, one per 1040-NR line".
   */
  summary?: string;
  /** How this node's CHILDREN relate to each other. */
  group?: Group;
  /**
   * Something to recognise before reading anything: brand marks for the real
   * technologies involved, a small diagram where the arrangement is the
   * finding, or a single number. See `Shape` in `lib/view.ts`.
   *
   * Only ever drawn from facts the analysis actually has. A card with nothing
   * true to draw gets none — an invented diagram is an invented arrow (D19).
   */
  shape?: Shape;
  state: State;
  alarm?: boolean;
  ghost?: boolean;
  col: number;
  row: number;
  /**
   * At most two short sentences (≤ 40 words) — the one thing to know before
   * looking at the pictures. Everything else is a block: steps are a `flow` or
   * `sequence`, connections a `diagram`, values a `table`. A paragraph that
   * explains the code is exactly what this tool replaces (D38).
   */
  detail?: string;
  /** Where this lives in the code. Every authored node has at least one. */
  code?: CodeRef[];
  /** Known problems, shown as "Watch out" on this level. */
  issues?: Issue[];
  /**
   * Why this is not certain, in plain words. Required when `state` is not
   * `derived` — a mark with no reason is the "what does partial mean" defect.
   */
  unsure?: string;
  /** Where the claim came from. Always a real location. */
  evidence?: string;
  anatomy?: Anatomy[];
  /**
   * What is underneath. Depth is a property of the BRANCH, not a global level:
   * a node with children can be opened, one without is a leaf, and nothing
   * caps how far that nests. Some branches stop at two because nothing
   * different lives below them; the ones that keep going do so because each
   * level answers a question its parent could not.
   */
  children?: Node[];
  /** Edges among this node's own children, drawn when it is the open node. */
  edges?: Edge[];
  /**
   * Synthesized from a row that carried `under`, rather than authored.
   *
   * The distinction is what a level MEANS. Authored children are siblings you
   * are meant to see together — "Subject and mode" next to "What you can send"
   * is a comparison. Row children are answers to six different questions, and
   * you asked one: rendering the other five is the wall of context this tool
   * exists to remove. `Branch` shows only the row child on the open path.
   */
  fromRow?: boolean;
}

export interface Edge {
  from: string;
  to: string;
  state: State;
  alarm?: boolean;
  label?: string;
  /**
   * Position in a real sequence, 1-indexed.
   *
   * An edge claims that `from` genuinely precedes `to` — a pipeline stage, a
   * request path, an ordered write. Siblings with no true ordering get no edge
   * at all and render as a SET (see `Group.ordering`), because inventing
   * arrows to make a level look like a diagram turns a weak claim into a
   * confident-looking one.
   */
  order?: number;
  /**
   * The branch this edge belongs to, where the path splits — e.g. students and
   * organisations after launch routing. Edges sharing a lane form one ordered
   * branch; its first edge leaves the fork node. An edge with no `order` is a
   * hand-off between branches, not a step.
   */
  lane?: string;
}

/**
 * How a set of siblings relates to each other.
 *
 * The board shipped with 6 edges, all at the root, and none below it — so
 * every level past the first was a silent pile of cards with no stated
 * relationship. Saying "these are unordered" is information; saying nothing
 * reads as missing analysis.
 */
export interface Group {
  ordering: "sequence" | "set";
  /** Shown when `set`: why these belong together despite having no order. */
  note?: string;
}

