/* ── row-level links ──────────────────────────────────────────
   The edges developers actually want to trace. Endpoints are ROWS, not cards:
   a foreign key points at the exact column it references, a route points at
   the step that serves it. Card-to-card edges ("Billing relates to Database")
   are nearly contentless; these are the ones that answer a question.

   Row id = `${capabilityId}:${rowKey}` — see rowId() below. */

export interface Link {
  from: string;
  to: string;
  state: State;
  alarm?: boolean;
  label?: string;
}

/** One mapping run: which repository, at which commit, and how it is cut. */
export interface Run {
  command: string;
  /** Directory name under ~/Desktop/Code — also where the code level reads. */
  repo: string;
  /** One sentence: what the top level is cut by, and why that order. */
  about: string;
  commit: string;
  files: number;
  elapsed: string;
  /** Absolute path of the mapped checkout. Set by the generator; overrides `repo`. */
  root?: string;
  /** Which model ran each generator stage. Absent on hand-authored maps. */
  models?: Record<string, string>;
  /** Web address of the repository, read from the checkout's git remote when the page is built. */
  url?: string;
}

/** Stable id for an anatomy row, so a wire can anchor to it. */
export function rowId(owner: string, key: string | number) {
  return `${owner}:${key}`;
}

export const LINKS: Link[] = [
  // Foreign keys — the classic thing you trace through a schema.
  { from: rowId("bill-subs", "org_id"), to: rowId("db-orgs", "id"), state: "derived", label: "FK" },
  { from: rowId("db-projects", "org_id"), to: rowId("db-orgs", "id"), state: "derived", label: "FK" },
  { from: rowId("db-projects", "created_by"), to: rowId("db-users", "id"), state: "derived", label: "FK" },
  { from: rowId("db-orgs", "user_id"), to: rowId("db-users", "id"), state: "derived", label: "FK" },
  { from: rowId("db-orgs", "org_id"), to: rowId("db-orgs", "id"), state: "derived", label: "FK" },
  { from: rowId("db-orgs", "invited_by"), to: rowId("db-users", "id"), state: "derived", label: "FK" },

  // Write paths — which step writes which column.
  { from: rowId("bill-checkout", 4), to: rowId("bill-subs", "stripe_subscription_id"), state: "derived", label: "writes" },
  { from: rowId("bill-hooks", "checkout.session.completed"), to: rowId("bill-subs", "status"), state: "derived", label: "writes" },
  { from: rowId("bill-hooks", "customer.subscription.updated"), to: rowId("bill-subs", "seats"), state: "derived", label: "writes" },
  { from: rowId("bill-hooks", "customer.subscription.updated"), to: rowId("bill-subs", "current_period_end"), state: "derived", label: "writes" },
  { from: rowId("bill-hooks", "customer.subscription.deleted"), to: rowId("bill-subs", "canceled_at"), state: "derived", label: "writes" },

  // Reads — an auth claim read out of a column. Both endpoints moved when the
  // session card became a lifecycle: "Claims" is now step 1 (minted, where the
  // claims are written) and "Transport" is step 2 (set as a cookie).
  { from: rowId("auth-session", 1), to: rowId("db-orgs", "role"), state: "derived", label: "reads" },
  { from: rowId("auth-signin", 2), to: rowId("db-users", "email"), state: "derived", label: "looks up" },
  { from: rowId("auth-signin", 4), to: rowId("auth-session", 2), state: "derived", label: "sets" },

  // Routes into the write path.
  { from: rowId("api-projects", "POST /api/projects"), to: rowId("proj-crud", 1), state: "derived", label: "handled by" },
  { from: rowId("proj-crud", 3), to: rowId("db-projects", "org_id"), state: "derived", label: "writes" },
  { from: rowId("proj-crud", 4), to: rowId("jobs-queue", "reindexProject"), state: "derived", label: "enqueues" },
  { from: rowId("api-projects", "POST /api/projects/[id]/files"), to: rowId("proj-uploads", 2), state: "derived", label: "handled by" },
  { from: rowId("proj-uploads", 4), to: rowId("db-projects", "settings"), state: "partial", label: "unconfirmed uploads orphan" },

  // The alarming one: the webhook route is swept in by the middleware glob.
  { from: rowId("api-webhooks", "POST /api/webhooks/stripe"), to: rowId("bill-hooks", "Rate limited"), state: "partial", alarm: true, label: "rate limited by IP" },

  // The storage level collapsed, taking `st-s3:Key layout` with it. The link it
  // anchored was the weakest in the fixture — an `inferred` guess that an S3
  // key string contains a project id, drawn from naming alone. Re-pointing it
  // at the domain card would have preserved a wire by making it vaguer, which
  // is the trade this whole pass exists to stop making.
];

/** Every link touching a row, in both directions. */
export function linksFor(id: string) {
  return LINKS.filter((l) => l.from === id || l.to === id);
}

ui/lib/diagram.ts:
import type { Anatomy, DiagramArrow, DiagramBox } from "@/lib/data";

/**
 * Where everything in a diagram goes, as plain numbers: the component draws
 * it, and `scripts/generate/audit-diagrams.mts` checks every map's diagrams
 * for text drawn over text without opening a browser. Text widths are
 * estimated from character counts, which is close enough at these fixed sizes.
 */

export const BOX_H = 58;
/** Width a corner badge needs beside the longest label on a live box. */
export const CUE_ROOM = 26;
const ROW_GAP = 40;
const COL_GAP = 76;
const PAD = 18;
const LANE_GAP = 12;
/** Two arrows running opposite ways down one column sit this far apart. */
const PAIR_GAP = 7;
const LABEL_CHAR = 6.6;
const LABEL_H = 14;

type Block = Extract<Anatomy, { kind: "diagram" }>;
type Placed = { x: number; y: number; w: number };
export type Rect = { x: number; y: number; w: number; h: number };
export type PlacedBox = Placed & { b: DiagramBox };
export type PlacedArrow = {
  from: string;
  to: string;
  d: string;
  tone: NonNullable<DiagramArrow["tone"]>;
  label?: { text: string; x: number; y: number; anchor: "start" | "middle" | "end" };
};

export function labelRect(l: NonNullable<PlacedArrow["label"]>): Rect {
  const w = l.text.length * LABEL_CHAR;
  const x = l.anchor === "start" ? l.x : l.anchor === "middle" ? l.x - w / 2 : l.x - w;
  return { x, y: l.y - 11, w, h: LABEL_H };
}

export const overlaps = (a: Rect, b: Rect) =>
  a.x < b.x + b.w && b.x < a.x + a.w && a.y < b.y + b.h && b.y < a.y + a.h;

export function layoutDiagram(block: Block) {
  const cols = Math.max(...block.boxes.map((b) => b.col)) + 1;
  const rows = Math.max(...block.boxes.map((b) => b.row)) + 1;
  // Each column is as wide as its longest label. A box that opens a part also
  // has to fit its badge in the top-right corner, so it reserves the room
  // rather than letting the badge sit on the label.
  const colW = Array.from({ length: cols }, (_, c) =>
    Math.max(
      150,
      ...block.boxes
        .filter((b) => b.col === c)
        .map((b) => Math.max(b.label.length * 8.4 + (b.opens ? CUE_ROOM : 0), (b.sub?.length ?? 0) * LABEL_CHAR) + 32),
    ),
  );
  // The gap between columns is as wide as the longest straight-across label
  // that has to sit in it; a fixed 76px clipped any label past ten characters
  // under the next box. Elbow labels sit between rows, clear of the boxes, so
  // they need no room here. Capped, so one label cannot push the picture off
  // the page.
  const gap = Math.min(
    260,
    Math.max(
      COL_GAP,
      ...block.arrows.map((a) => {
        const f = block.boxes.find((b) => b.id === a.from);
        const t = block.boxes.find((b) => b.id === a.to);
        if (!a.label || !f || !t || f.col === t.col || f.row !== t.row) return 0;
        return a.label.length * LABEL_CHAR + 28;
      }),
    ),
  );
  const colX = colW.map((_, c) => PAD + colW.slice(0, c).reduce((a, w) => a + w + gap, 0));
  let W = colX[cols - 1] + colW[cols - 1] + PAD;
  const H = PAD * 2 + rows * BOX_H + (rows - 1) * ROW_GAP;
  const at = new Map<string, PlacedBox>(
    block.boxes.map((b) => [b.id, { x: colX[b.col], y: PAD + b.row * (BOX_H + ROW_GAP), w: colW[b.col], b }]),
  );

  // Arrows between the same two boxes the same way are one line: their labels
  // are joined rather than drawn on the same spot (the overlap a reader
  // reported, "sidebar link" over "post dropdown").
  const merged: (DiagramArrow & { labels: string[] })[] = [];
  for (const a of block.arrows) {
    if (!at.has(a.from) || !at.has(a.to)) continue;
    const same = merged.find((m) => m.from === a.from && m.to === a.to);
    if (same) {
      if (a.label && !same.labels.includes(a.label)) same.labels.push(a.label);
      continue;
    }
    merged.push({ ...a, labels: a.label ? [a.label] : [] });
  }

  const boxRects: Rect[] = [...at.values()].map(({ x, y, w }) => ({ x, y, w, h: BOX_H }));
  // Where a line may run clear of every box: down the middle of each gap
  // between columns, and along the middle of each gap between rows.
  const gx = colX.slice(1).map((x) => x - gap / 2);
  const gy = Array.from({ length: rows - 1 }, (_, r) => PAD + (r + 1) * (BOX_H + ROW_GAP) - ROW_GAP / 2);
  const lanes = laneOffsets(merged, at);
  const drawn: { seg: Rect; from: string; to: string }[] = [];
  const routes = merged.map((a, i) => {
    const f = at.get(a.from)!;
    const t = at.get(a.to)!;
    // A and B in one column, arrows both ways: side by side, not one line.
    const back = f.x === t.x && merged.some((m) => m.from === a.to && m.to === a.from);
    const first = route(f, t, gap, back ? (t.y > f.y ? -PAIR_GAP : PAIR_GAP) : (lanes.get(i) ?? 0));
    // The plain route unless it cuts through a box or runs along another
    // arrow's line; then the cheapest detour that does neither. A fan-out or
    // fan-in sharing its trunk is the bundle reading as one, so it is free.
    const cost = (pts: Pt[], bonus = 0) => {
      const segs = segmentsOf(pts);
      let c = bonus;
      for (const s of segs) {
        c += s.w + s.h + 30;
        for (const b of boxRects) if (overlaps(s, inset(b))) c += 10000;
        for (const o of drawn) if (o.from !== a.from && o.to !== a.to) c += 20 * collinear(s, o.seg);
      }
      return c;
    };
    let best = { pts: first, c: cost(first, -20) };
    for (const pts of detours(f, t, gx, gy)) {
      const c = cost(pts);
      if (c < best.c) best = { pts, c };
    }
    for (const seg of segmentsOf(best.pts)) drawn.push({ seg, from: a.from, to: a.to });
    return best;
  });

  const arrows: PlacedArrow[] = merged.map((a, i) => ({
    from: a.from,
    to: a.to,
    d: `M${routes[i].pts.map((p) => p.join(" ")).join("L")}`,
    tone: a.tone ?? "plain",
    // Placed below, once every line is down.
    label: a.labels.length ? { text: a.labels.join(" · "), x: 0, y: 0, anchor: "start" as const } : undefined,
  }));

  // A label that lands on a box, another label or another arrow's line
  // moves until it is clear, to the nearest spot still beside its own line.
  const taken: Rect[] = [];
  const W0 = W;
  const runsOf = routes.map((r) => segmentsOf(r.pts));
  arrows.forEach((a, i) => {
    if (!a.label) return;
    const others = drawn.filter((d) => d.from !== a.from || d.to !== a.to).map((d) => d.seg);
    // Text on text or on a box is unreadable; text across a line is drawn
    // with a halo and stays legible, so it is only a mild cost.
    const clashes = (r: Rect) => {
      const room = { x: r.x - 3, y: r.y - 3, w: r.w + 6, h: r.h + 6 };
      // Past the right edge widens the picture, which can push it into a
      // scroll that hides the label's end: better on the line's other side.
      const out = (r.y < 0 || r.y + r.h > H || r.x < 0 ? 1000 : 0) + (r.x + r.w + PAD > W0 ? 50 : 0);
      return out + 100 * [...boxRects, ...taken].filter((o) => overlaps(room, o)).length + others.filter((o) => overlaps(room, o)).length;
    };
    // A run another arrow also draws — a fan-in's trunk — names none of them,
    // so a label goes on a run that is this arrow's alone when it can.
    const shared = runsOf[i].map((s) => runsOf.some((rs, j) => j !== i && rs.some((o) => collinear(s, o) > 4)));
    const spots = spotsOn(routes[i].pts, a.label.text.length * LABEL_CHAR, shared);
    let fit = spots[0], least = Infinity;
    for (const s of spots) {
      // Beside a shared run is a last resort: worse than crossing a line.
      const c = clashes(labelRect({ ...a.label, ...s })) + (s.shared ? 5 : 0);
      if (c < least) [fit, least] = [s, c];
      if (!c) break;
    }
    Object.assign(a.label, { x: fit.x, y: fit.y, anchor: fit.anchor });
    const r = labelRect(a.label);
    taken.push(r);
    W = Math.max(W, r.x + r.w + PAD);
  });

  return { W, H, gap, boxes: [...at.values()], boxRects, arrows, labels: taken };
}

type Pt = [number, number];
type Label = { x: number; y: number; anchor: "start" | "middle" | "end"; shared?: boolean };

/** The straight runs of a polyline, as zero-thickness rects. */
export function segmentsOf(pts: Pt[]): Rect[] {
  return pts.slice(1).map(([x, y], i) => {
    const [px, py] = pts[i];
    return { x: Math.min(x, px), y: Math.min(y, py), w: Math.abs(x - px) || 0.1, h: Math.abs(y - py) || 0.1 };
  });
}

const inset = (b: Rect): Rect => ({ x: b.x + 1, y: b.y + 1, w: b.w - 2, h: b.h - 2 });

/** How far two runs lie along the same line. */
function collinear(a: Rect, b: Rect) {
  const horiz = (r: Rect) => r.h < 1;
  if (horiz(a) !== horiz(b)) return 0;
  if (horiz(a)) return Math.abs(a.y - b.y) < 4 ? Math.max(0, Math.min(a.x + a.w, b.x + b.w) - Math.max(a.x, b.x)) : 0;
  return Math.abs(a.x - b.x) < 4 ? Math.max(0, Math.min(a.y + a.h, b.y + b.h) - Math.max(a.y, b.y)) : 0;
}

/**
 * Every place a label can sit and still read as this line's: beside a run,
 * slid along it or on its other side — never off it, where it would be read
 * as naming whatever line is nearest. Runs no other arrow shares come first,
 * longest first; a short one takes its label at either end, beside the box
 * it leaves or enters, rather than centred over the line it joins.
 */
function spotsOn(pts: Pt[], width: number, shared: boolean[]): Label[] {
  const runs = pts.slice(1).map(([x2, y2], i) => ({ x1: pts[i][0], y1: pts[i][1], x2, y2, len: Math.abs(x2 - pts[i][0]) + Math.abs(y2 - pts[i][1]), shared: Boolean(shared[i]) }));
  return runs
    .sort((a, b) => Number(a.shared) - Number(b.shared) || b.len - a.len)
    .flatMap(({ x1, y1, x2, y2, len, shared }): Label[] => spotsBeside(x1, y1, x2, y2, len, width).map((l) => ({ ...l, shared })));
}

/** Beside one run: slid along it or on its other side. */
function spotsBeside(x1: number, y1: number, x2: number, y2: number, len: number, width: number): Label[] {
  if (x1 === x2) {
    const mid = (y1 + y2) / 2 + 4;
    const room = Math.max(0, len / 2 - 10);
    return [0, -14, 14, -28, 28, -42, 42]
      .filter((d) => Math.abs(d) <= room)
      .flatMap((d): Label[] => [{ x: x1 + 8, y: mid + d, anchor: "start" }, { x: x1 - 8, y: mid + d, anchor: "end" }]);
  }
  const mid = (x1 + x2) / 2;
  const room = Math.max(0, (len - width) / 2);
  const right = x2 > x1;
  const ends: Label[] =
    len < width + 16
      ? [y1 - 6, y1 + 15].flatMap((y): Label[] => [
          { x: x1 + (right ? 4 : -4), y, anchor: right ? "start" : "end" },
          { x: x2 + (right ? -6 : 6), y, anchor: right ? "end" : "start" },
        ])
      : [];
  return [
    ...[0, -30, 30, -60, 60, -90, 90]
      .filter((d) => Math.abs(d) <= room)
      .flatMap((d): Label[] => [{ x: mid + d, y: y1 - 6, anchor: "middle" }, { x: mid + d, y: y1 + 15, anchor: "middle" }]),
    ...ends,
  ];
}

/**
 * The other ways from one box to another: out a side, down a column gap and
 * in a side; or out the top or bottom, along a row gap and in the top or
 * bottom.
 */
function detours(f: Placed, t: Placed, gx: number[], gy: number[]): Pt[][] {
  const out: Pt[][] = [];
  const fy = f.y + BOX_H / 2;
  const ty = t.y + BOX_H / 2;
  for (const g of gx) {
    const x1 = g > f.x ? f.x + f.w : f.x;
    const x2 = g > t.x ? t.x + t.w + 2 : t.x - 2;
    out.push([[x1, fy], [g, fy], [g, ty], [x2, ty]]);
  }
  const fc = f.x + f.w / 2;
  const tc = t.x + t.w / 2;
  if (fc !== tc)
    for (const g of gy) {
      const y1 = g > f.y ? f.y + BOX_H : f.y;
      const y2 = g > t.y ? t.y + BOX_H + 2 : t.y - 2;
      out.push([[fc, y1], [fc, g], [tc, g], [tc, y2]]);
    }
  return out;
}

/**
 * Elbow arrows that run down the same gap between columns would draw on top
 * of each other. A fan-out from one box, or a fan-in to one box, SHOULD share
 * its trunk — that is what makes it read as one bundle — so arrows are
 * grouped into bundles per gap and each bundle gets its own lane.
 */
function laneOffsets(arrows: { from: string; to: string }[], at: Map<string, Placed>) {
  const gaps = new Map<string, { i: number; from: string; to: string }[]>();
  arrows.forEach((a, i) => {
    const f = at.get(a.from);
    const t = at.get(a.to);
    if (!f || !t || f.x === t.x || f.y === t.y) return;
    const key = t.x > f.x ? `r${f.x + f.w}` : `l${f.x}`;
    gaps.set(key, [...(gaps.get(key) ?? []), { i, from: a.from, to: a.to }]);
  });
  const out = new Map<number, number>();
  for (const list of gaps.values()) {
    const count = (k: "from" | "to", v: string) => list.filter((x) => x[k] === v).length;
    const bundleOf = (x: { from: string; to: string }) =>
      count("from", x.from) > 1 ? `f:${x.from}` : count("to", x.to) > 1 ? `t:${x.to}` : `a:${x.from}>${x.to}`;
    const bundles = [...new Set(list.map(bundleOf))];
    for (const x of list) {
      const b = bundles.indexOf(bundleOf(x));
      out.set(x.i, (b - (bundles.length - 1) / 2) * LANE_GAP);
    }
  }
  return out;
}

/**
 * The plain right-angled path between two boxes. Same column: straight down
 * (or up), shifted sideways by `lane`. Otherwise out of the facing side,
 * along the gap between columns, and in.
 */
function route(f: Placed, t: Placed, gap: number, lane = 0): Pt[] {
  const fy = f.y + BOX_H / 2;
  const ty = t.y + BOX_H / 2;
  if (f.x === t.x) {
    const down = t.y > f.y;
    const y1 = down ? f.y + BOX_H : f.y;
    const y2 = down ? t.y - 2 : t.y + BOX_H + 2;
    const cx = f.x + f.w / 2 + lane;
    return [[cx, y1], [cx, y2]];
  }
  const right = t.x > f.x;
  const x1 = right ? f.x + f.w : f.x;
  const x2 = right ? t.x - 2 : t.x + t.w + 2;
  if (fy === ty) return [[x1, fy], [x2, fy]];
  const mx = (right ? x1 + gap / 2 : x1 - gap / 2) + lane;
  return [[x1, fy], [mx, fy], [mx, ty], [x2, ty]];
}

ui/lib/explorify/index.ts:
/**
 * explorify — a real repository, read at ~/Desktop/Code/explorify, commit 304a512
 * (59a89b3 plus the owner's delete-user fix; code refs are read live).
 *
 * An Expo / React Native app for campus events. Two kinds of account share one
 * binary: students (app/individual) find and join events, organisations
 * (app/org) create them and check people in. Everything talks straight to
 * Supabase from the phone; there is no server of the app's own in between.
 *
 * Every fact below was read out of the source. Where the repo cannot settle a
 * question — most often because the database schema and its row-level security
 * are NOT in this repository — the node says so and is marked `partial` or
 * `inferred` rather than filled in plausibly. Code at the leaves is quoted
 * verbatim at its real line, re-read at its offset before being pasted.
 *
 * Cut by THE LIFE OF ONE EVENT. Every user passes the same two steps first
 * (signing up, then being routed by account type on each launch); after that
 * the product is one object passing between two actors: an organisation
 * creates an event, a student finds it, joins it, and the organisation checks
 * them in. The cut by actor ("Student", "Organisation") was rejected: the
 * event and its `rsvp` column are shared by both sides, so that cut would put
 * the writer and the reader of the same string in two different boxes — the
 * "what belongs to what" confusion this tool exists to remove. The three roots
 * that are not steps — accounts, Supabase, server code — sit off the path.
 *
 * DEPTH. Each branch runs four or five levels:
 *
 *   root (what someone does)
 *     → its parts (authored children)
 *       → one part's mechanism (a row that carries `under`)
 *         → the data or decision it turns on (another `under`)
 *           → the source, quoted verbatim
 *
 * NOT QUOTED ON PURPOSE: lib/supabase.ts:5-7 holds the project URL and anon
 * key, and app/org/index/addEvent.tsx:415 holds a Google API key. The findings
 * name those lines; the keys themselves are not copied into this repo.
 */

import type { Anatomy, Edge, Link, Node, Run, Source, State } from "@/lib/data";
import { signup } from "./signup";
import { launch } from "./launch";
import { createEvent } from "./create-event";
import { feed } from "./feed";
import { rsvp } from "./rsvp";
import { checkIn } from "./check-in";
import { account } from "./account";
import { supabase } from "./supabase";
import { server } from "./server";
import { rowId } from "@/lib/data";

export type { State, Anatomy, Node, Edge, Link, Source };

export const RUN: Run = {
  command: "understand-slop map .",
  repo: "explorify",
  about:
    "Cut by the life of one event — an organisation creates it, a student finds and joins it, the organisation checks them in — after the two steps every account passes first.",
  commit: "304a512",
  files: 181,
  elapsed: "—",
};

/** The tree as authored. `lib/map.ts` adds a node per deep row. */
export const AUTHORED: Node[] = [signup, launch, createEvent, feed, rsvp, checkIn, account, supabase, server
];

/* The life of one event, in order. Five edges, one chain.

   Sign-up does not literally pass through launch routing — the wizard routes
   itself on success — but every launch after it does, so the order is real for
   any user who opens the app twice. `create-event → feed` is a data precedence:
   a student cannot find an event no organisation has published.

   `account`, `supabase` and `server` are not steps and get no edge. */
export const E0: Edge[] = [
  { from: "signup", to: "launch", state: "derived", label: "every later open goes through", order: 1 },
  // app/_layout.tsx sends an id found in `individual` to app/individual and
  // one found in `organizations` to app/org: two apps from here on.
  { from: "launch", to: "feed", state: "derived", label: "routes students to", order: 2, lane: "Students" },
  { from: "feed", to: "rsvp", state: "derived", label: "opens", order: 3, lane: "Students" },
  { from: "launch", to: "create-event", state: "derived", label: "routes organisations to", order: 2, lane: "Organisations" },
  // ongoing.tsx → eventdetails.tsx:200 → attendees.tsx
  { from: "create-event", to: "check-in", state: "derived", label: "lists the event, whose details open", order: 3, lane: "Organisations" },
  // Where the two apps meet: one writes a row the other reads.
  { from: "create-event", to: "feed", state: "derived", label: "publishes into" },
  { from: "rsvp", to: "check-in", state: "derived", label: "fills the list for" },
];

/* ── row-level links ──────────────────────────────────────────
   A value written in one place and read in another. Row keys follow
   components/anatomy.tsx: `map` anchors on the row's `from`, `flow` on the
   step number, `facts` on the label, `source` on "source". */

export const LINKS: Link[] = [
  // Joining writes the string that the feed then caches on every phone.
  { from: rowId("rv-column", "events.rsvp"), to: rowId("fd-fetch", 3), state: "partial", alarm: true, label: "cached by every student" },
  // Check-in rewrites the same string from a stale copy.
  { from: rowId("ci-tap", 3), to: rowId("rv-column", "events.rsvp"), state: "partial", alarm: true, label: "overwrites" },
  // The student's delete button and the function it calls.
  { from: rowId("ac-delete", "student"), to: rowId("sv-delete", 2), state: "derived", label: "calls, with the caller's sign-in token" },
  // Sign-up's final insert creates the row the launch lookup asks for.
  { from: rowId("su-finish", 2), to: rowId("ln-lookup", 2), state: "derived", label: "creates the row found by" },
];

export function linksFor(id: string) {
  return LINKS.filter((l) => l.from === id || l.to === id);
}

ui/lib/map.ts:
/**
 * The map on screen, whichever repository it describes.
 *
 * A map file states facts — `RUN`, the authored tree, the root chain `E0`, and
 * row-to-row `LINKS` — as `maps/<name>/map.json`, hand-exported or generated.
 * Everything derived from those lives here, so a second repository is a second
 * file, not a copy of the tree plumbing.
 */

import type { Anatomy, Edge, Link, Node, Run } from "@/lib/data";
import { rowId } from "@/lib/data";

export interface MapFile {
  RUN: Run;
  AUTHORED: Node[];
  E0: Edge[];
  LINKS: Link[];
}

/* ── rows that go deeper ──────────────────────────────────────
   A row carrying `under` becomes a REAL child node, spliced in beside whatever
   children its owner already had. See the note in lib/data.ts: the synthesized
   id is rowId(owner, key), the same id the row's anchor registers under, so the
   row and the card it opens share an identity and connect without a special
   case in the wire layer. */

/** The rows of one anatomy block that carry `under`, as {key, label, blocks}. */
function deepRows(blocks: Anatomy[]) {
  const out: { key: string; label: string; sub?: string; detail?: string; under: Anatomy[] }[] = [];
  for (const b of blocks) {
    if (b.kind === "map") {
      for (const r of b.rows) {
        // `to` is carried so the node can state the rule itself. On the engine
        // cards `from → to` IS the formula, and a card titled "dividendsTax"
        // whose subtitle only named its parent would hide the one line the
        // reader opened it for.
        if (r.under) out.push({ key: r.from, label: r.from, sub: r.to, under: r.under });
      }
    } else if (b.kind === "flow") {
      for (const r of b.rows) {
        // `detail` rides along. The card no longer renders a step's paragraph
        // when that step has somewhere to go (D24) — so if it does not land on
        // the child it lands nowhere, which is content present in the file and
        // invisible in the UI. That is the exact failure this tool exists to
        // find, and it stayed green through tsc and lint.
        if (r.under) out.push({ key: String(r.n), label: r.title, detail: r.detail, under: r.under });
      }
    }
  }
  return out;
}

/**
 * Walk the tree and give every `under`-carrying row a child node.
 *
 * Runs once at module load over the authored tree, so `nodeAt`, `levelAt`,
 * `allNodes` and the canvas all see one uniform structure and none of them
 * needs to know a row was involved.
 */
function withRowChildren(nodes: Node[]): Node[] {
  return nodes.map((n) => {
    const authored = n.children ? withRowChildren(n.children) : [];
    // ⚠ The synthesized children are fed back through this function, NOT just
    // constructed and returned.
    //
    // A row's `under` is itself an Anatomy[], so it can hold rows that carry
    // their own `under` — which is the only way a branch reaches past three
    // levels. Building these nodes without recursing set `anatomy` correctly
    // and then never looked at it again, so the second `under` stayed data and
    // never became a node: every root measured exactly 3 levels deep however
    // deeply it was authored. The content was present in the file and
    // unreachable in the UI, which is the failure that looks most like "the
    // fixture is shallow" while being nothing of the kind.
    const fromRows = n.anatomy
      ? withRowChildren(
          deepRows(n.anatomy).map((r, i): Node => ({
            id: rowId(n.id, r.key),
            title: r.label,
            // Not authored per row: 93 of these exist. A map row already
            // states the rule on its `to` side, so that becomes the subtitle —
            // on the engine cards it is literally the formula. Everything else
            // falls back to naming the card it opened out of, which is the
            // "what belongs to what" question. The generic "what happens to
            // it" it replaces said nothing on all 93.
            sub: r.sub ?? `Inside ${n.title}`,
            detail: r.detail,
            state: "derived",
            col: 0,
            row: authored.length + i,
            anatomy: r.under,
            evidence: n.evidence,
            fromRow: true,
          })),
        )
      : [];
    const children = [...authored, ...fromRows];
    return children.length ? { ...n, children } : { ...n, children: undefined };
  });
}

const byOrder = (a: Edge, b: Edge) => (a.order ?? 0) - (b.order ?? 0);

/** Everything the screen reads, derived once from one map file. */
export function buildMap(file: MapFile, name: string) {
  const { RUN, E0, LINKS } = file;
  /**
   * The tree everything else reads: authored nodes, plus one node for every
   * row that carries `under`. Built once, so no consumer knows a row was
   * involved.
   */
  const L0: Node[] = withRowChildren(file.AUTHORED);

  /** Resolve a path of ids to the node it names. */
  function nodeAt(path: string[]): Node | null {
    let level: Node[] = L0;
    let found: Node | null = null;
    for (const id of path) {
      found = level.find((n) => n.id === id) ?? null;
      if (!found) return null;
      level = found.children ?? [];
    }
    return found;
  }

  /** The nodes shown at a given path's level — roots when the path is empty. */
  function levelAt(path: string[]): Node[] {
    if (path.length === 0) return L0;
    return nodeAt(path)?.children ?? [];
  }

  /**
   * The path everyone walks, in the order E0 chains it: the ordered edges with
   * no lane. Walking them from the first `from` IS the sequence.
   */
  const SPINE = (() => {
    const sorted = E0.filter((e) => e.order !== undefined && !e.lane).sort(byOrder);
    return sorted.length ? [sorted[0].from, ...sorted.map((e) => e.to)] : [];
  })();

  /** Where the path splits, one ordered branch per lane. Empty if it never does. */
  const LANES = [...new Set(E0.flatMap((e) => (e.lane ? [e.lane] : [])))].map((lane) => {
    const sorted = E0.filter((e) => e.lane === lane).sort(byOrder);
    return { name: lane, from: sorted[0].from, ids: sorted.map((e) => e.to) };
  });

  /** Edges with no order: one branch handing something to another. */
  const HANDOFFS = E0.filter((e) => e.order === undefined);

  const ON_PATH = new Set([...SPINE, ...LANES.flatMap((l) => l.ids)]);

  function roots(ids: string[]) {
    return ids.map((id) => L0.find((n) => n.id === id)).filter((n): n is Node => n !== undefined);
  }

  /** 1-indexed position on the path, counting the shared steps into a lane. */
  function stepOf(id: string): { n: number; of: number; lane?: string } | undefined {
    const i = SPINE.indexOf(id);
    if (i !== -1) return { n: i + 1, of: SPINE.length };
    for (const l of LANES) {
      const j = l.ids.indexOf(id);
      if (j !== -1) return { n: SPINE.length + j + 1, of: SPINE.length + l.ids.length, lane: l.name };
    }
  }

  return { name, RUN, E0, LINKS, L0, nodeAt, levelAt, SPINE, LANES, HANDOFFS, ON_PATH, roots, stepOf };
}

export type BuiltMap = ReturnType<typeof buildMap>;

/** Every node in the tree, flattened. Used for id lookups and audits. */
export function allNodes(nodes: Node[]): Node[] {
  return nodes.flatMap((n) => [n, ...allNodes(n.children ?? [])]);
}

ui/lib/maps.ts:
/**
 * Server-side: the map files under `ui/maps/<name>/map.json`, and the repo
 * each one reads its code from.
 */

import { execFileSync } from "node:child_process";
import { existsSync, readdirSync, readFileSync } from "node:fs";
import { homedir } from "node:os";
import { join, resolve } from "node:path";
import type { Run } from "@/lib/data";
import type { MapFile } from "@/lib/map";

const MAPS = join(process.cwd(), "maps");
export const DEFAULT_MAP = "explorify";

export function listMaps(): string[] {
  return readdirSync(MAPS).filter((d) => existsSync(join(MAPS, d, "map.json"))).sort();
}

/** `name` arrives from the URL, so only a listed map is ever read. */
export function loadMap(name: string | undefined): { name: string; file: MapFile } {
  const pick = name && listMaps().includes(name) ? name : DEFAULT_MAP;
  return { name: pick, file: JSON.parse(readFileSync(join(MAPS, pick, "map.json"), "utf8")) };
}

/**
 * Where a map's code lives. A generated map records its absolute root; a
 * hand-authored one names a directory under ~/Desktop/Code, so a literal
 * `/Users/<name>/…` is never baked into a fixture.
 */
export function rootOf(run: Run): string {
  return run.root ?? process.env.SLOP_REPO_ROOT ?? resolve(homedir(), "Desktop/Code", run.repo);
}

/** The checkout's `origin` as a web address (`git@host:o/r.git` → `https://host/o/r`), if it has one. */
export function remoteOf(run: Run): string | undefined {
  try {
    const url = execFileSync("git", ["-C", rootOf(run), "remote", "get-url", "origin"], { encoding: "utf8", stdio: ["ignore", "pipe", "ignore"] }).trim();
    return url.replace(/^git@([^:]+):/, "https://$1/").replace(/\.git$/, "").replace(/^https:\/\/[^@/]+@/, "https://") || undefined;
  } catch {
    return undefined;
  }
}

ui/lib/repo.ts:
/**
 * Binding the map to a real repository. Frozen contract for this round.
 *
 * Until now every `source` block was text pasted into `lib/taxbuddy.ts` by
 * hand. That text was verified once, at authoring time, and drifts silently
 * the moment the real file changes — which is exactly the failure this project
 * exists to study. These functions read the file instead.
 *
 * `~/Desktop/Code/taxBuddy` is a live git checkout; every spot-checked
 * file:line in the fixture resolved to the right line, so the anchors are
 * trustworthy enough to read against.
 */

/**
 * Where the mapped repository lives: absolute, one per map, resolved by
 * `rootOf` in `lib/maps.ts` from the map the reader has open. The route hands
 * it in; nothing caller-supplied ever chooses it.
 */
export type RepoRoot = string;

export interface SliceRequest {
  /** Repo-relative path. Must stay inside the repo root once resolved. */
  file: string;
  /** 1-indexed first line. */
  start: number;
  /** 1-indexed last line, inclusive. */
  end: number;
}

export interface Slice extends SliceRequest {
  /** Verbatim lines, newline-joined. Indentation preserved exactly. */
  code: string;
  /** Total lines in the file, so the UI can say "733 of 1,204". */
  total: number;
  /**
   * True when the file on disk still matches what the fixture quoted.
   * A false here is a FINDING, not an error: it means the map has drifted from
   * the code, and the UI must say so rather than quietly showing fresh text
   * under a stale explanation.
   */
  matchesFixture: boolean;
}

/**
 * Read a slice of a real file.
 *
 * Path safety: resolve the path and confirm it is still under the repo root.
 * `../` traversal, absolute paths and symlinks pointing outside are refused —
 * this endpoint reads arbitrary caller-supplied paths, so the containment check
 * is the whole security model.
 */
export type ReadSlice = (req: SliceRequest, fixture: string | undefined, root: RepoRoot) => Promise<Slice>;

/**
 * Write an edited slice back.
 *
 * Deliberately narrow, because this is the one operation in the product that
 * can destroy work:
 *
 * - Inside the repo root only, same containment check as the read.
 * - One contiguous slice of one file per call.
 * - `expected` must match what is currently on disk, or the write is refused.
 *   This is optimistic concurrency: it stops a save built on a stale read from
 *   overwriting a change made in the editor since.
 * - The caller is shown a diff and confirms before this is ever invoked.
 *
 * The UI never writes on blur, on a timer, or on navigation. Only on an
 * explicit save.
 */
export interface WriteRequest extends SliceRequest {
  /** The replacement text for [start, end]. */
  code: string;
  /** What the caller believes is currently at [start, end]. Verified first. */
  expected: string;
}

export interface WriteResult {
  ok: boolean;
  /** Unified diff of what changed, for display after the fact. */
  diff: string;
  /** Set when refused: "outside repo", "stale", "not a file". */
  refused?: string;
}

export type WriteSlice = (req: WriteRequest, root: RepoRoot) => Promise<WriteResult>;

// ---------------------------------------------------------------------------
// Implementation. The types above are the frozen contract; everything below
// satisfies it and adds nothing to it.
// ---------------------------------------------------------------------------

import { readFile, writeFile, realpath, stat } from "node:fs/promises";
import { resolve, sep } from "node:path";

/**
 * The entire security model, in one function.
 *
 * `file` arrives from the network, so it is assumed hostile. Three things are
 * checked, in this order, because each one defeats a different attack:
 *
 * 1. `resolve(the repo root, file)` collapses `../` textually — this is what stops
 *    `../../../etc/passwd` and, because `resolve` discards the base when given
 *    an absolute second argument, it also folds absolute paths back through the
 *    same prefix test rather than silently honouring them.
 * 2. The prefix test uses `root + sep`, not bare `startsWith(root)`. Without the
 *    separator `/Users/.../taxBuddy-secrets` passes as if it were inside
 *    `/Users/.../taxBuddy`.
 * 3. `realpath` resolves symlinks and the prefix test runs AGAIN on the result.
 *    Step 1 is pure string arithmetic and cannot see a link inside the repo
 *    pointing out of it; only asking the filesystem can.
 *
 * Returns the real absolute path, or null when the path escapes.
 */
async function contain(repoRoot: RepoRoot, file: string): Promise<string | null> {
  const root = await realpath(repoRoot);
  const inside = (p: string) => p === root || p.startsWith(root + sep);

  const target = resolve(root, file);
  if (!inside(target)) return null;

  // realpath throws ENOENT on a path that does not exist, which is a refusal
  // here rather than an error: there is nothing to read and nothing to write.
  let real: string;
  try {
    real = await realpath(target);
  } catch {
    return null;
  }
  return inside(real) ? real : null;
}

/** Thrown to the route handler, which turns it into a 400 with this message. */
export class Refused extends Error {}

/**
 * `fixture` is what the MAP claims sits at these lines, which the repository
 * itself has no opinion about; undefined when the caller made no claim.
 */
export const readSlice = async (
  req: SliceRequest,
  fixture: string | undefined,
  root: RepoRoot,
): Promise<Slice> => {
  const real = await contain(root, req.file);
  if (!real) throw new Refused("outside repo");
  if (!(await stat(real)).isFile()) throw new Refused("not a file");

  const lines = (await readFile(real, "utf8")).split("\n");
  const start = Math.max(1, req.start);
  const end = Math.min(lines.length, Math.max(start, req.end));
  const code = lines.slice(start - 1, end).join("\n");

  return {
    file: req.file,
    start,
    end,
    code,
    total: lines.length,
    // No fixture to compare against is not a mismatch — a caller that asked
    // only for the file's text has made no claim that could have drifted.
    matchesFixture: fixture === undefined || quoteHolds(fixture, code),
  };
};

/** Conformance to the frozen contract, checked by the compiler. */
const _readSliceConforms: ReadSlice = readSlice;
void _readSliceConforms;

/**
 * Does the fixture's quote still hold against what is on disk?
 *
 * Exact equality is the normal answer. The one accepted relaxation is a quote
 * whose LAST line stops part-way through the real line — the fixture quotes
 * prose out of JSX that way, taking a sentence and leaving the rest of the
 * line. Every other line must match byte for byte, including indentation.
 *
 * Everything else is drift, and drift is a finding: the explanation attached to
 * this quote was written about text that is no longer there.
 */
function quoteHolds(fixture: string, disk: string): boolean {
  if (fixture === disk) return true;
  const f = fixture.replace(/\n$/, "").split("\n");
  const d = disk.replace(/\n$/, "").split("\n");
  if (f.length !== d.length) return false;
  const last = f.length - 1;
  return (
    f.slice(0, last).every((line, i) => line === d[i]) &&
    d[last].startsWith(f[last])
  );
}

export const writeSlice: WriteSlice = async (req, root) => {
  const real = await contain(root, req.file);
  if (!real) return { ok: false, diff: "", refused: "outside repo" };
  if (!(await stat(real)).isFile()) {
    return { ok: false, diff: "", refused: "not a file" };
  }

  const lines = (await readFile(real, "utf8")).split("\n");
  if (req.start < 1 || req.end > lines.length || req.end < req.start) {
    return { ok: false, diff: "", refused: "stale" };
  }

  // Optimistic concurrency. The caller read [start, end] at some point and is
  // now writing back a change to it; if disk no longer holds what they read,
  // their edit was composed against text that has since been replaced and
  // applying it would silently destroy whoever made that replacement.
  const onDisk = lines.slice(req.start - 1, req.end).join("\n");
  if (onDisk !== req.expected) {
    return { ok: false, diff: "", refused: "stale" };
  }

  const replacement = req.code.replace(/\n$/, "").split("\n");
  const next = [
    ...lines.slice(0, req.start - 1),
    ...replacement,
    ...lines.slice(req.end),
  ];
  await writeFile(real, next.join("\n"), "utf8");

  return { ok: true, diff: unified(req.file, req.start, onDisk, req.code) };
};

/**
 * A unified diff of just the replaced slice.
 *
 * Whole-line add/remove, no LCS: the slice is small, contiguous and already
 * known to be the only thing that changed, so the alignment a real diff
 * algorithm buys is alignment nobody would read. A dependency for this would
 * be a dependency for cosmetics.
 */
function unified(file: string, start: number, before: string, after: string) {
  const b = before.replace(/\n$/, "").split("\n");
  const a = after.replace(/\n$/, "").split("\n");
  return [
    `--- a/${file}`,
    `+++ b/${file}`,
    `@@ -${start},${b.length} +${start},${a.length} @@`,
    ...b.map((l) => `-${l}`),
    ...a.map((l) => `+${l}`),
  ].join("\n");
}

ui/lib/source.ts:
/**
 * Client-side: where the drawer reads code from.
 *
 * Served by `next dev`, that is `/api/source` over the real checkout. A static
 * export (scripts/export-static.mts) has no server, so it reads the files the
 * map cites, baked into `source.json` beside the page at build time.
 */

import type { Slice } from "@/lib/repo";

/** Set only in a static export: the one map it serves. */
export const STATIC_MAP = process.env.NEXT_PUBLIC_STATIC_MAP;
/** In a static export, the code host page a ref links to: `<base>/<file>#L<start>-L<end>`. */
export const SOURCE_URL = process.env.NEXT_PUBLIC_SOURCE_URL;

let baked: Promise<Record<string, string>> | undefined;

export async function readSource(
  q: { map: string; file: string; start: number; end: number; fixture?: string },
  signal?: AbortSignal,
): Promise<{ slice: Slice } | { refused: string }> {
  if (!STATIC_MAP) {
    const params = new URLSearchParams({ map: q.map, file: q.file, start: String(q.start), end: String(q.end) });
    if (q.fixture !== undefined) params.set("fixture", q.fixture);
    const res = await fetch(`/api/source?${params}`, { signal });
    const body = await res.json();
    return res.ok ? { slice: body as Slice } : { refused: (body.refused as string) ?? "unreadable" };
  }
  baked ??= fetch(`${process.env.NEXT_PUBLIC_BASE_PATH ?? ""}/source.json`).then((r) => r.json());
  const text = (await baked)[q.file];
  if (text === undefined) return { refused: "not in this export" };
  const lines = text.split("\n");
  const code = lines.slice(q.start - 1, q.end).join("\n");
  return {
    slice: { file: q.file, start: q.start, end: q.end, code, total: lines.length, matchesFixture: q.fixture === undefined || code === q.fixture },
  };
}

ui/scripts/generate/author.ts:
/**
 * Stage 3 — one agent per root writes that root's whole subtree.
 *
 * It reads the code itself (numbered lines, grep, directory listings) and
 * hands in the finished node through `submit`, which runs the same checks the
 * map is held to. Problems come back as the tool's answer, so the repair loop
 * is the conversation itself: the model fixes what the checker names, with
 * the code still in front of it.
 */
/* eslint-disable @typescript-eslint/no-explicit-any -- model tool inputs */
import { execFileSync } from "node:child_process";
import { readFileSync } from "node:fs";
import type { Node } from "@/lib/data";
import { BACKEND, invoke, callsOf, type Block, type Message, type Tool } from "./bedrock";
import { ccAgent, type Handled } from "./claude-code";
import { check } from "./check";
import type { Cut, Root } from "./cut";
import { owners } from "./cut";
import { numbered, type Inventory } from "./inventory";
import { shapeProblems, typeReference } from "./schema";
import { full, oneLine, type FileSummary } from "./summarize";

export interface Authored {
  root: Node | null;
  turns: number;
  reads: number;
  submits: number;
  /** The checker's last word when the root never came back clean. */
  problems: string[];
}

export const TOOLS: Tool[] = [
  {
    name: "read_file",
    description: "Read a file from the repository with line numbers. At most 400 lines per call; read the ranges you need.",
    input_schema: { type: "object", required: ["path"], properties: { path: { type: "string" }, start: { type: "integer" }, end: { type: "integer" } } },
  },
  {
    name: "grep",
    description: "Search the repository (git grep -E, case-sensitive). Returns up to 60 matching lines as path:line:text.",
    input_schema: { type: "object", required: ["pattern"], properties: { pattern: { type: "string" }, under: { type: "string", description: "Optional directory or file to search within." } } },
  },
  {
    name: "list",
    description: "List the files under a directory with their line counts.",
    input_schema: { type: "object", required: ["dir"], properties: { dir: { type: "string" } } },
  },
  {
    name: "submit",
    description: "Hand in the complete root node, with every descendant. It is checked; if anything fails you get the list back and must submit again with everything fixed.",
    input_schema: { type: "object", required: ["root"], properties: { root: { type: "object", description: "A Node (see the types): the root and its whole subtree." } } },
  },
];

/** The explorify root used as the worked example, minus what generated maps may not use. */
function exemplar(): string {
  const map = JSON.parse(readFileSync("maps/explorify/map.json", "utf8"));
  const root = structuredClone(map.AUTHORED.find((r: any) => r.id === "check-in"));
  const strip = (n: any) => {
    if (n.shape?.kind === "figure") delete n.shape;
    for (const b of n.anatomy ?? []) if (b.kind === "screen") delete b.shot;
    (n.children ?? []).forEach(strip);
  };
  strip(root);
  return JSON.stringify(root, null, 1);
}

let systemCache: Block[] | null = null;
function system(): Block[] {
  systemCache ??= [
    { type: "text", text: readFileSync("scripts/generate/prompts/rules.md", "utf8") },
    {
      type: "text",
      text: `# The types (lib/data.ts) — every field's comment is part of the standard\n\n${typeReference()}\n\n# A worked example: one root of a hand-authored map, at the standard to match\n\nIt was written before diagram arrows carried \`at\`; yours must. It is from a different repository — match its depth, density and honesty, not its content.\n\n${exemplar()}`,
      cache_control: { type: "ephemeral" },
    },
  ];
  return systemCache;
}

function brief(root: Root, cut: Cut, inv: Inventory, sums: Record<string, FileSummary>): string {
  const mine = inv.files.filter((f) => f.code && !f.test && owners(cut, f.path).includes(root.id));
  const mineSet = new Set(mine.map((f) => f.path));
  // Files just across the boundary: what this root imports, and what imports it.
  const near = new Set<string>();
  for (const [from, tos] of Object.entries(inv.imports))
    for (const to of tos) {
      if (mineSet.has(from) && !mineSet.has(to)) near.add(to);
      if (mineSet.has(to) && !mineSet.has(from)) near.add(from);
    }
  return [
    `# Repository: ${inv.name} @ ${inv.commit}`,
    `## README (excerpt)\n${inv.readme.slice(0, 2500) || "(none)"}`,
    ...(inv.scope ? [`## Scope\nThis map covers only part of the repository. Its reader: ${inv.scope.focus} Files outside it can still be read and cited.`] : []),
    `## The whole map's top level — ${cut.about}\n${cut.roots.map((r) => `- ${r.id}: ${r.title} — ${r.sub}`).join("\n")}`,
    `## Your root\nid: ${root.id}\ntitle: ${root.title}\nsub: ${root.sub}\nscope: ${root.why}\nEvery node id under it starts with "${root.prefix}-".`,
    `Brand marks you may use: ${inv.marks.length ? inv.marks.join(", ") : "none"}.`,
    `## Files this root owns (${mine.length}), with what each does\n${mine.map((f) => (sums[f.path] ? full(sums[f.path]) : `${f.path} (${f.lines} lines)`)).join("\n")}`,
    near.size ? `## Files just outside it that it talks to\n${[...near].sort().slice(0, 60).map((p) => (sums[p] ? oneLine(sums[p]) : p)).join("\n")}` : "",
    `## Task
Read the code you need — use the symbol line ranges above to read targeted ranges, not whole files — then submit this root with its full subtree.
Aim for 2-3 levels, 3-6 children per node, a diagram on most levels whose boxes open the children they show, and real issues where the code has them.
Budget: about 25 tool calls before you submit.`,
  ].filter(Boolean).join("\n\n");
}

export function runTool(call: { name: string; input: any }, inv: Inventory, known: Set<string>): string {
  const i = call.input ?? {};
  if (call.name === "read_file") {
    const path = String(i.path ?? "").replace(/^\.?\//, "");
    if (!known.has(path)) return `No such file in the repository listing: ${path}`;
    const start = Math.max(1, Number(i.start) || 1);
    const end = Math.min(start + 399, Number(i.end) || start + 399);
    const total = inv.files.find((f) => f.path === path)!.lines;
    return `${path} (lines ${start}-${Math.min(end, total)} of ${total})\n${numbered(inv.repo, path, start, end)}`;
  }
  if (call.name === "grep") {
    const args = ["-C", inv.repo, "grep", "-n", "-I", "-E", String(i.pattern ?? "")];
    if (i.under) args.push("--", String(i.under).replace(/^\.?\//, ""));
    try {
      const hits = execFileSync("git", args, { encoding: "utf8", maxBuffer: 16 << 20, stdio: ["ignore", "pipe", "pipe"] }).split("\n").filter(Boolean);
      return hits.slice(0, 60).map((h) => h.slice(0, 220)).join("\n") + (hits.length > 60 ? `\n… ${hits.length - 60} more` : "");
    } catch (e: any) {
      return e.status === 1 ? "No matches." : `grep failed: ${String(e.stderr ?? e.message).slice(0, 200)}`;
    }
  }
  if (call.name === "list") {
    const dir = String(i.dir ?? "").replace(/^\.?\//, "").replace(/\/?$/, "/");
    const hits = inv.files.filter((f) => dir === "/" || f.path.startsWith(dir));
    return hits.slice(0, 200).map((f) => `${f.path} (${f.lines})`).join("\n") + (hits.length > 200 ? `\n… ${hits.length - 200} more` : "") || "Nothing there.";
  }
  return `Unknown tool ${call.name}`;
}

/** The last block of the last message carries the cache mark, so each turn re-reads the conversation from cache. */
function withCacheMark(messages: Message[]): Message[] {
  const out = messages.map((m) => ({ ...m, content: typeof m.content === "string" ? [{ type: "text", text: m.content } as Block] : m.content.map((b) => ({ ...b })) }));
  const last = out[out.length - 1].content as any[];
  last[last.length - 1].cache_control = { type: "ephemeral" };
  return out;
}

export async function authorRoot(
  root: Root,
  cut: Cut,
  inv: Inventory,
  sums: Record<string, FileSummary>,
  model: string,
  log: (s: string) => void,
): Promise<Authored> {
  const known = new Set(inv.files.map((f) => f.path));
  const res: Authored = { root: null, turns: 0, reads: 0, submits: 0, problems: [] };
  const MAX_TURNS = 45;

  /** One tool call, answered the same way whichever backend made it. */
  const handle = (name: string, input: any): Handled => {
    if (name !== "submit") {
      res.reads++;
      return { content: runTool({ name, input }, inv, known) };
    }
    res.submits++;
    const node = input?.root;
    if (node && typeof node === "object" && node.id !== root.id) node.id = root.id;
    const problems = shapeProblems(node, root.prefix);
    if (!problems.length) problems.push(...check({ AUTHORED: [node], E0: [], LINKS: [] }, inv.repo, { generated: true }).problems);
    res.problems = problems;
    log(`${root.id}: submit ${res.submits} — ${problems.length ? `${problems.length} problems` : "clean"}`);
    if (!problems.length) return { content: "Accepted. This root is done; stop now.", done: { node, reads: res.reads, submits: res.submits } };
    return { content: `Not accepted. Fix every one of these and submit the whole root again:\n- ${problems.slice(0, 80).join("\n- ")}`, isError: true };
  };

  if (BACKEND === "claude-code") {
    const r = await ccAgent<{ node: Node; reads: number; submits: number }>({
      model, system: system(), prompt: brief(root, cut, inv, sums), tools: TOOLS, handle, effort: "high", stage: "author",
      maxTurns: MAX_TURNS, nudge: "Continue: use the tools, and finish by calling submit.",
    });
    // A replayed run calls no tools, so its counts come from the cache.
    return { ...res, root: r.value?.node ?? null, turns: r.turns, reads: r.value?.reads ?? res.reads, submits: r.value?.submits ?? res.submits };
  }

  const messages: Message[] = [{ role: "user", content: brief(root, cut, inv, sums) }];
  for (; res.turns < MAX_TURNS; res.turns++) {
    const r = await invoke({ model, stage: "author", effort: "high", maxTokens: 64000, system: system(), messages: withCacheMark(messages), tools: TOOLS });
    messages.push({ role: "assistant", content: r.content });
    const calls = callsOf(r);
    if (!calls.length) {
      messages.push({ role: "user", content: r.stop_reason === "max_tokens" ? "Your reply was cut off at the token limit. Submit again; keep labels short." : "Continue: use the tools, and finish by calling submit." });
      continue;
    }
    const results: Block[] = [];
    for (const c of calls) {
      const h = handle(c.name, c.input);
      if (h.done) {
        res.root = (h.done as { node: Node }).node;
        return res;
      }
      // Key order as before, so the requests of maps already made still replay from cache.
      results.push(h.isError ? { type: "tool_result", tool_use_id: c.id, is_error: true, content: h.content } : { type: "tool_result", tool_use_id: c.id, content: h.content });
    }
    if (res.turns === MAX_TURNS - 6) results.push({ type: "text", text: "You are almost out of turns. Submit the complete root now." });
    messages.push({ role: "user", content: results });
  }
  return res;
}

ui/scripts/generate/bedrock.ts:
/**
 * One door to Claude on Bedrock, shaped after VisuLearn's src/lib/bedrock.ts:
 * InvokeModel with the native Anthropic body, default credential chain,
 * AWS_REGION. Adds what a batch pipeline needs and a chat app does not —
 * tools, a global concurrency cap, backoff on throttling, a disk cache, and
 * a running bill.
 *
 * The cache is the reproducibility story. Temperature 0 narrows a fresh sample
 * but does not pin it (and thinking calls cannot use it); the same request
 * served from disk is pinned. A re-run with no code changes is therefore
 * identical, and `--fresh` measures how far a new sample drifts.
 */

import { BedrockRuntimeClient, InvokeModelWithResponseStreamCommand } from "@aws-sdk/client-bedrock-runtime";
import { createHash } from "node:crypto";
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

/**
 * What this AWS account can invoke (probed 2026-10-22). The 5.x profiles are
 * listed in us-east-1 but every one answers AccessDeniedException.
 */
export const MODELS = {
  haiku: "global.anthropic.claude-haiku-4-5-20251001-v1:0",
  sonnet: "global.anthropic.claude-sonnet-4-6",
  opus: "global.anthropic.claude-opus-4-6-v1",
} as const;

/** The model without its routing prefix: `us.` and `global.` run the same model on the same request. */
const bare = (model: string) => model.replace(/^(us|eu|apac|global)\./, "");

/**
 * $ per million tokens through a `global.` profile, which Bedrock prices at
 * the list price; a geographic one (`us.`) costs about 10% more on input and
 * output. Times the tokens Bedrock reports, this is the bill to within its
 * rounding — Cost Explorer shows the same charge a day later, per service.
 */
const PRICE: Record<string, { in: number; out: number; cacheRead: number }> = {
  [bare(MODELS.haiku)]: { in: 1, out: 5, cacheRead: 0.1 },
  [bare(MODELS.sonnet)]: { in: 3, out: 15, cacheRead: 0.3 },
  [bare(MODELS.opus)]: { in: 5, out: 25, cacheRead: 0.5 },
};
const priceOf = (model: string) => {
  const p = PRICE[bare(model)];
  const k = model.startsWith("global.") ? 1 : 1.1;
  return { in: p.in * k, out: p.out * k, cacheRead: p.cacheRead * k };
};

const client = new BedrockRuntimeClient({ region: process.env.AWS_REGION || "us-east-1" });

export interface Tool {
  name: string;
  description: string;
  input_schema: object;
  strict?: boolean;
}

export type Block =
  | { type: "text"; text: string; cache_control?: { type: "ephemeral" } }
  | { type: "tool_use"; id: string; name: string; input: unknown }
  | { type: "tool_result"; tool_use_id: string; content: string; is_error?: boolean }
  | { type: "thinking"; [k: string]: unknown };

export interface Message {
  role: "user" | "assistant";
  content: string | Block[];
}

export interface Reply {
  content: Block[];
  stop_reason: string;
  usage: { input_tokens: number; output_tokens: number; cache_read_input_tokens?: number; cache_creation_input_tokens?: number };
}

export interface Request {
  model: string;
  system: string | Block[];
  messages: Message[];
  tools?: Tool[];
  maxTokens?: number;
  /** Turns on adaptive thinking at this effort (Sonnet/Opus only). Absent: temperature 0, no thinking. */
  effort?: "low" | "medium" | "high" | "max";
  /** Tags the bill, e.g. "summarize". */
  stage: string;
}

/* ── the bill ───────────────────────────────────────────────── */

/** `usd` is spent this run; `fullUsd` and the token counts are the whole work, replayed calls included, so a replayed map still reports its size and price. */
export const bill: Record<string, { calls: number; cached: number; input: number; output: number; cacheRead: number; usd: number; fullUsd: number }> = {};

const charge = (stage: string, model: string, r: Reply, fromCache: boolean) => chargeUsage(stage, model, r.usage, fromCache);

/** Bills one call's tokens at the API list price, whichever backend made it, so the two compare. */
export function chargeUsage(stage: string, model: string, u: Reply["usage"], fromCache: boolean) {
  const b = (bill[stage] ??= { calls: 0, cached: 0, input: 0, output: 0, cacheRead: 0, usd: 0, fullUsd: 0 });
  b.calls++;
  const p = priceOf(model);
  const write = u.cache_creation_input_tokens ?? 0;
  const read = u.cache_read_input_tokens ?? 0;
  const usd = (u.input_tokens * p.in + write * p.in * 1.25 + read * p.cacheRead + u.output_tokens * p.out) / 1e6;
  b.fullUsd += usd;
  // Tokens are the work the map takes, so a replayed call counts too.
  b.input += u.input_tokens + write;
  b.output += u.output_tokens;
  b.cacheRead += read;
  if (fromCache) { b.cached++; return; }
  b.usd += usd;
}

/* ── cache, concurrency, backoff ────────────────────────────── */

let cacheDir: string | null = null;
let fresh = false;
export function cacheIn(dir: string, opts: { fresh?: boolean } = {}) {
  cacheDir = dir;
  fresh = Boolean(opts.fresh);
  mkdirSync(dir, { recursive: true });
}

/** Where a reply with this key is cached; `replay` false asks only where to write it (a --fresh run reads nothing). */
export function cacheFile(key: string, replay = true): string | null {
  return cacheDir && !(replay && fresh) ? join(cacheDir, `${key}.json`) : null;
}

/** Which door the calls go through: an AWS account (default) or the reader's own Claude Code. */
export const BACKEND = process.env.SLOP_BACKEND === "claude-code" ? "claude-code" : "bedrock";

const LIMIT = Number(process.env.SLOP_CONCURRENCY ?? 8);
let running = 0;
const queue: (() => void)[] = [];
export async function slot<T>(fn: () => Promise<T>): Promise<T> {
  if (running >= LIMIT) await new Promise<void>((r) => queue.push(r));
  running++;
  try {
    return await fn();
  } finally {
    running--;
    queue.shift()?.();
  }
}

let coolUntil = 0;
/** Seconds of request time spent waiting out throttles, summed over calls — the account's quota, not the work. */
export const throttle = { waits: 0, seconds: 0 };
const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
const RETRYABLE = /Throttling|TooManyRequests|ServiceUnavailable|ModelNotReady|InternalServer|ModelError|timeout|ECONNRESET|socket hang up/i;

export async function invoke(req: Request): Promise<Reply> {
  const body = {
    anthropic_version: "bedrock-2023-05-31",
    max_tokens: req.maxTokens ?? 16000,
    system: req.system,
    messages: req.messages,
    ...(req.tools ? { tools: req.tools, tool_choice: { type: "auto" } } : {}),
    ...(req.effort ? { thinking: { type: "adaptive" }, output_config: { effort: req.effort } } : { temperature: 0 }),
  };
  const json = JSON.stringify(body);
  // Keyed on one spelling of the model whatever the routing — the `us.` one
  // the first maps were cached under — so a routing switch replays them.
  const key = createHash("sha256").update(`us.${bare(req.model)}\n${json}`).digest("hex");
  const file = cacheDir ? join(cacheDir, `${key}.json`) : null;
  if (file && !fresh && existsSync(file)) {
    const r = JSON.parse(readFileSync(file, "utf8")) as Reply;
    charge(req.stage, req.model, r, true);
    return r;
  }

  const r = await slot(async () => {
    for (let attempt = 0; ; attempt++) {
      try {
        if (coolUntil > Date.now()) await sleep(coolUntil - Date.now());
        // Streamed, as VisuLearn does: a long author turn left a plain
        // request waiting minutes with nothing on the wire, and it timed out.
        const res = await client.send(
          new InvokeModelWithResponseStreamCommand({ modelId: req.model, contentType: "application/json", accept: "application/json", body: json }),
        );
        return await assemble(res.body!);
      } catch (e) {
        const msg = `${(e as Error).name}: ${(e as Error).message}`;
        // A daily cap does not lift in minutes; retrying only burns them.
        if (/per day/i.test(msg)) throw new Error(`${req.stage} ${req.model}: daily token quota spent — ${msg}`);
        const throttled = /Throttling|TooManyRequests/i.test(msg);
        if (attempt >= (throttled ? 12 : 6) || !RETRYABLE.test(msg)) throw new Error(`${req.stage} ${req.model}: ${msg}`);
        const wait = Math.min(60_000, 2000 * 2 ** attempt) * (0.5 + Math.random());
        // A throttle is the account's quota, not this request: every call
        // waits it out, or the rest keep hitting the limit and burn retries.
        if (throttled) {
          coolUntil = Math.max(coolUntil, Date.now() + wait);
          throttle.waits++;
          throttle.seconds += wait / 1000;
        }
        await sleep(wait);
      }
    }
  });
  charge(req.stage, req.model, r, false);
  if (file) writeFileSync(file, JSON.stringify(r));
  return r;
}

type StreamEvent = { chunk?: { bytes?: Uint8Array } };

/** The whole reply from its stream events, shaped exactly as a plain call returns it. */
async function assemble(stream: AsyncIterable<StreamEvent>): Promise<Reply> {
  const reply: Reply = { content: [], stop_reason: "", usage: { input_tokens: 0, output_tokens: 0 } };
  const json: Record<number, string> = {};
  for await (const e of stream) {
    if (!e.chunk?.bytes) continue;
    /* eslint-disable-next-line @typescript-eslint/no-explicit-any -- Anthropic stream events */
    const ev: any = JSON.parse(new TextDecoder().decode(e.chunk.bytes));
    if (ev.type === "message_start") reply.usage = { ...ev.message.usage };
    else if (ev.type === "content_block_start") reply.content[ev.index] = { ...ev.content_block };
    else if (ev.type === "content_block_delta") {
      /* eslint-disable-next-line @typescript-eslint/no-explicit-any -- block being built */
      const b: any = reply.content[ev.index];
      const d = ev.delta;
      if (d.type === "text_delta") b.text = (b.text ?? "") + d.text;
      else if (d.type === "input_json_delta") json[ev.index] = (json[ev.index] ?? "") + d.partial_json;
      else if (d.type === "thinking_delta") b.thinking = (b.thinking ?? "") + d.thinking;
      else if (d.type === "signature_delta") b.signature = (b.signature ?? "") + d.signature;
    } else if (ev.type === "content_block_stop" && json[ev.index] !== undefined) {
      // A reply cut off at max_tokens can end mid-JSON; the callers already
      // treat a max_tokens stop as a turn to redo, so its input is just empty.
      let input: unknown = {};
      try { input = json[ev.index] ? JSON.parse(json[ev.index]) : {}; } catch { /* cut off */ }
      (reply.content[ev.index] as { input: unknown }).input = input;
    } else if (ev.type === "message_delta") {
      reply.stop_reason = ev.delta.stop_reason ?? reply.stop_reason;
      if (ev.usage?.output_tokens != null) reply.usage.output_tokens = ev.usage.output_tokens;
    }
  }
  return reply;
}

/** The text of a reply, thinking dropped. */
export const textOf = (r: Reply) => r.content.flatMap((b) => (b.type === "text" ? [b.text] : [])).join("");

/** Every tool call in a reply. */
export const callsOf = (r: Reply) =>
  r.content.flatMap((b) => (b.type === "tool_use" ? [b as Extract<Block, { type: "tool_use" }>] : []));

/**
 * One structured answer: the model is asked to call `tool` once and nothing
 * else. Forced tool_choice is a 400 on the 5.5 models, so this asks, checks,
 * and asks again with the reason when the call is missing.
 */
/**
 * What is wrong with a tool answer at the top level, or null. Models now and
 * then send an array as its JSON text (saas-starter's verify stage crashed on
 * one); that is unwrapped in place, anything else goes back as an error.
 */
function shapeOf(tool: Tool, input: Record<string, unknown>): string | null {
  const schema = tool.input_schema as { required?: string[]; properties?: Record<string, { type?: string }> };
  for (const k of schema.required ?? []) if (input?.[k] === undefined) return `Missing required field "${k}".`;
  for (const [k, p] of Object.entries(schema.properties ?? {})) {
    if (p.type !== "array" || input[k] === undefined) continue;
    if (typeof input[k] === "string") {
      try { input[k] = JSON.parse(input[k] as string); } catch { /* reported below */ }
    }
    if (!Array.isArray(input[k])) return `Field "${k}" must be an array, not ${typeof input[k]}.`;
  }
  return null;
}

export async function ask<T>(req: Omit<Request, "tools"> & { tool: Tool }): Promise<T> {
  if (BACKEND === "claude-code") return (await import("./claude-code")).ccAsk<T>(req);
  const messages = [...req.messages];
  for (let attempt = 0; attempt < 3; attempt++) {
    const r = await invoke({ ...req, messages, tools: [req.tool] });
    const call = callsOf(r).find((c) => c.name === req.tool.name);
    const wrong = call ? shapeOf(req.tool, call.input as Record<string, unknown>) : null;
    if (call && !wrong) return call.input as T;
    messages.push(
      { role: "assistant", content: r.content },
      call
        ? { role: "user", content: [{ type: "tool_result", tool_use_id: call.id, is_error: true, content: `${wrong} Call ${req.tool.name} again with the corrected input.` }] }
        : { role: "user", content: `Answer by calling the ${req.tool.name} tool exactly once. stop_reason was ${r.stop_reason}.` },
    );
  }
  throw new Error(`${req.stage}: no ${req.tool.name} call after 3 attempts`);
}

ui/scripts/generate/check.ts:
/**
 * Every mechanical rule a map must pass, as one function: hand-authored maps
 * through scripts/check-map.mts, generated ones inside the pipeline, where the
 * problems go back to the model that wrote the node.
 */
/* eslint-disable @typescript-eslint/no-explicit-any -- walks map JSON, typed or not */
import { existsSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { buildMap, type MapFile } from "@/lib/map";
import { MARK_IDS } from "@/components/shapes";
import type { Anatomy } from "@/lib/data";
import { layoutDiagram, overlaps, segmentsOf } from "@/lib/diagram";

export interface CheckResult {
  problems: string[];
  roots: { id: string; depth: number; nodes: number }[];
  refs: number;
  sources: { ok: number; bad: number };
}

/** Lines of repo files, read once per run. */
export function fileReader(repo: string) {
  const cache = new Map<string, string[] | null>();
  return (file: string) => {
    if (!cache.has(file)) {
      try { cache.set(file, readFileSync(join(repo, file), "utf8").split("\n")); }
      catch { cache.set(file, null); }
    }
    return cache.get(file)!;
  };
}

/**
 * `generated` adds the rules a generated map lives under (D45): no hand-drawn
 * figures, no screenshots, no pasted source, only brand marks that have a
 * drawing, every diagram arrow citing the line it happens on, and at least
 * three levels under every root.
 */
export function check(
  map: Pick<MapFile, "AUTHORED" | "E0" | "LINKS">,
  repo: string,
  opts: { generated?: boolean; only?: Set<string> } = {},
): CheckResult {
  const linesOf = fileReader(repo);
  const problems: string[] = [];
  const ids = new Map<string, number>();
  const sources = { ok: 0, bad: 0 };
  let refs = 0;
  const gen = Boolean(opts.generated);
  const inRange = (file: string, start: number, end: number) => {
    const lines = linesOf(file);
    return lines !== null && start >= 1 && start <= end && end <= lines.length;
  };
  // `opens` may name a row-built child, so it is checked against the tree the
  // screen actually reads, not the authored one.
  const built = new Map<string, Set<string>>();
  const index = (ns: any[]) => ns.forEach((n) => { built.set(n.id, new Set((n.children ?? []).map((c: any) => c.id))); index(n.children ?? []); });
  index(buildMap({ RUN: {} as any, AUTHORED: map.AUTHORED, E0: [], LINKS: [] }, "").L0);

  const walkBlocks = (owner: string, blocks: any[] = [], d: number): number => {
    let deepest = d;
    for (const b of blocks) {
      if (b.kind === "source") {
        if (gen) problems.push(`SOURCE ${owner} — generated maps read code through \`code\` refs, never pasted source`);
        const lines = linesOf(b.file);
        if (!lines) { sources.bad++; problems.push(`MISSING ${owner} ${b.file}`); continue; }
        const want = b.code.replace(/\s+$/, "").split("\n");
        const got = lines.slice(b.start - 1, b.start - 1 + want.length);
        if (want.every((l: string, i: number) => l.trimEnd() === (got[i] ?? "").trimEnd())) sources.ok++;
        else { sources.bad++; problems.push(`MISMATCH ${owner} ${b.file}:${b.start}`); }
        deepest = Math.max(deepest, d + 1);
      }
      if (b.kind === "table")
        b.rows.forEach((r: string[], i: number) => {
          if (r.length !== b.columns.length) problems.push(`TABLE ${owner} row ${i} has ${r.length} cells, ${b.columns.length} columns`);
        });
      if (b.kind === "screen" && b.shot) {
        if (gen) problems.push(`SHOT ${owner} — generated maps have no screenshots; describe the screen with items`);
        else if (!existsSync(join(process.cwd(), "public", b.shot))) problems.push(`SHOT ${owner} ${b.shot} does not exist under ui/public`);
      }
      if (b.kind === "diagram") {
        const cells = new Set<string>();
        for (const x of b.boxes) {
          const c = `${x.col},${x.row}`;
          if (cells.has(c)) problems.push(`DIAGRAM ${owner} two boxes at col ${x.col} row ${x.row}`);
          cells.add(c);
          if (x.opens && !built.get(owner)?.has(x.opens)) problems.push(`DIAGRAM ${owner} box "${x.id}" opens "${x.opens}", which is not a child of ${owner}`);
        }
        for (const a of b.arrows) {
          for (const e of [a.from, a.to])
            if (!b.boxes.some((x: any) => x.id === e)) problems.push(`DIAGRAM ${owner} arrow end "${e}" is not a box`);
          if (gen && (a.label ?? "").length > 24) problems.push(`ARROW ${owner} ${a.from}→${a.to} label "${a.label}" is over 24 characters — a few words on the line`);
          if (gen) {
            const m = /^(.+):(\d+)(?:-(\d+))?$/.exec(a.at ?? "");
            if (!m) problems.push(`ARROW ${owner} ${a.from}→${a.to} cites no line — give \`at\` as file:line where this path happens`);
            else if (!inRange(m[1], +m[2], +(m[3] ?? m[2]))) problems.push(`ARROW ${owner} ${a.from}→${a.to} cites ${a.at}, which does not exist`);
          }
        }
        if (gen && b.arrows.every((a: any) => b.boxes.some((x: any) => x.id === a.from) && b.boxes.some((x: any) => x.id === a.to)))
          problems.push(...layoutProblems(b).problems.map((p) => `LAYOUT ${owner} ${p}`));
      }
      if (b.kind === "sequence")
        for (const m of b.rows) for (const a of [m.from, m.to])
          if (!b.actors.includes(a)) problems.push(`SEQUENCE ${owner} "${a}" is not an actor`);
      if (gen && (b.rows ?? []).some((r: any) => r.under)) problems.push(`UNDER ${owner} — a deeper part is a child node, not a row with \`under\``);
      for (const r of b.rows ?? []) if (r.under) deepest = Math.max(deepest, walkBlocks(owner, r.under, d + 1));
    }
    return deepest;
  };

  const walk = (n: any, d: number): number => {
    ids.set(n.id, (ids.get(n.id) ?? 0) + 1);
    if (!/^[A-Z0-9"]/.test(n.title)) problems.push(`TITLE ${n.id} "${n.title}" — start with a capital`);
    if (n.title.split(/\s+/).length > 4) problems.push(`TITLE ${n.id} "${n.title}" — more than 4 words`);
    // D42: no file paths on a card.
    for (const [k, v] of [["title", n.title], ["sub", n.sub]])
      if (/[\w-]+\/[\w.-]+|\b[\w-]+\.(tsx?|jsx?|py|go|rb|rs|java|sql|json)\b/.test(v ?? "")) problems.push(`PATH ${n.id} ${k} "${v}" — no file paths on a card`);
    // D38: two short sentences at most; the rest is pictures.
    const words = (n.detail ?? "").split(/\s+/).filter(Boolean).length;
    const sentences = (n.detail ?? "").split(/(?<=[.!?])\s+(?=[A-Z"`(])/).filter(Boolean).length;
    if (words > 40) problems.push(`DETAIL ${n.id} — ${words} words (max 40)`);
    if (sentences > 2) problems.push(`DETAIL ${n.id} — ${sentences} sentences (max 2)`);
    if (n.state !== "derived" && !n.unsure) problems.push(`UNSURE ${n.id} is ${n.state} but gives no reason`);
    if (gen && n.shape?.kind === "figure") problems.push(`SHAPE ${n.id} — figures are hand-drawn; use marks, count, or none`);
    if (n.shape?.kind === "marks")
      for (const m of n.shape.ids) if (!MARK_IDS.includes(m)) problems.push(`SHAPE ${n.id} mark "${m}" has no drawing (have: ${MARK_IDS.join(", ")})`);
    if (!n.code?.length) problems.push(`CODE ${n.id} has no code refs`);
    for (const c of n.code ?? []) {
      refs++;
      const lines = linesOf(c.file);
      if (!lines) problems.push(`CODE ${n.id} ${c.file} does not exist`);
      else if (!inRange(c.file, c.start, c.end))
        problems.push(`CODE ${n.id} ${c.file}:${c.start}-${c.end} out of range (file has ${lines.length})`);
    }
    for (const e of n.edges ?? []) for (const k of [e.from, e.to])
      if (!built.get(n.id)?.has(k)) problems.push(`EDGE ${n.id} ${e.from}→${e.to}: "${k}" is not a child`);
    let deepest = walkBlocks(n.id, n.anatomy, d);
    for (const c of n.children ?? []) deepest = Math.max(deepest, walk(c, d + 1));
    return deepest;
  };

  const roots = (opts.only ? map.AUTHORED.filter((r) => opts.only!.has(r.id)) : map.AUTHORED).map((r) => {
    const before = ids.size;
    const depth = walk(r, 1);
    if (gen && depth < 2) problems.push(`DEPTH ${r.id} reaches ${depth} level (min 2)`);
    return { id: r.id, depth, nodes: ids.size - before };
  });
  for (const [id, c] of ids) if (c > 1) problems.push(`DUP id ${id}`);
  if (!opts.only) {
    for (const e of map.E0 ?? []) for (const k of [e.from, e.to])
      if (!map.AUTHORED.some((r) => r.id === k)) problems.push(`E0 endpoint ${k} not a root`);
    for (const l of map.LINKS ?? []) for (const k of [l.from, l.to]) {
      const owner = k.slice(0, k.indexOf(":"));
      if (!ids.has(owner)) problems.push(`LINK owner ${owner} unknown`);
    }
  }
  return { problems, roots, refs, sources };
}

/** Widest a diagram may lay out — the explorify benchmark's widest is 1523. Past it the page holds the picture at its 70% floor and it scrolls far. */
export const MAX_DIAGRAM_W = 1550;

/**
 * What the page would draw badly: text on text, text on a box, a line through
 * a box it does not connect, a picture too wide to read. A label across
 * another line is only counted — it is drawn with a halo and stays legible.
 */
export function layoutProblems(block: Extract<Anatomy, { kind: "diagram" }>) {
  const L = layoutDiagram(block);
  const problems: string[] = [];
  if (L.W > MAX_DIAGRAM_W)
    problems.push(`is ${Math.round(L.W)}px wide (max ${MAX_DIAGRAM_W}) — shorten box subs, or use fewer columns and more rows`);
  const runs = L.arrows.map((a) => segmentsOf(a.d.slice(1).split("L").map((p) => p.split(" ").map(Number) as [number, number])));
  const labelled = L.arrows.filter((a) => a.label);
  let crossings = 0;
  labelled.forEach((a, i) => {
    const r = L.labels[i];
    L.boxes.forEach((p, j) => { if (overlaps(r, L.boxRects[j])) problems.push(`label "${a.label!.text}" sits on box "${p.b.label}"`); });
    labelled.slice(i + 1).forEach((o, k) => { if (overlaps(r, L.labels[i + 1 + k])) problems.push(`label "${a.label!.text}" sits on label "${o.label!.text}"`); });
    L.arrows.forEach((o, k) => { if (o !== a && runs[k].some((s) => overlaps(r, s))) crossings++; });
  });
  L.arrows.forEach((a, k) => {
    for (const s of runs[k])
      L.boxes.forEach((p, j) => {
        if (p.b.id === a.from || p.b.id === a.to) return;
        const b = L.boxRects[j];
        if (overlaps(s, { x: b.x + 1, y: b.y + 1, w: b.w - 2, h: b.h - 2 })) problems.push(`line ${a.from}→${a.to} runs through box "${p.b.label}"`);
      });
  });
  return { problems: [...new Set(problems)], crossings };
}

ui/scripts/generate/claude-code.ts:
/**
 * The same calls as bedrock.ts, made through the reader's own Claude Code
 * (`claude -p`) instead of an AWS account — so someone with a Claude plan maps
 * a repository without a second bill. SLOP_BACKEND=claude-code selects it.
 *
 * Parity with the API path is the point, so the request is held to the same
 * shape: the same model, the same system prompt (replacing Claude Code's own),
 * no built-in tools, no settings, CLAUDE.md or memory from this machine. A
 * structured answer is `--json-schema` with the tool's schema. An agent's tools
 * are the very functions the API path runs, served to Claude Code over MCP by
 * this process, so the checker that accepts a root is the same code either way.
 *
 * Claude Code runs the agent loop itself; what comes back is the final answer
 * and the token count, which is priced with the API table so the two backends'
 * bills compare. Replies are cached on disk like the API's.
 */

import { spawn } from "node:child_process";
import { createHash, randomUUID } from "node:crypto";
import { existsSync, mkdtempSync, readFileSync, writeFileSync } from "node:fs";
import { createServer, type Server } from "node:http";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { cacheFile, chargeUsage, slot, type Message, type Tool } from "./bedrock";

/** Bedrock profile → the name Claude Code takes for the same model. */
const CC_MODEL: Record<string, string> = {
  "global.anthropic.claude-haiku-4-5-20251001-v1:0": "claude-haiku-4-5-20251001",
  "global.anthropic.claude-sonnet-4-6": "claude-sonnet-4-6",
  "global.anthropic.claude-opus-4-6-v1": "claude-opus-4-6",
};
const ccModel = (model: string) => CC_MODEL[model] ?? model;

/** An empty working directory: no project CLAUDE.md, no repository for Claude Code's own tools to wander. */
let emptyDir: string | undefined;
const cwd = () => (emptyDir ??= mkdtempSync(join(tmpdir(), "slop-cc-")));

interface Result {
  is_error: boolean;
  subtype: string;
  result?: string;
  structured_output?: unknown;
  session_id: string;
  num_turns: number;
  modelUsage?: Record<string, { inputTokens: number; outputTokens: number; cacheReadInputTokens: number; cacheCreationInputTokens: number }>;
}

/** What one `claude -p` run used, summed over every model it called. */
type Usage = { input_tokens: number; output_tokens: number; cache_read_input_tokens: number; cache_creation_input_tokens: number };
function usageOf(r: Result): Usage {
  const u = { input_tokens: 0, output_tokens: 0, cache_read_input_tokens: 0, cache_creation_input_tokens: 0 };
  for (const m of Object.values(r.modelUsage ?? {})) {
    u.input_tokens += m.inputTokens;
    u.output_tokens += m.outputTokens;
    u.cache_read_input_tokens += m.cacheReadInputTokens;
    u.cache_creation_input_tokens += m.cacheCreationInputTokens;
  }
  return u;
}
const addUsage = (a: Usage, b: Usage): Usage => ({
  input_tokens: a.input_tokens + b.input_tokens,
  output_tokens: a.output_tokens + b.output_tokens,
  cache_read_input_tokens: a.cache_read_input_tokens + b.cache_read_input_tokens,
  cache_creation_input_tokens: a.cache_creation_input_tokens + b.cache_creation_input_tokens,
});

const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
const RETRYABLE = /overloaded|529|500|502|503|rate.?limit|429|ECONNRESET|timed? ?out/i;

/** One `claude -p` run, prompt on stdin, retried on transient failures. */
async function claude(args: string[], prompt: string, stage: string): Promise<Result> {
  return slot(async () => {
    for (let attempt = 0; ; attempt++) {
      const out = await new Promise<{ code: number | null; stdout: string; stderr: string }>((resolve) => {
        // Not a nested session of whatever Claude Code launched this script.
        const env = { ...process.env };
        delete env.CLAUDECODE;
        delete env.CLAUDE_CODE_ENTRYPOINT;
        // No effort means no thinking, as on the API path; with one, thinking is capped (see ccEffort).
        env.MAX_THINKING_TOKENS = args.includes("--effort") ? THINKING : "0";
        const p = spawn("claude", ["-p", "--output-format", "json", "--setting-sources", "", "--strict-mcp-config", ...args], { cwd: cwd(), env });
        let stdout = "", stderr = "";
        p.stdout.on("data", (d) => (stdout += d));
        p.stderr.on("data", (d) => (stderr += d));
        p.on("close", (code) => resolve({ code, stdout, stderr }));
        p.stdin.end(prompt);
      });
      let r: Result | null = null;
      try { r = JSON.parse(out.stdout); } catch { /* reported below */ }
      if (r && !r.is_error) return r;
      const msg = (r?.result ?? out.stderr ?? out.stdout).slice(0, 500);
      // A plan's usage window does not reopen in minutes; retrying only spends the wait.
      if (/usage limit|limit reached|resets? (at|in)/i.test(msg)) throw new Error(`${stage}: Claude plan usage limit reached — ${msg}`);
      if (r?.subtype === "error_max_turns") return r;
      if (attempt >= 5 || !RETRYABLE.test(msg)) throw new Error(`${stage}: claude -p failed (${r?.subtype ?? `exit ${out.code}`}): ${msg}`);
      await sleep(Math.min(60_000, 3000 * 2 ** attempt) * (0.5 + Math.random()));
    }
  });
}

/** The flags every run shares: the model, its effort, and our system prompt in place of Claude Code's. */
/**
 * Claude Code's effort for the API path's. The same word does not buy the same
 * thinking through both doors: at "high", ky's authors through Claude Code
 * thought for up to 43k tokens in one reply (13 minutes) where the API never
 * passed 10k. A 16k cap per reply kept the effort and the maps' quality and
 * halved the time. SLOP_CC_EFFORT and SLOP_CC_THINKING recalibrate; both are
 * part of the cache key.
 */
const THINKING = process.env.SLOP_CC_THINKING ?? "16000";
const ccEffort = (effort?: string) => (effort ? `${process.env.SLOP_CC_EFFORT ?? effort}/${THINKING}` : undefined);

function base(model: string, system: string, effort?: string): string[] {
  return ["--model", ccModel(model), "--system-prompt", system, ...(effort ? ["--effort", effort.split("/")[0]] : [])];
}

/** A conversation as one prompt. The API path's retries carry the previous answer and what was wrong with it; so does this. */
function transcript(messages: Message[]): string {
  return messages
    .map((m) => {
      const parts = typeof m.content === "string" ? [m.content] : m.content.map((b) => (b.type === "text" ? b.text : b.type === "tool_use" ? JSON.stringify(b.input) : b.type === "tool_result" ? b.content : ""));
      const text = parts.filter(Boolean).join("\n\n");
      return m.role === "assistant" ? `## Your previous answer\n${text}` : text;
    })
    .join("\n\n");
}

const systemText = (system: string | { type: string; text?: string }[]) => (typeof system === "string" ? system : system.map((b) => b.text ?? "").join("\n\n"));

/** A cached run: the answer and what it cost, so a replay reports the same size and price. */
function cached<T>(key: string, stage: string, model: string): (T & { usage: Usage }) | null {
  const file = cacheFile(key);
  if (!file || !existsSync(file)) return null;
  const hit = JSON.parse(readFileSync(file, "utf8")) as T & { usage: Usage };
  chargeUsage(stage, model, hit.usage, true);
  return hit;
}
function store(key: string, value: object) {
  const file = cacheFile(key, false);
  if (file) writeFileSync(file, JSON.stringify(value));
}
const keyOf = (...parts: string[]) => createHash("sha256").update(["claude-code", ...parts].join("\n")).digest("hex");

/** One structured answer, shaped by the tool's schema. */
export async function ccAsk<T>(req: { model: string; system: string | { type: string; text?: string }[]; messages: Message[]; tool: Tool; effort?: string; stage: string }): Promise<T> {
  const system = systemText(req.system);
  const prompt = `${transcript(req.messages)}\n\nAnswer with the ${req.tool.name} structure: ${req.tool.description}`;
  const schema = JSON.stringify(req.tool.input_schema);
  const effort = ccEffort(req.effort);
  const key = keyOf(req.model, effort ?? "", system, prompt, schema);
  const hit = cached<{ value: T }>(key, req.stage, req.model);
  if (hit) return hit.value;
  // Two built-in turns at least: the answer, then the structured-output call.
  const r = await claude([...base(req.model, system, effort), "--tools", "", "--json-schema", schema, "--max-turns", "4", "--no-session-persistence"], prompt, req.stage);
  if (r.structured_output === undefined) throw new Error(`${req.stage}: claude -p returned no structured output (${r.subtype})`);
  const usage = usageOf(r);
  chargeUsage(req.stage, req.model, usage, false);
  store(key, { value: r.structured_output, usage });
  return r.structured_output as T;
}

/* ── agents: our tools, served over MCP to Claude Code ───────── */

export interface Handled {
  content: string;
  isError?: boolean;
  /** Set when this call ends the agent's work: an accepted submit, a final review. */
  done?: unknown;
}
interface Session { tools: Tool[]; handle: (name: string, input: unknown) => Handled; done?: unknown; calls: number }

const sessions = new Map<string, Session>();
let server: Promise<{ port: number; server: Server }> | null = null;

/** A minimal MCP server over streamable HTTP, one path per agent: initialize, tools/list, tools/call. */
function mcp() {
  server ??= new Promise((resolve) => {
    const s = createServer((req, res) => {
      const session = sessions.get((req.url ?? "").split("/").pop() ?? "");
      if (req.method !== "POST" || !session) {
        res.writeHead(req.method === "POST" ? 404 : 405).end();
        return;
      }
      let body = "";
      req.on("data", (d) => (body += d));
      req.on("end", () => {
        const msg = JSON.parse(body) as { id?: number | string; method: string; params?: { name?: string; arguments?: unknown; protocolVersion?: string } };
        if (msg.id === undefined) {
          res.writeHead(202).end();
          return;
        }
        let result: unknown;
        if (msg.method === "initialize") result = { protocolVersion: msg.params?.protocolVersion ?? "2025-06-18", capabilities: { tools: {} }, serverInfo: { name: "slop", version: "1" } };
        else if (msg.method === "tools/list") result = { tools: session.tools.map((t) => ({ name: t.name, description: t.description, inputSchema: t.input_schema })) };
        else if (msg.method === "tools/call") {
          session.calls++;
          const h = session.done !== undefined ? { content: "Already accepted. Stop now." } : session.handle(msg.params!.name!, msg.params!.arguments);
          if (h.done !== undefined) session.done = h.done;
          result = { content: [{ type: "text", text: h.content }], isError: Boolean(h.isError) };
        } else result = {};
        res.writeHead(200, { "content-type": "application/json" }).end(JSON.stringify({ jsonrpc: "2.0", id: msg.id, result }));
      });
    });
    s.listen(0, "127.0.0.1", () => resolve({ port: (s.address() as { port: number }).port, server: s }));
  });
  return server;
}

/** Closes the MCP server so the process can exit. */
export async function ccClose() {
  if (server) (await server).server.close();
}

/**
 * One agent run: Claude Code drives the loop over our tools until a call
 * reports `done`. A run that stops without it is resumed with `nudge`, as the
 * API loop nudges a turn with no tool call.
 */
export async function ccAgent<T>(req: {
  model: string;
  system: string | { type: string; text?: string }[];
  prompt: string;
  tools: Tool[];
  handle: (name: string, input: unknown) => Handled;
  effort?: string;
  stage: string;
  maxTurns: number;
  nudge: string;
}): Promise<{ value: T | null; turns: number; calls: number; usage: Usage }> {
  const system = systemText(req.system);
  const effort = ccEffort(req.effort);
  const key = keyOf(req.model, effort ?? "", system, req.prompt, JSON.stringify(req.tools));
  const hit = cached<{ value: T | null; turns: number; calls: number }>(key, req.stage, req.model);
  if (hit) return hit;

  const { port } = await mcp();
  const id = randomUUID();
  const session: Session = { tools: req.tools, handle: req.handle, calls: 0 };
  sessions.set(id, session);
  const config = JSON.stringify({ mcpServers: { slop: { type: "http", url: `http://127.0.0.1:${port}/mcp/${id}` } } });
  const allowed = req.tools.map((t) => `mcp__slop__${t.name}`).join(",");
  let usage: Usage = { input_tokens: 0, output_tokens: 0, cache_read_input_tokens: 0, cache_creation_input_tokens: 0 };
  let turns = 0;
  try {
    let prompt = req.prompt;
    for (let run = 0; run < 3 && session.done === undefined && turns < req.maxTurns; run++) {
      // A nudge continues the same session, reads and all, as the API loop's next turn does.
      const flags = [...base(req.model, system, effort), "--tools", "", "--mcp-config", config, "--allowedTools", allowed, "--max-turns", String(req.maxTurns - turns)];
      const r = await claude(run === 0 ? [...flags, "--session-id", id] : [...flags, "--resume", id], prompt, req.stage);
      usage = addUsage(usage, usageOf(r));
      turns += r.num_turns;
      prompt = req.nudge;
    }
  } finally {
    sessions.delete(id);
  }
  chargeUsage(req.stage, req.model, usage, false);
  const out = { value: (session.done as T | undefined) ?? null, turns, calls: session.calls, usage };
  store(key, out);
  return out;
}

ui/scripts/generate/cut.ts:
/**
 * Stage 2 — the top level: what someone does with this product, and which
 * files each of those things owns (D16, D33).
 *
 * The one call whose mistakes every later stage inherits, so it runs on the
 * strongest model available and its output is checked mechanically: every
 * source file must land in a root or be excluded with a reason, and every
 * edge must join two roots.
 */

import { readFileSync } from "node:fs";
import type { Edge } from "@/lib/data";
import { ask, type Message } from "./bedrock";
import type { Inventory } from "./inventory";
import { oneLine, type FileSummary } from "./summarize";

export interface Root {
  id: string;
  prefix: string;
  title: string;
  sub: string;
  why: string;
  /** Repo paths; one ending in "/" claims everything under it. */
  files: string[];
}

export interface Cut {
  about: string;
  roots: Root[];
  excluded: { path: string; reason: string }[];
  edges: Edge[];
}

const TOOL = {
  name: "cut",
  description: "Record the top level of the map.",
  input_schema: {
    type: "object",
    additionalProperties: false,
    required: ["about", "roots", "excluded", "edges"],
    properties: {
      about: { type: "string", description: "One sentence: what the top level is cut by and why that order. E.g. 'Cut by the life of one event — an organisation creates it, a student finds and joins it — after the two steps every account passes first.'" },
      roots: {
        type: "array",
        items: {
          type: "object",
          additionalProperties: false,
          required: ["id", "prefix", "title", "sub", "why", "files"],
          properties: {
            id: { type: "string", description: "kebab-case, short: 'sign-up', 'billing'." },
            prefix: { type: "string", description: "2-3 lowercase letters, unique per root; every node id under this root starts with '<prefix>-'." },
            title: { type: "string", description: "1-4 words, Title Case, everyday words." },
            sub: { type: "string", description: "One plain line: what this is. No file paths." },
            why: { type: "string", description: "One sentence for the author of this root: what it covers and where its boundary with the neighbouring roots is." },
            files: { type: "array", items: { type: "string" }, description: "Paths this root owns. A path ending in '/' claims every file under it. A shared file may appear in more than one root." },
          },
        },
      },
      excluded: {
        type: "array",
        description: "Source files or directories ('/'-terminated) deliberately left out of every root, each with a reason: generated, vendored, dead, pure tooling.",
        items: { type: "object", additionalProperties: false, required: ["path", "reason"], properties: { path: { type: "string" }, reason: { type: "string" } } },
      },
      edges: {
        type: "array",
        description: "Real precedence between roots. Ordered edges with no lane form the shared path; edges sharing a lane form one branch after a fork; an edge with no order is a hand-off between branches.",
        items: {
          type: "object",
          additionalProperties: false,
          required: ["from", "to", "label"],
          properties: {
            from: { type: "string" },
            to: { type: "string" },
            label: { type: "string", description: "A few words read as '<label> <to title>': 'routes students to', 'publishes into'." },
            order: { type: "integer", description: "1-indexed position in the path or lane. Omit for a hand-off." },
            lane: { type: "string", description: "Only where the path genuinely forks (e.g. by account type): the branch name." },
          },
        },
      },
    },
  },
};

const INSTRUCTIONS = `Choose the top level of the map: 4 to 10 roots.

- Roots are what someone DOES with the product, in the order they do it — a journey, not a stack of layers. For a library, the someone is the caller.
- Title a journey root as the action, the way a user would say it: "Signing Up", "Writing A Post", "Making A Request" — not a layer or module name like "Authentication" or "Post Dashboard". Roots off the path may be nouns ("The Database").
- Put the roots that are steps of one journey on the path with ordered edges. Fork into lanes only where the code really routes different users down different paths.
- Things that are not steps (the database, background jobs, shared infrastructure, admin tooling) are roots off the path with no edge. Use them sparingly; prefer folding infrastructure into the feature that uses it.
- Every source file listed must be in at least one root's files or in excluded. Use '/'-terminated directory paths to keep the list short when a whole directory belongs to one root.
- A root should own enough to explain in 2-3 levels and not so much that it can't: roughly 3-60 files.
- Ids are kebab-case; prefixes are 2-3 letters and unique.
Call the cut tool once.`;

/** The roots that claim a path: an exact listing, else the longest directory claim. */
export function owners(cut: Cut, path: string): string[] {
  const exact = cut.roots.filter((r) => r.files.includes(path)).map((r) => r.id);
  if (exact.length) return exact;
  let best = -1;
  let ids: string[] = [];
  for (const r of cut.roots)
    for (const f of r.files)
      if (f.endsWith("/") && path.startsWith(f)) {
        if (f.length > best) { best = f.length; ids = [r.id]; }
        else if (f.length === best && !ids.includes(r.id)) ids.push(r.id);
      }
  return ids;
}

const excludedBy = (cut: Cut, path: string) => cut.excluded.some((e) => e.path === path || (e.path.endsWith("/") && path.startsWith(e.path)));

function problems(cut: Cut, inv: Inventory): string[] {
  const out: string[] = [];
  const ids = new Set(cut.roots.map((r) => r.id));
  const prefixes = new Set<string>();
  for (const r of cut.roots) {
    if (!/^[a-z0-9]+(-[a-z0-9]+)*$/.test(r.id)) out.push(`root id "${r.id}" is not kebab-case`);
    if (!/^[a-z]{2,3}$/.test(r.prefix) || prefixes.has(r.prefix)) out.push(`root ${r.id}: prefix "${r.prefix}" must be 2-3 lowercase letters and unique`);
    prefixes.add(r.prefix);
    if (r.title.split(/\s+/).length > 4) out.push(`root ${r.id}: title "${r.title}" has more than 4 words`);
  }
  for (const e of cut.edges) for (const k of [e.from, e.to]) if (!ids.has(k)) out.push(`edge ${e.from}→${e.to}: "${k}" is not a root id`);
  const missing = inv.files.filter((f) => f.code && !f.test && !owners(cut, f.path).length && !excludedBy(cut, f.path)).map((f) => f.path);
  if (missing.length) out.push(`${missing.length} source files are in no root and not excluded:\n${missing.slice(0, 300).join("\n")}`);
  return out;
}

export async function cutRepo(inv: Inventory, sums: Record<string, FileSummary>, model: string): Promise<{ cut: Cut; leftover: string[] }> {
  // Only what bears on the cut: rules for writing a level change often, and
  // each change would otherwise re-cut every repository and rename its roots.
  const all = readFileSync("scripts/generate/prompts/rules.md", "utf8");
  const rules = all.slice(0, all.indexOf("## What a level shows"));
  const listing = inv.files
    .filter((f) => f.code && !f.test)
    .map((f) => (sums[f.path] ? oneLine(sums[f.path]) : `${f.path} (${f.lines} lines)`))
    .join("\n");
  const other = inv.files.filter((f) => (!f.code || f.test) && !f.outside).map((f) => f.path);
  const messages: Message[] = [
    {
      role: "user",
      content: [
        `# Repository: ${inv.name} @ ${inv.commit}`,
        `## README\n${inv.readme || "(none)"}`,
        ...(inv.scope ? [`## Scope\nThis map covers only part of the repository: ${inv.scope.paths.join(", ")}. Its reader: ${inv.scope.focus} Cut the roots by what that reader does with this part. Code outside the scope is not listed and needs no root.`] : []),
        `## Dependencies\n${inv.deps.join(", ") || "(none)"}`,
        `## Source files (${inv.files.filter((f) => f.code && !f.test).length}), one line each\n${listing}`,
        `## Other files (tests, config, docs, assets) — need no root\n${other.slice(0, 400).join("\n")}${other.length > 400 ? `\n… and ${other.length - 400} more` : ""}`,
        INSTRUCTIONS,
      ].join("\n\n"),
    },
  ];
  const system = [{ type: "text" as const, text: rules, cache_control: { type: "ephemeral" as const } }];

  let cut: Cut | null = null;
  for (let round = 0; round < 3; round++) {
    cut = await ask<Cut>({ model, stage: "cut", effort: "high", maxTokens: 32000, system, messages, tool: TOOL });
    const p = problems(cut, inv);
    if (!p.length) return { cut, leftover: [] };
    messages.push(
      { role: "assistant", content: [{ type: "text", text: JSON.stringify(cut) }] },
      { role: "user", content: `That cut has problems. Fix them and call cut again with the complete corrected cut:\n- ${p.join("\n- ")}` },
    );
  }
  // Still uncovered after three rounds: recorded, not silently dropped.
  const leftover = inv.files.filter((f) => f.code && !f.test && !owners(cut!, f.path).length && !excludedBy(cut!, f.path)).map((f) => f.path);
  cut!.excluded.push(...leftover.map((path) => ({ path, reason: "left unassigned by the cut after three rounds" })));
  return { cut: cut!, leftover };
}

ui/scripts/generate/evaluate.ts:
/**
 * Numbers for comparing maps, the explorify benchmark included. A map that
 * matches these is not proven good — that takes a walk through it in the
 * browser — but one that misses them is reliably worse.
 */
/* eslint-disable @typescript-eslint/no-explicit-any -- map and report JSON */
import { existsSync, readFileSync } from "node:fs";
import type { Node } from "@/lib/data";
import type { MapFile } from "@/lib/map";
import { rootOf } from "@/lib/maps";
import { check } from "./check";
import { owners, type Cut } from "./cut";

export function evaluate(name: string, map: MapFile) {
  const nodes: Node[] = [];
  const walk = (n: Node) => { nodes.push(n); (n.children ?? []).forEach(walk); };
  map.AUTHORED.forEach(walk);
  const blocks = nodes.flatMap((n) => n.anatomy ?? []);
  const diagrams = blocks.filter((b) => b.kind === "diagram") as any[];
  const parents = nodes.filter((n) => n.children?.length);
  // D40: how much of the way down is through the picture.
  const linked = parents.map((n) => {
    const kids = new Set(n.children!.map((c) => c.id));
    const opened = new Set((n.anatomy ?? []).flatMap((b: any) => (b.kind === "diagram" ? b.boxes.map((x: any) => x.opens) : [])).filter((id: string) => kids.has(id)));
    return opened.size / kids.size;
  });
  const report = existsSync(`maps/${name}/report.json`) ? JSON.parse(readFileSync(`maps/${name}/report.json`, "utf8")) : null;
  const root = rootOf(map.RUN);
  const generated = Boolean(map.RUN.models);
  const problems = existsSync(root) ? check(map, root, { generated }).problems.length : "no checkout";
  const depth = (n: Node): number => 1 + Math.max(0, ...(n.children ?? []).map(depth));
  return {
    map: name,
    roots: map.AUTHORED.length,
    nodes: nodes.length,
    depth: map.AUTHORED.map(depth).join(""),
    "kids/parent": +(parents.reduce((a, n) => a + n.children!.length, 0) / Math.max(1, parents.length)).toFixed(1),
    "refs/node": +(nodes.reduce((a, n) => a + (n.code?.length ?? 0), 0) / nodes.length).toFixed(1),
    "diagram %": Math.round((100 * nodes.filter((n) => n.anatomy?.some((b) => b.kind === "diagram")).length) / nodes.length),
    "boxes/diagram": +(diagrams.reduce((a, d) => a + d.boxes.length, 0) / Math.max(1, diagrams.length)).toFixed(1),
    "opens %": Math.round((100 * linked.reduce((a, x) => a + x, 0)) / Math.max(1, linked.length)),
    "blocks/node": +(blocks.length / nodes.length).toFixed(1),
    issues: nodes.reduce((a, n) => a + (n.issues?.length ?? 0), 0),
    "not certain %": Math.round((100 * nodes.filter((n) => n.state !== "derived").length) / nodes.length),
    problems,
    "verify %": report?.verifyPassRate ?? "",
    usd: report?.fullUsd ?? "",
    // Tokens sent and received over the whole run, cached prompt reads included (in thousands).
    "k tokens": report ? Math.round(Object.values(report.bill as Record<string, { input: number; output: number; cacheRead: number }>).reduce((a, b) => a + b.input + b.output + b.cacheRead, 0) / 1000) : "",
    min: report ? Math.round(report.elapsed.total / 60) : "",
  };
}

/**
 * How far a fresh cut drifts from the map's own: for each source file, do the
 * two cuts put it with the same neighbours? Root ids and titles differ between
 * samples, so files are compared pairwise — two files together in one cut and
 * apart in the other is a disagreement.
 */
export function stability(name: string, otherCutFile: string): string {
  const a: Cut = JSON.parse(readFileSync(`maps/${name}/.cache/cut.json`, "utf8"));
  const b: Cut = JSON.parse(readFileSync(otherCutFile, "utf8"));
  const sums = Object.keys(JSON.parse(readFileSync(`maps/${name}/.cache/summaries.json`, "utf8")));
  const key = (c: Cut, p: string) => owners(c, p).sort().join(",") || "(excluded)";
  let agree = 0, total = 0;
  for (let i = 0; i < sums.length; i++)
    for (let j = i + 1; j < sums.length; j++) {
      const sa = key(a, sums[i]) === key(a, sums[j]);
      const sb = key(b, sums[i]) === key(b, sums[j]);
      total++;
      if (sa === sb) agree++;
    }
  return `${name}: ${a.roots.length} vs ${b.roots.length} roots; pairwise file-grouping agreement ${((100 * agree) / total).toFixed(1)}% over ${sums.length} files\n  A: ${a.roots.map((r) => r.title).join(" · ")}\n  B: ${b.roots.map((r) => r.title).join(" · ")}`;
}

ui/scripts/generate/inventory.ts:
/**
 * Stage 0 — what is in the repository, with no model involved.
 *
 * Everything the later stages are allowed to cite comes from here: the file
 * list, line counts, the manifest's dependencies, and (for TS/JS) which file
 * imports which. A model never sees a path this did not list.
 */

import { execFileSync } from "node:child_process";
import { createHash } from "node:crypto";
import { existsSync, readFileSync, statSync } from "node:fs";
import { dirname, extname, join, normalize } from "node:path";
import ts from "typescript";
import { MARK_IDS } from "@/components/shapes";

export interface RepoFile {
  path: string;
  lines: number;
  hash: string;
  /** Source a model should read and summarise, as opposed to config, docs or assets. */
  code: boolean;
  /** A test, fixture or story: listed and citable, never summarised or required in a root. */
  test: boolean;
  /** Outside a --scope: readable and citable, but no root owns it. */
  outside?: boolean;
}

export interface Inventory {
  repo: string;
  name: string;
  commit: string;
  files: RepoFile[];
  readme: string;
  /** Dependency names from every manifest found, sorted. */
  deps: string[];
  /** Brand marks this repo has a real dependency for (D25). */
  marks: string[];
  /** A map of part of a large repo: the paths it covers and what a reader of it does. */
  scope?: { paths: string[]; focus: string };
  /** TS/JS only: repo-relative imports per file. */
  imports: Record<string, string[]>;
}

const CODE = new Set([
  ".ts", ".tsx", ".js", ".jsx", ".mjs", ".cjs", ".vue", ".svelte", ".astro",
  ".py", ".go", ".rb", ".rs", ".java", ".kt", ".scala", ".swift", ".php", ".cs", ".ex", ".exs",
  ".sql", ".prisma", ".graphql", ".gql", ".proto",
]);
const SKIP = [
  /(^|\/)(node_modules|vendor|dist|build|out|coverage|\.next|\.turbo|\.git|__snapshots__|migrations\/meta)\//,
  /(^|\/)(package-lock\.json|yarn\.lock|pnpm-lock\.yaml|bun\.lockb?|poetry\.lock|uv\.lock|Cargo\.lock|go\.sum|composer\.lock)$/,
  /\.(min\.js|map|png|jpe?g|gif|webp|ico|svg|woff2?|ttf|otf|eot|mp4|mp3|wav|pdf|zip|gz|lock|snap)$/i,
  /\.d\.ts$/,
];
const TEST = /(^|\/)(tests?|__tests__|__mocks__|specs?|e2e|cypress|playwright|fixtures|stories)\/|\.(test|spec|stories|e2e)\.[a-z]+$|(^|\/)(test_[^/]+|[^/]+_test)\.(py|go)$|(^|\/)conftest\.py$/;
/** Bigger than this is generated, vendored, or a fixture — listed, never summarised. */
const MAX_BYTES = 150_000;

/** Which dependency names stand for which brand mark. */
const MARK_DEPS: Record<string, RegExp> = {
  aws: /^@aws-sdk\/|^aws-sdk$|^boto3$/,
  bedrock: /bedrock/,
  s3: /client-s3|s3-request-presigner/,
  supabase: /^@supabase\/|^supabase$/,
  openai: /^openai$/,
  postgres: /^pg$|^postgres$|^psycopg|^@neondatabase|^@vercel\/postgres|^asyncpg$/,
  nextjs: /^next$/,
  zod: /^zod$/,
  pdf: /pdf/,
  expo: /^expo$/,
  googlemaps: /google-maps|googlemaps|places-autocomplete/,
  flask: /^flask$/i,
  deno: /^deno$/,
};

function git(repo: string, ...args: string[]) {
  return execFileSync("git", ["-C", repo, ...args], { encoding: "utf8", maxBuffer: 64 << 20 }).trim();
}

function manifests(repo: string, files: string[]): string[] {
  const deps = new Set<string>();
  for (const f of files) {
    if (f.endsWith("package.json")) {
      try {
        const p = JSON.parse(readFileSync(join(repo, f), "utf8"));
        for (const k of ["dependencies", "devDependencies", "peerDependencies"]) Object.keys(p[k] ?? {}).forEach((d) => deps.add(d));
      } catch { /* a broken manifest names nothing */ }
    } else if (/(^|\/)(requirements[^/]*\.txt|pyproject\.toml)$/.test(f)) {
      const text = readFileSync(join(repo, f), "utf8");
      for (const m of text.matchAll(/^\s*"?([A-Za-z][\w.-]+)\s*(?:[<>=~!\[;"]|$)/gm)) deps.add(m[1].toLowerCase());
    }
  }
  return [...deps].sort();
}

/** `@/x` style aliases from the nearest tsconfig, as prefix → directory. */
function aliases(repo: string, files: string[]): [string, string][] {
  const out: [string, string][] = [];
  for (const f of files.filter((x) => /(^|\/)tsconfig[^/]*\.json$/.test(x))) {
    const cfg = ts.readConfigFile(join(repo, f), ts.sys.readFile).config;
    const base = join(dirname(f), cfg?.compilerOptions?.baseUrl ?? ".");
    for (const [k, v] of Object.entries<string[]>(cfg?.compilerOptions?.paths ?? {}))
      if (k.endsWith("/*") && v[0]?.endsWith("/*")) out.push([k.slice(0, -1), normalize(join(base, v[0].slice(0, -1))) + "/"]);
  }
  return out;
}

function resolveImport(from: string, spec: string, known: Set<string>, alias: [string, string][]): string | null {
  let base: string | null = null;
  if (spec.startsWith(".")) base = normalize(join(dirname(from), spec));
  else for (const [prefix, dir] of alias) if (spec.startsWith(prefix)) { base = normalize(dir + spec.slice(prefix.length)); break; }
  if (base === null) return null;
  base = base.replace(/^\.\//, "");
  const tries = [base, ...[".ts", ".tsx", ".js", ".jsx", ".mjs", ".vue", ".svelte"].flatMap((e) => [base + e, `${base}/index${e}`])];
  // `./x.js` in TS source names `./x.ts`.
  if (/\.(m?js|jsx)$/.test(base)) tries.push(base.replace(/\.(m?js|jsx)$/, ".ts"), base.replace(/\.(m?js|jsx)$/, ".tsx"));
  return tries.find((t) => known.has(t)) ?? null;
}

export function inventory(repo: string): Inventory {
  const listed = git(repo, "ls-files").split("\n").filter(Boolean).sort();
  const files: RepoFile[] = [];
  for (const path of listed) {
    if (SKIP.some((r) => r.test(path))) continue;
    const abs = join(repo, path);
    if (!existsSync(abs) || !statSync(abs).isFile()) continue;
    const buf = readFileSync(abs);
    if (buf.includes(0)) continue;
    const text = buf.toString("utf8");
    files.push({
      path,
      lines: text.split("\n").length,
      hash: createHash("sha1").update(buf).digest("hex").slice(0, 12),
      code: CODE.has(extname(path).toLowerCase()) && buf.length <= MAX_BYTES,
      test: TEST.test(path),
    });
  }

  const known = new Set(files.map((f) => f.path));
  const alias = aliases(repo, listed);
  const imports: Record<string, string[]> = {};
  for (const f of files) {
    if (!/\.(tsx?|jsx?|mjs|cjs)$/.test(f.path) || !f.code) continue;
    const info = ts.preProcessFile(readFileSync(join(repo, f.path), "utf8"), true, true);
    const deps = info.importedFiles.map((i) => resolveImport(f.path, i.fileName, known, alias)).filter((x): x is string => x !== null);
    if (deps.length) imports[f.path] = [...new Set(deps)].sort();
  }

  const readmeFile = listed.find((f) => /^readme(\.md|\.rst|\.txt)?$/i.test(f));
  const deps = manifests(repo, listed);
  return {
    repo,
    name: repo.replace(/\/+$/, "").split("/").pop()!,
    commit: git(repo, "rev-parse", "--short", "HEAD"),
    files,
    readme: readmeFile ? readFileSync(join(repo, readmeFile), "utf8").slice(0, 8000) : "",
    deps,
    marks: MARK_IDS.filter((m) => MARK_DEPS[m] && deps.some((d) => MARK_DEPS[m].test(d))),
    imports,
  };
}

/** A file's text with 1-indexed line numbers, the only form a model ever reads. */
export function numbered(repo: string, path: string, start = 1, end = Infinity): string {
  const lines = readFileSync(join(repo, path), "utf8").split("\n");
  const s = Math.max(1, start);
  const e = Math.min(lines.length, end);
  return lines.slice(s - 1, e).map((l, i) => `${String(s + i).padStart(5)}  ${l}`).join("\n");
}

