/**
 * The whole generator, stage by stage. Lives in a .ts module rather than the
 * .mts entry point so every stage shares one instance of bedrock.ts: tsx loads
 * .mts as ESM and .ts as CommonJS, and two instances meant the cache and the
 * bill were set in one and read from the other.
 */
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { resolve } from "node:path";
import type { Edge, Node } from "@/lib/data";
import type { MapFile } from "@/lib/map";
import { authorRoot, type Authored } from "./author";
import { BACKEND, bill, MODELS, cacheIn, throttle } from "./bedrock";
import { ccClose } from "./claude-code";
import { check } from "./check";
import { cutRepo, type Cut } from "./cut";
import { inventory } from "./inventory";
import { summarize } from "./summarize";
import { verifyTree, type Verdict } from "./verify";

export async function main(args: string[]) {
  const opt = (k: string) => { const i = args.indexOf(k); return i === -1 ? undefined : args[i + 1]; };

  const repo = resolve(args.find((a, i) => !a.startsWith("--") && !args[i - 1]?.startsWith("--"))!);
  const inv = inventory(repo);
  const name = opt("--name") ?? inv.name.toLowerCase();
  // --scope maps part of a large repo; the rest stays readable to the authors.
  const scope = opt("--scope")?.split(",");
  if (scope) {
    inv.scope = { paths: scope, focus: opt("--focus") ?? "" };
    for (const f of inv.files) if (!scope.some((p) => f.path === p || f.path.startsWith(p.replace(/\/?$/, "/")))) Object.assign(f, { code: false, outside: true });
  }
  const only = opt("--roots")?.split(",");
  const stopAfter = opt("--stop-after");
  const pick = (env: string | undefined) => MODELS[(env ?? "opus") as keyof typeof MODELS] ?? MODELS.opus;
  const models = { summarize: MODELS.haiku, cut: pick(process.env.SLOP_CUT), author: pick(process.env.SLOP_AUTHOR), verify: MODELS.haiku };

  const out = `maps/${name}`;
  mkdirSync(out, { recursive: true });
  cacheIn(`${out}/.cache`, { fresh: args.includes("--fresh") });
  const t0 = Date.now();
  const elapsed: Record<string, number> = {};
  const lap = async <T,>(stage: string, fn: () => Promise<T>): Promise<T> => {
    const t = Date.now();
    const r = await fn();
    elapsed[stage] = Math.round((Date.now() - t) / 1000);
    console.log(`· ${stage} done in ${elapsed[stage]}s — $${(bill[stage]?.usd ?? 0).toFixed(2)}`);
    return r;
  };
  const say = (s: string) => console.log(`  ${s}`);

  const code = inv.files.filter((f) => f.code && !f.test);
  console.log(`${inv.name} @ ${inv.commit}: ${inv.files.length} files, ${code.length} to summarise, marks [${inv.marks.join(", ")}]`);

  const sums = await lap("summarize", () =>
    summarize(inv, (n, of) => { if (n % 25 === 0 || n === of) say(`summarised ${n}/${of}`); }),
  );
  writeFileSync(`${out}/.cache/summaries.json`, JSON.stringify(sums, null, 1));
  if (stopAfter === "summarize") return;

  // A re-run with --roots redoes some roots of the map that is there, so it
  // keeps that map's cut: a fresh one could rename every root.
  const { cut, leftover } =
    only && existsSync(`${out}/.cache/cut.json`)
      ? { cut: JSON.parse(readFileSync(`${out}/.cache/cut.json`, "utf8")) as Cut, leftover: [] as string[] }
      : await lap("cut", () => cutRepo(inv, sums, models.cut));
  writeFileSync(`${out}/.cache/cut.json`, JSON.stringify(cut, null, 1));
  for (const r of cut.roots) say(`${r.id.padEnd(18)} ${r.title} — ${r.files.length} paths`);
  if (leftover.length) say(`${leftover.length} files left unassigned after three rounds`);
  if (stopAfter === "cut") return;

  // A re-run with --roots reuses the roots it is not asked to redo.
  const prev: MapFile | null = only && existsSync(`${out}/map.json`) ? JSON.parse(readFileSync(`${out}/map.json`, "utf8")) : null;
  const authored: Record<string, Authored> = {};
  await lap("author", () =>
    Promise.all(
      cut.roots.map(async (r) => {
        const kept = prev?.AUTHORED.find((n) => n.id === r.id);
        if (only && !only.includes(r.id) && kept) {
          authored[r.id] = { root: kept, turns: 0, reads: 0, submits: 0, problems: [] };
          return;
        }
        authored[r.id] = await authorRoot(r, cut, inv, sums, models.author, say);
        say(`${r.id}: ${authored[r.id].root ? "accepted" : "FAILED"} after ${authored[r.id].turns + 1} turns, ${authored[r.id].reads} reads`);
      }),
    ),
  );

  const verdicts: Record<string, Verdict[]> = {};
  await lap("verify", () =>
    Promise.all(
      cut.roots.map(async (r) => {
        const root = authored[r.id].root;
        if (root && !(only && !only.includes(r.id))) verdicts[r.id] = await verifyTree(root, inv, models.author);
      }),
    ),
  );

  const AUTHORED: Node[] = cut.roots.flatMap((r, i) => {
    const n = authored[r.id].root;
    return n ? [{ ...n, col: 0, row: i }] : [];
  });
  const present = new Set(AUTHORED.map((n) => n.id));
  const E0: Edge[] = cut.edges.filter((e) => present.has(e.from) && present.has(e.to)).map((e) => ({ ...e, state: "derived" as const }));
  // A stage replayed wholly from cache took seconds and cost nothing, not what
  // generating it costs; the last report's time and bill for it stand, so the
  // record stays a plan.
  const last = existsSync(`${out}/report.json`) ? JSON.parse(readFileSync(`${out}/report.json`, "utf8")) : null;
  const before = last?.elapsed ?? {};
  const spent = { ...bill };
  let total = Math.round((Date.now() - t0) / 1000);
  for (const stage of Object.keys(elapsed)) {
    const runs = Object.entries(bill).filter(([k]) => k === stage || k.startsWith(`${stage}-`));
    if (runs.length && runs.every(([, b]) => b.calls === b.cached) && typeof before[stage] === "number") {
      total += before[stage] - elapsed[stage];
      elapsed[stage] = before[stage];
      for (const [k] of runs) if (last.bill?.[k]) spent[k] = last.bill[k];
    }
  }
  const map: MapFile = {
    RUN: {
      command: `understand-slop map ${inv.name}`,
      // A scoped map is named for its part and counts only the files it covers.
      repo: inv.scope ? name : inv.name,
      about: cut.about,
      commit: inv.commit,
      files: inv.scope ? code.length : inv.files.length,
      elapsed: `${Math.round(total / 60)} min`,
      root: repo,
      models,
    },
    AUTHORED,
    E0,
    LINKS: [],
  };
  const final = check(map, repo, { generated: true });
  writeFileSync(`${out}/map.json`, JSON.stringify(map, null, 1) + "\n");

  const allVerdicts = Object.values(verdicts).flat();
  const usd = Object.values(spent).reduce((a, b) => a + b.usd, 0);
  const fullUsd = Object.values(spent).reduce((a, b) => a + b.fullUsd, 0);
  const report = {
    repo: inv.name,
    commit: inv.commit,
    // Through Claude Code, `usd` is what the same tokens cost at the API list
    // price; on a Claude plan they come out of the plan's usage instead.
    backend: BACKEND,
    models,
    // A --roots repair is not what the map costs to make: the full run's
    // time and price stand, and the repair is listed beside them.
    ...(only && last
      ? { elapsed: last.elapsed, usd: last.usd, fullUsd: last.fullUsd, bill: last.bill, repairs: [...(last.repairs ?? []), { roots: only, seconds: total, usd: Math.round(Object.values(bill).reduce((a, b) => a + b.usd, 0) * 100) / 100, bill }] }
      : { elapsed: { ...elapsed, total }, usd: Math.round(usd * 100) / 100, fullUsd: Math.round(fullUsd * 100) / 100, bill: spent }),
    throttled: { waits: throttle.waits, seconds: Math.round(throttle.seconds) },
    files: { listed: inv.files.length, summarised: code.length, unassigned: leftover },
    excluded: cut.excluded,
    roots: cut.roots.map((r) => ({
      id: r.id,
      title: r.title,
      accepted: Boolean(authored[r.id].root),
      turns: authored[r.id].turns + 1,
      reads: authored[r.id].reads,
      submits: authored[r.id].submits,
      lastProblems: authored[r.id].root ? [] : authored[r.id].problems.slice(0, 20),
      verify: verdicts[r.id] ? { nodes: verdicts[r.id].length, ok: verdicts[r.id].filter((v) => v.ok).length, flagged: verdicts[r.id].filter((v) => v.flagged).length, rewritten: verdicts[r.id].filter((v) => v.rewritten).map((v) => ({ id: v.id, claims: v.claims })), downgraded: verdicts[r.id].filter((v) => v.downgraded).map((v) => v.id) } : (last?.roots?.find((x: { id: string }) => x.id === r.id)?.verify ?? null),
    })),
    check: { problems: final.problems, depth: final.roots },
    verifyPassRate: only && last?.verifyPassRate != null ? null : allVerdicts.length ? Math.round((100 * allVerdicts.filter((v) => v.ok).length) / allVerdicts.length) : null,
  };
  // A repair verified only the roots it redid; the rate is over every root.
  if (report.verifyPassRate === null) {
    const v = report.roots.map((r) => r.verify).filter(Boolean) as { nodes: number; ok?: number; downgraded: string[] }[];
    const nodes = v.reduce((a, x) => a + x.nodes, 0);
    if (nodes) report.verifyPassRate = Math.round((100 * v.reduce((a, x) => a + (x.ok ?? x.nodes - x.downgraded.length), 0)) / nodes);
  }
  writeFileSync(`${out}/report.json`, JSON.stringify(report, null, 1) + "\n");
  console.log(`\n${out}/map.json — ${AUTHORED.length}/${cut.roots.length} roots, ${final.problems.length} check problems, verify ${report.verifyPassRate}% , $${report.usd} spent ($${report.fullUsd} uncached), ${report.elapsed.total}s`);
  final.problems.slice(0, 20).forEach((p) => console.log(`  ${p}`));
  await ccClose();
}

ui/scripts/generate/schema.ts:
/**
 * The shape a generated node must have, checked field by field so the author
 * gets a precise list back instead of a renderer crash. The types themselves
 * stay in lib/data.ts — `typeReference` hands the model that file's own text,
 * comments included, because those comments ARE the standard each field is
 * held to.
 */
/* eslint-disable @typescript-eslint/no-explicit-any -- validates untrusted model output */
import { readFileSync } from "node:fs";

/** lib/data.ts from `State` to just before the old inline fixture. */
export function typeReference(): string {
  const src = readFileSync("lib/data.ts", "utf8");
  return src.slice(src.indexOf("export type State"), src.indexOf("export const RUN"));
}

const STATES = ["derived", "partial", "inferred"];
const KINDS: Record<string, string[]> = {
  diagram: ["caption", "boxes", "arrows"],
  table: ["columns", "rows", "state"],
  sequence: ["actors", "rows"],
  screen: ["title", "items"],
  example: ["caption", "value"],
  schema: ["table", "rows"],
  routes: ["rows"],
  flow: ["rows"],
  facts: ["rows"],
  bars: ["unit", "rows"],
  parts: ["total", "rows"],
  chips: ["rows"],
  map: ["rows"],
};

const isStr = (v: unknown) => typeof v === "string" && v.trim().length > 0;
const isInt = (v: unknown) => Number.isInteger(v);

/**
 * Problems with a node's shape, recursively. Mutates only what has one right
 * answer (`col`/`row` become the child's index) so the model is never asked to
 * spend a round on grid bookkeeping.
 */
export function shapeProblems(node: any, prefix: string, isRoot = true): string[] {
  const out: string[] = [];
  const at = (k: string) => `${node?.id ?? "?"}.${k}`;
  if (!node || typeof node !== "object") return ["node is not an object"];
  if (!isStr(node.id)) out.push(at("id") + " missing");
  else if (!isRoot && !node.id.startsWith(prefix + "-")) out.push(`${node.id}: ids under this root must start with "${prefix}-"`);
  for (const k of ["title", "sub"]) if (!isStr(node[k])) out.push(at(k) + " missing");
  if (!STATES.includes(node.state)) out.push(at("state") + ` must be one of ${STATES.join("/")}`);
  if (node.group && !["sequence", "set"].includes(node.group.ordering)) out.push(at("group.ordering") + " must be sequence or set");
  if (!Array.isArray(node.code)) out.push(at("code") + " must be an array of {file,start,end,label}");
  else node.code.forEach((c: any, i: number) => {
    if (!isStr(c?.file) || !isInt(c?.start) || !isInt(c?.end) || !isStr(c?.label)) out.push(at(`code[${i}]`) + " needs file, start, end (integers), label");
  });
  for (const [i, iss] of (node.issues ?? []).entries())
    if (!isStr(iss?.title) || !isStr(iss?.detail)) out.push(at(`issues[${i}]`) + " needs title and detail");
  for (const [i, b] of (node.anatomy ?? []).entries()) {
    const need = KINDS[b?.kind];
    if (!need) { out.push(at(`anatomy[${i}]`) + ` kind "${b?.kind}" is not one of ${Object.keys(KINDS).join(", ")}`); continue; }
    for (const k of need) if (b[k] === undefined) out.push(at(`anatomy[${i}]`) + ` (${b.kind}) missing ${k}`);
    if (b.kind === "diagram") {
      for (const x of b.boxes ?? []) if (!isStr(x?.id) || !isStr(x?.label) || !isInt(x?.col) || !isInt(x?.row)) out.push(at(`anatomy[${i}]`) + " diagram box needs id, label, col, row");
      for (const a of b.arrows ?? []) if (!isStr(a?.from) || !isStr(a?.to)) out.push(at(`anatomy[${i}]`) + " diagram arrow needs from, to");
    }
    if (b.kind === "table" && (!Array.isArray(b.columns) || !Array.isArray(b.rows) || b.rows.some((r: any) => !Array.isArray(r)))) out.push(at(`anatomy[${i}]`) + " table needs columns: string[] and rows: string[][]");
    if (b.kind === "screen" && (b.items ?? []).some((x: any) => !["heading", "text", "field", "choice", "button", "list", "image"].includes(x?.type)))
      out.push(at(`anatomy[${i}]`) + " screen item type must be heading/text/field/choice/button/list/image");
  }
  if (node.children !== undefined && !Array.isArray(node.children)) out.push(at("children") + " must be an array");
  (node.children ?? []).forEach((c: any, i: number) => {
    if (c && typeof c === "object") { c.col = 0; c.row = i; }
    out.push(...shapeProblems(c, prefix, false));
  });
  if (isRoot) { node.col = 0; node.row = 0; }
  return out;
}

ui/scripts/generate/summarize.ts:
/**
 * Stage 1 — one short, structured reading of every source file (Haiku).
 *
 * The cut sees the whole repo only through these, so they record what a file
 * DOES for the product (what it reads, writes, shows, calls), with line ranges
 * the author can jump to. Keyed by content: an unchanged file is never re-read,
 * which is also what an incremental map will need.
 */

import { ask, MODELS } from "./bedrock";
import { numbered, type Inventory } from "./inventory";

export interface FileSummary {
  path: string;
  purpose: string;
  kind: string;
  symbols: { name: string; start: number; end: number; does: string }[];
  reads: string[];
  writes: string[];
  external: string[];
  user_sees: string;
}

const KINDS = ["screen", "component", "api-route", "server-action", "hook", "state", "data-model", "migration", "query", "lib", "config", "script", "job", "cli", "entry", "types", "other"];

const TOOL = {
  name: "summary",
  description: "Record what this file does.",
  input_schema: {
    type: "object",
    additionalProperties: false,
    required: ["purpose", "kind", "symbols", "reads", "writes", "external", "user_sees"],
    properties: {
      purpose: { type: "string", description: "One plain sentence: what this file does for the product or its caller. Not a restatement of the file name." },
      kind: { type: "string", enum: KINDS },
      symbols: {
        type: "array",
        description: "The functions, components, routes, classes or tables that matter, up to 12, with their exact line ranges as numbered.",
        items: {
          type: "object",
          additionalProperties: false,
          required: ["name", "start", "end", "does"],
          properties: { name: { type: "string" }, start: { type: "integer" }, end: { type: "integer" }, does: { type: "string", description: "A few words." } },
        },
      },
      reads: { type: "array", items: { type: "string" }, description: "Data it reads: tables, collections, storage keys, env vars, cookies, files. Concrete names." },
      writes: { type: "array", items: { type: "string" }, description: "Data it writes, same form." },
      external: { type: "array", items: { type: "string" }, description: "Outside services or HTTP endpoints it calls (Stripe, S3, /api/posts)." },
      user_sees: { type: "string", description: "If it renders UI: what a user sees and can do, in one sentence. Otherwise empty." },
    },
  },
};

const SYSTEM = `You read one source file from a repository and record what it does, for someone mapping the whole codebase.
Be concrete and literal: real table names, real routes, real env var names, real line numbers as shown in the left margin.
Never guess at code you cannot see. Call the summary tool once.`;

/** Larger files are read in their first part only; the summary says so. */
const MAX_LINES = 1500;

export async function summarize(inv: Inventory, onDone: (n: number, of: number) => void): Promise<Record<string, FileSummary>> {
  const todo = inv.files.filter((f) => f.code && !f.test);
  const out: Record<string, FileSummary> = {};
  let n = 0;
  await Promise.all(
    todo.map(async (f) => {
      const cut = f.lines > MAX_LINES ? `\n(Only lines 1-${MAX_LINES} of ${f.lines} are shown.)` : "";
      try {
        const s = await ask<Omit<FileSummary, "path">>({
          model: MODELS.haiku,
          stage: "summarize",
          maxTokens: 4000,
          system: SYSTEM,
          messages: [{ role: "user", content: `Repository: ${inv.name}\nFile: ${f.path} (${f.lines} lines)${cut}\n\n${numbered(inv.repo, f.path, 1, MAX_LINES)}` }],
          tool: TOOL,
        });
        out[f.path] = { path: f.path, ...s };
      } catch (e) {
        // One unreadable file is a gap the cut is told about, not a failed run.
        out[f.path] = { path: f.path, purpose: `(not summarised: ${(e as Error).message.slice(0, 120)})`, kind: "other", symbols: [], reads: [], writes: [], external: [], user_sees: "" };
      }
      onDone(++n, todo.length);
    }),
  );
  return Object.fromEntries(Object.keys(out).sort().map((k) => [k, out[k]]));
}

/** One line per file — the form the cut reads the whole repo in. */
export function oneLine(s: FileSummary): string {
  const io = [
    s.reads.length ? `reads ${s.reads.slice(0, 4).join(", ")}` : "",
    s.writes.length ? `writes ${s.writes.slice(0, 4).join(", ")}` : "",
    s.external.length ? `calls ${s.external.slice(0, 3).join(", ")}` : "",
  ].filter(Boolean).join("; ");
  return `${s.path} [${s.kind}] ${s.purpose}${io ? ` (${io})` : ""}`;
}

/** A file's summary with its symbols, the form an author reads its own files in. */
export function full(s: FileSummary): string {
  const syms = s.symbols.map((x) => `    ${x.start}-${x.end} ${x.name}: ${x.does}`).join("\n");
  return `${oneLine(s)}${s.user_sees ? `\n    user sees: ${s.user_sees}` : ""}${syms ? `\n${syms}` : ""}`;
}

ui/scripts/generate/verify.ts:
/**
 * Stage 4 — does each node's prose hold against the lines it cites?
 *
 * The checker proves a cited range exists; only a reading proves it says what
 * the node claims. Two readers, because one was not enough: Haiku alone
 * flagged claims and in the same breath called them accurate (taxonomy: 18 of
 * 54 nodes downgraded, most wrongly). So Haiku screens every claim with an
 * explicit verdict, and only what it marks contradicted or not shown goes to
 * the author model. That reviewer can search the repository: a true claim
 * whose lines were simply not cited gets the missing code ref (taxonomy's
 * second run downgraded 24 nodes for exactly that), a false one is corrected,
 * and only a claim the repository cannot show at all marks the node `partial`.
 * An issue that is accurate but describes behaviour the code means to have is
 * flagged `intended` and dropped: on flask, a mature library with few real
 * bugs, a third of the issues were documented rules written up as defects.
 */
import type { CodeRef, Node } from "@/lib/data";
import { ask, BACKEND, callsOf, invoke, MODELS, type Block, type Message } from "./bedrock";
import { ccAgent } from "./claude-code";
import { runTool, TOOLS } from "./author";
import { fileReader } from "./check";
import { numbered, type Inventory } from "./inventory";

export interface Verdict {
  id: string;
  ok: boolean;
  flagged: number;
  rewritten: boolean;
  downgraded: boolean;
  claims: string[];
}

const SCREEN = {
  name: "verdicts",
  description: "One verdict per factual claim in the node.",
  input_schema: {
    type: "object",
    additionalProperties: false,
    required: ["claims"],
    properties: {
      claims: {
        type: "array",
        items: {
          type: "object",
          additionalProperties: false,
          required: ["claim", "verdict"],
          properties: {
            claim: { type: "string", description: "The claim, quoted briefly." },
            verdict: { type: "string", enum: ["supported", "contradicted", "not_shown", "intended"], description: "supported: the cited lines show it. contradicted: they show otherwise. not_shown: nothing cited bears on it. intended (issues only): the lines show it, but it is behaviour the code means to have — a documented rule, a deliberate error for misuse, standard language behaviour — not something going wrong." },
            why: { type: "string" },
          },
        },
      },
    },
  },
};

const REVIEW = {
  name: "review",
  description: "Your ruling on the flagged claims, and the node's corrected wording.",
  input_schema: {
    type: "object",
    additionalProperties: false,
    required: ["real", "detail", "issues", "code_labels", "add_refs", "unresolvable"],
    properties: {
      real: { type: "array", items: { type: "string" }, description: "The flags that are right. Empty if every flag is a false alarm." },
      detail: { type: "string", description: "The node's detail, corrected if needed. At most two sentences and 40 words." },
      issues: { type: "array", items: { type: "object", additionalProperties: false, required: ["title", "detail"], properties: { title: { type: "string" }, detail: { type: "string" }, where: { type: "string" } } } },
      code_labels: { type: "array", items: { type: "string" }, description: "One label per existing code ref, same order." },
      add_refs: {
        type: "array",
        description: "Code refs to add for true claims whose lines were not cited — lines you have read.",
        items: { type: "object", additionalProperties: false, required: ["file", "start", "end", "label"], properties: { file: { type: "string" }, start: { type: "integer" }, end: { type: "integer" }, label: { type: "string" } } },
      },
      unresolvable: { type: "string", description: "Only when a claim the node depends on cannot be shown from anything in this repository (it lives in an external service, a deploy setting, an unchecked-in schema): one plain sentence saying what is not certain and why. Otherwise empty." },
    },
  },
};

function evidence(n: Node, inv: Inventory): string {
  return (n.code ?? [])
    .map((c, i) => `[${i}] ${c.label} — ${c.file}:${c.start}-${c.end}\n${numbered(inv.repo, c.file, c.start, Math.min(c.end, c.start + 150))}`)
    .join("\n\n");
}

function claims(n: Node): string {
  return JSON.stringify({ title: n.title, sub: n.sub, detail: n.detail, issues: n.issues ?? [], code_labels: (n.code ?? []).map((c) => c.label) }, null, 1);
}

const words = (s: string) => s.split(/\s+/).filter(Boolean).length;
const sentences = (s: string) => s.split(/(?<=[.!?])\s+(?=[A-Z"`(])/).filter(Boolean).length;

async function verifyNode(n: Node, inv: Inventory, model: string): Promise<Verdict> {
  const v: Verdict = { id: n.id, ok: true, flagged: 0, rewritten: false, downgraded: false, claims: [] };
  type Screen = { claims: { claim: string; verdict: string; why?: string }[] };
  const screenWith = (maxTokens: number) => ask<Screen>({
    model: MODELS.haiku,
    stage: "verify",
    maxTokens,
    system: "You check a short explanation of code against the code it cites. List every factual claim in the detail, issues and code labels, and give each a verdict. Reasonable summary and wording are supported; a fact, behaviour, name or number the lines do not show is not. An issue must be something going wrong; one that describes deliberate behaviour is intended, even when it is accurate.",
    messages: [{ role: "user", content: `## The node\n${claims(n)}\n\n## The cited code\n${evidence(n, inv)}` }],
    tool: SCREEN,
  });
  // A node with many claims can outrun the first answer's room (umami's did);
  // it gets more, and if it still has no answer it is unverified, not fatal.
  let screen: Screen;
  try {
    screen = await screenWith(4000).catch(() => screenWith(16000));
  } catch {
    return { ...v, ok: false, claims: ["the verify screen gave no answer"] };
  }
  const flags = screen.claims.filter((c) => c.verdict !== "supported").map((c) => `${c.claim} — ${c.verdict}${c.why ? `: ${c.why}` : ""}`);
  v.flagged = flags.length;
  if (!flags.length) return v;

  const r = await review(n, flags, inv, model);
  if (!r) return v;
  v.claims = r.real;
  if (!r.real.length) return v;
  // A rewrite that still breaks the length rule is not applied; the node keeps its own detail.
  if (words(r.detail) <= 40 && sentences(r.detail) <= 2) n.detail = r.detail;
  n.issues = r.issues.length ? r.issues : undefined;
  (n.code ?? []).forEach((c, i) => { if (r.code_labels[i]) c.label = r.code_labels[i]; });
  const linesOf = fileReader(inv.repo);
  for (const c of r.add_refs) {
    const lines = linesOf(c.file);
    if (lines && c.start >= 1 && c.start <= c.end && c.end <= lines.length) (n.code ??= []).push(c);
  }
  v.rewritten = true;
  if (r.unresolvable.trim()) {
    n.state = "partial";
    n.unsure = r.unresolvable.trim().slice(0, 300);
    v.downgraded = true;
    v.ok = false;
  }
  return v;
}

interface Review { real: string[]; detail: string; issues: { title: string; detail: string; where?: string }[]; code_labels: string[]; add_refs: CodeRef[]; unresolvable: string }

/** The second reader: may read and grep the repository before ruling. */
async function review(n: Node, flags: string[], inv: Inventory, model: string): Promise<Review | null> {
  const known = new Set(inv.files.map((f) => f.path));
  const tools = [...TOOLS.filter((t) => t.name !== "submit"), REVIEW];
  const system = `You rule on flags a first reader raised against an explanation of code. The first reader saw only the cited lines, so many flags are false alarms or true claims that were simply not cited.
- A false alarm: dismiss it.
- A true claim whose lines were not cited: find them (read_file, grep) and add them in add_refs.
- A wrong claim: correct the wording so every claim is shown by code — never add what the code does not show.
- A claim nothing in this repository can show: say so in unresolvable.
- An issue flagged intended: if the code shows the behaviour is deliberate (a docstring or comment saying so, an explicit raise for misuse, standard language behaviour), drop it from issues. Keep it only if it really makes something go wrong for whoever hits it.
The detail must stay at most two sentences and 40 words. Finish by calling review.`;
  const prompt = `## The node\n${claims(n)}\n\n## Claims a first reader flagged\n- ${flags.join("\n- ")}\n\n## The cited code\n${evidence(n, inv)}`;
  const tooLong = (out: Review) => out.real.length && (words(out.detail) > 40 || sentences(out.detail) > 2);
  const lengthError = (out: Review) => `The detail has ${words(out.detail)} words and ${sentences(out.detail)} sentences; the limit is 40 words and 2 sentences. Call review again.`;

  if (BACKEND === "claude-code") {
    const r = await ccAgent<Review>({
      model, system, prompt, tools, effort: "medium", stage: "verify-review", maxTurns: 10, nudge: "Finish by calling review.",
      handle: (name, input) => {
        if (name !== "review") return { content: runTool({ name, input }, inv, known) };
        const out = input as Review;
        return tooLong(out) ? { content: lengthError(out), isError: true } : { content: "Recorded. Stop now.", done: out };
      },
    });
    return r.value;
  }

  const messages: Message[] = [{ role: "user", content: prompt }];
  for (let turn = 0; turn < 10; turn++) {
    const r = await invoke({ model, stage: "verify-review", effort: "medium", maxTokens: 8000, system, messages, tools });
    messages.push({ role: "assistant", content: r.content });
    const calls = callsOf(r);
    const done = calls.find((c) => c.name === "review");
    if (done) {
      const out = done.input as Review;
      if (tooLong(out) && turn < 9) {
        messages.push({ role: "user", content: [{ type: "tool_result", tool_use_id: done.id, is_error: true, content: lengthError(out) }] });
        continue;
      }
      return out;
    }
    if (!calls.length) { messages.push({ role: "user", content: "Finish by calling review." }); continue; }
    messages.push({ role: "user", content: calls.map((c): Block => ({ type: "tool_result", tool_use_id: c.id, content: runTool(c as { name: string; input: unknown }, inv, known) })) });
  }
  return null;
}

export async function verifyTree(root: Node, inv: Inventory, model: string): Promise<Verdict[]> {
  const nodes: Node[] = [];
  const walk = (n: Node) => { nodes.push(n); (n.children ?? []).forEach(walk); };
  walk(root);
  return Promise.all(nodes.map((n) => (n.code?.length ? verifyNode(n, inv, model) : Promise.resolve({ id: n.id, ok: false, flagged: 0, rewritten: false, downgraded: false, claims: ["no code refs"] }))));
}
